window.JN_CARDS = [{"id":"do-001","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":10,"title":"今天我是你的发球机","body":"投的人只管投，球落到哪儿都有人捡回来、传到手上。10 分钟不用自己追球，比平时能多投一大截。","steps":["投的人站到今天最想投的位置","捡球的人守在篮下，抢到球就传回对方胸前","投的人喊“换点”，两个人一起换位置","10 分钟到，由投的人决定：再来一组，还是换个玩法"],"need":["一个球","一个篮筐"],"hint":"耳机别带，手机静音放球包。只捡球、只传球，不说“手肘收一点”。他进球后回头看你时，你的眼睛得在场上。","refs":[{"t":"The White Hatter 网站 · Darren Laur","u":"https://www.thewhitehatter.ca/post/parents-your-kid-is-looking-for-you-in-the-stands","lv":"个案"}],"art":"ball","tags":["篮球","传球"]},{"id":"do-002","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":10,"title":"让我 2 个球","body":"罚球线上各投 10 个，比谁进得多。开局前先谈判：投得准的那位让对手几个？自己报数，让多了输掉不许反悔。输的人包揽今天所有的捡球。","steps":["两个人站到罚球线，先谈让分：投得准的那位报一个数","让出去的球，直接记在对手账上","猜拳定谁先投，每人 10 个，一人一球轮着投，大声报数","打平就加赛：一人一球，直到分出胜负","输的人今天负责捡球"],"need":["一个球","一个篮筐"],"hint":"让分是你开口向他要的，别反过来说“我让你”。他一个都不肯让，也接着比。输了就认，球捡得认真点。全程不讲投篮姿势。想让手机记数，「工具箱」里的「球场计分板」有罚球赛。","art":"hoop","tags":["篮球","罚球"]},{"id":"do-003","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":20,"title":"给老爸上 3 道锁","body":"半场一对一，先到 7 分赢。开打前，从这 4 条里挑 3 条给老爸戴上：不许盖帽、只用一只手运球、每回合只伸一次手抢断、不许起跳。","steps":["先慢跑 2 圈，活动脚踝和膝盖","说好规则：半场，一球一分，先到 7 分赢","挑锁的人选 3 条，大声宣布","戴锁的人犯了规：自己进的球不算；防守时犯的，直接送对手 1 分","戴锁的人赢了：下一局 4 道全上。输得太惨：对手亲手解一道，再来"],"need":["一个球","一个篮筐"],"hint":"3 道锁就是让分，戴上以后认真打，不用再放水，他看得出来；别仗着块头硬挤。你体力一般，打半场就够。打完不复盘，只说一句“我喜欢看你打球”。","refs":[{"t":"Scott Gibb 的个人通讯","u":"https://scottgibb.substack.com/p/how-to-play-basketball-with-kids-675","lv":"个案"},{"t":"Daniel Coyle 的博客（2013-09-19）","u":"https://danielcoyle.com/2013/09/19/best-parenting-tip-ever/","lv":"专家意见"}],"art":"sneaker","tags":["篮球","一对一"]},{"id":"do-004","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":20,"title":"测一张投篮热区图","body":"像数据网站给球星画的那种：选 5 个点，每个点投 10 个，进 6 个以上标“热”，3 个以下标“冰”。两个人各测一张，看谁的图上冰块多。","steps":["投的人选 5 个点，每个点用脚尖点一下地","每个点投 10 个，另一个人捡球、报数","5 个数字记进手机备忘录，标上“热”或“冰”，写上日期","换人再测一张，数字再难看也照记","下个月同一块场地再测，看哪块冰化了"],"need":["一个球","一个篮筐","手机备忘录"],"hint":"数字只记不评，不拿来考核，也不拿去跟别人比。你那张多半全是冰，照实记，让他笑。记完手机放回包里。","art":"target","tags":["篮球","投篮","热区图"]},{"id":"do-005","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":10,"title":"慢动作，一人 5 个","body":"用手机的慢动作拍 5 次出手，坐到场边回放。播放键在被拍的人手里，留哪条、删哪条，本人说了算。然后换人：摄影师也得被拍 5 个。","steps":["手机调到慢动作，站到投篮的人侧面三四步远","连拍 5 次出手，进不进都拍","坐到场边回放，播放键交给被拍的人","换人：摄影师也去投 5 个，照样拍，照样回放","各自的片子各自处置：留哪条、删哪条，本人说了算"],"need":["一个球","一部手机"],"hint":"回放时一句动作要领都别讲；他不开口，你也别问“看出什么了”。你那 5 个再难看也留给他笑。拍完手机放回包里。","art":"camera","tags":["篮球","视频"]},{"id":"do-006","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":10,"title":"10 分钟包教包会","body":"挑一个只有一方会的动作：胯下运球、欧洲步、背后传球都行。会的人当教练，10 分钟包教。教不会，算学生笨。","steps":["先一起慢跑一圈、活动脚踝；教练挑一个动作，完整做一遍","学生照着做，做错了由教练喊停","教练把动作拆成两三步，一步一步带","10 分钟后验收：学生连做 3 次，教练打分","学生当场在一对一里用一次，用得再丑也用"],"need":["一个球"],"hint":"真学，学得笨一点正好。他怎么教你就怎么做，别反过来纠正他，也别说“这招比赛里用不上”。","refs":[{"t":"Scary Mommy · Clint Edwards","u":"https://www.scarymommy.com/hated-sports-child-started-playing","lv":"个案"}],"art":"whistle","tags":["篮球","让他教你"]},{"id":"do-007","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":40,"title":"这场球，讲给外行听","body":"挑一场今天的比赛，回放或者一段 20 分钟的集锦也行。懂球的人当讲解，另一个人当第一次看球的观众，什么都可以问。","steps":["讲解的人挑比赛：看哪两队，看全场还是只看最后一节","开场前讲解的人先交代：今天该盯着谁看","观众只管提外行问题：刚才为什么吹哨？","看完各评一个：全场最佳，和最好笑的一瞬间"],"hint":"你就是那个不懂球的观众，问得越外行越好。他讲错了也别纠正，更别借球星的故事讲“人家多努力”。","refs":[{"t":"澎湃号 · “大虎爸爸”的自述","u":"https://www.thepaper.cn/newsDetail_forward_24562966","lv":"个案"}],"art":"scoreboard","tags":["篮球","看球"]},{"id":"do-008","type":"do","sub":"出游","format":"steps","audience":"all","for":"kid","scenes":["周末","出游"],"mins":180,"title":"去现场看一场球","body":"北京有职业球队的主场。看哪一场、坐哪一档、怎么去，都由懂球的那位定。大人只负责给一个总预算，然后跟着走。","steps":["现在就打开赛程，挑一场主场比赛；休赛期就先挑下赛季的","大人报出总预算，挑的人据此选座位档","挑的人查好：怎么去、几点出门","比赛进行时手机只拍照，中场休息随意","散场后直接回家还是先去吃点东西，挑场次的人定"],"hint":"他选的场次和座位你别改，超预算就让他自己重选。看台上别讲解，你才是外行。回家路上只聊比赛，不点评他。","refs":[{"t":"美国汽车协会（AAA）的出行建议","u":"https://cluballiance.aaa.com/the-extra-mile/advice/travel/how-to-plan-a-family-vacation-with-your-kids","lv":"专家意见"},{"t":"《宁波晚报》报道（人民日报客户端转载）","u":"https://www.peopleapp.com/rmharticle/30051410968","lv":"个案"}],"art":"jersey","tags":["篮球","看球","北京"]},{"id":"do-009","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":90,"title":"叫上你的人，我管后勤","body":"周末约球，叫上同学，凑够人就开打。大人负责带水、看包，缺一个人的时候才上场凑数，人齐了立刻下场。","steps":["现在就定时间和场地，约球的人去问同学来不来","大人备好水，把球打足气","到场先一起热身、传球，等人到齐","人齐了大人退到场边管水和包；要走开，先说清“我几点回来”","大人说几点回来就几点出现，一分钟也别晚"],"need":["一个球","够几个人喝的水"],"hint":"他和同学打起来了就真的退开：不喊战术，不当裁判，别在场边大声叫好，他同学都听着呢。想走开去跑步就明说；留在场边就别刷手机。","refs":[{"t":"北京日报客户端（2025-05-29）","u":"https://news.bjd.com.cn/2025/05/29/11179764.shtml","lv":"个案"}],"art":"highfive","tags":["篮球","同学"]},{"id":"do-010","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":10,"title":"今天只准用笨手","body":"运球、上篮、投篮，全部换成不顺的那只手。两个人会一起退回刚学球的样子。篮下谁先用笨手投进 3 个，谁赢。","steps":["各自亮出自己的“笨手”","先用笨手运球绕半场一圈，掉球不算丢人","站到篮下，轮流用笨手投","谁先投进 3 个，谁赢","输的人用笨手给赢的人拧开水瓶"],"need":["一个球","一个篮筐"],"hint":"这个玩法里你们一样笨，正好。你投得难看就让他笑，别顺口来一句“你左手是该多练练”。","art":"ball","tags":["篮球","左手"]},{"id":"do-011","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":15,"title":"投进才能往前走","body":"篮筐周围定 5 个点。站在第一个点投，进了才能去下一个点，没进就原地等下一轮。谁先走完 5 个点谁赢。点在哪儿，投得准的那位定。","steps":["定点的人选 5 个点，由近到远还是乱着来，随他","从第一个点开始，一人一球轮着投","投进：前进到下一个点；没进：原地等下一轮","最先在第 5 个点投进的人获胜","输的人想翻盘，可以申请“再走一圈”"],"need":["一个球","一个篮筐"],"hint":"点位他定，定得再刁钻也照办。你在同一个点卡了 5 轮也别找借口，认了就是。","refs":[{"t":"传统投篮游戏“环游世界”（Around the World）","lv":"经典"}],"art":"hoop","tags":["篮球","投篮"]},{"id":"do-012","type":"do","sub":"球场","format":"steps","audience":"all","for":"kid","scenes":["球场","周末"],"mins":10,"title":"最后 5 秒，再来一遍","body":"落后 1 分，还剩 5 秒。一个人演绝杀的英雄，另一个人演防守的倒霉蛋，兼任读秒员和现场解说。没进？“裁判回看，时间还剩 2 秒。”","steps":["先各投几个热热身；主角定剧本：哪两队、差几分、从哪儿接球","配角把球传过去，大声倒数“5、4、3……”","主角出手，配角配上现场解说","进了：配角就地表演被绝杀；没进：“回看录像”，重来","换人，另一位也当一回主角"],"need":["一个球","一个篮筐"],"hint":"演得越投入越好；场上有他认识的人，就把音量收到只有他听得见。他没投进别安慰，直接“回看录像”让他再来。倒地表演慢一点，别真摔。","art":"trophy","tags":["篮球","绝杀"]},{"id":"do-013","type":"do","sub":"厨房","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":60,"title":"做一道都没做过的菜","body":"挑一道两个人都没做过的菜，现查菜谱、现买菜、现翻车。好不好吃不重要，能端上桌就算赢。","steps":["现在就各提名一道菜，猜拳定做哪道","对着菜谱看冰箱，缺的列成清单一起去买","分工：切和灶台归大人；洗、拌、调味、念菜谱归另一位","照着菜谱一步步做，每一步都大声念出来","上桌先拍照，再同时下第一筷子"],"need":["一份菜谱","2 条围裙"],"hint":"不追求好吃，也别借机派家务。做砸了，第一个笑的人应该是你。手机只用来看菜谱。","refs":[{"t":"光明网科普 · 王葵（2026-09-11）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"}],"art":"pan","tags":["做饭","新手"]},{"id":"do-014","type":"do","sub":"厨房","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":45,"title":"今晚你是主厨","body":"今晚吃什么、几个菜、谁干什么，主厨说了算。大人是帮厨，只负责三件事：切菜、看火，和回答“是，主厨”。","steps":["主厨宣布今晚的菜单：几个菜，哪道是招牌","主厨排工序：先做哪道、几点开饭，帮厨复述一遍","刀和灶台上的活归帮厨，调味和摆盘归主厨","出锅前主厨尝味，说加盐就加盐","吃完主厨给帮厨打分：刀工几分，听指挥几分"],"hint":"他定的菜单再怪也照做，番茄炒蛋配薯条也行。掌勺时别自作主张加料，别说“应该先放油”。他下指令，你就回“是，主厨”。","refs":[{"t":"光明网科普 · 王葵（2026-09-11）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"}],"art":"pan","tags":["做饭","他做主"]},{"id":"do-015","type":"do","sub":"厨房","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"蒙上眼，猜这是啥","body":"一个人蒙上眼，另一个人从厨房挑 5 样能直接吃的，一小勺一小勺地喂，猜对一样得 1 分。规矩：喂过别人的，自己也得各吃一勺。然后换人，有仇报仇。","steps":["猜拳，输的人先蒙眼","出题的人挑 5 样能直接吃的，带酒的不上，每样一小勺","猜的人可以闻，每样可以问一个问题","5 样过完摘眼罩：出题的人把这 5 样自己各吃一勺","换人再来，分数低的那位洗勺子"],"need":["眼罩或围巾","几把小勺"],"hint":"只挑他不过敏、能直接入口的。他整了你，你也别拿芥末辣椒报复一个蒙着眼的人。轮到你蒙眼，他喂什么你吃什么，反正他自己也得吃。","art":"question","tags":["盲尝","挑战"]},{"id":"do-016","type":"do","sub":"厨房","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":40,"title":"不许买菜的一顿饭","body":"不许出门买任何东西。只用冰箱和橱柜里现有的，拼出一顿能吃的饭，再给它起一个听上去很贵的名字。","steps":["打开冰箱和橱柜，把能用的全摆上台面","两个人对着这一堆商量：能拼成什么","切和开火归大人，搭配和调味听另一位的","给成品起个菜名，越像高级餐厅越好","拍一张“菜单照”，发到家里的群"],"hint":"他的搭配再黑暗也先做出来，别说“这两样不能一起炒”，让锅来回答。真难吃就一起笑，再煮包面。","art":"pan","tags":["做饭","冰箱"]},{"id":"do-017","type":"do","sub":"厨房","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"终极三明治对决","body":"每人用家里现有的东西做一个三明治，做完交换：你吃我做的，我吃你做的。同时咬第一口，盯着对方的脸，谁先绷不住谁输。","steps":["把面包和所有能夹的东西摆上桌","需要切的，大人先统一切好","限时 5 分钟，各做各的，不许偷看","交换，同时咬第一口，盯着对方的脸","谁先皱眉或笑场谁输，输的人洗盘子"],"need":["面包片","冰箱里能夹的东西"],"hint":"他往你那份里夹了奇怪的东西，吃一口再说。你给他做的别太“健康”，也别真整他：这是对决，不是营养餐，更不是报复。","art":"pizza","tags":["早餐","对决"]},{"id":"do-018","type":"do","sub":"厨房","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":30,"title":"包一个最丑的饺子","body":"家里包饺子的那天，每人另包 3 个“特别款”：形状随便，越怪越好。下锅见真章：谁的怪饺子煮完还没破，谁赢。","steps":["洗手上桌，先看别人怎么包两个","正常的照包，每人另包 3 个“特别款”，各包各的","给自己的特别款做个记号：捏个角，或者按个指印","下锅和捞饺子归大人","捞出来清点：完好的特别款多的人赢，破了的自己吃"],"need":["饺子皮","饺子馅"],"hint":"别教他“正确”的捏法，煮漏了也算他的作品。你包的那 3 个也别太好看。","art":"table","tags":["饺子","冬至","过年","冬"]},{"id":"do-019","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":20,"title":"夜跑：谁先喊“等等我”","body":"夏天的晚上，天黑后下楼跑一圈（刚吃完饭先歇半小时）。路线、速度、在哪儿折返，都由领跑的人定。跟跑的人每喊一次“等等我”记一笔，满 3 笔请喝水。","steps":["换鞋下楼，原地活动 2 分钟脚踝和膝盖","腿脚快的那位领跑，定方向","走人行道和公园步道，过路口先停下看车","跟跑的人每喊一次“等等我”，记一笔","跑到领跑的人说停为止；满 3 笔的人请喝水"],"hint":"这是一段路，不是训练。不计时，不说“再坚持一下”，更别拿跑步当惩罚或交换条件。你喘了就喊“等等我”，认罚就是。","refs":[{"t":"北京日报客户端（2025-05-29）","u":"https://news.bjd.com.cn/2025/05/29/11179764.shtml","lv":"个案"}],"art":"moon","tags":["跑步","夜跑","夏"]},{"id":"do-020","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":60,"title":"骑到哪儿算哪儿","body":"骑车出门，每到一个路口，由骑在前面的人决定左转、右转还是直行。骑满 20 分钟停下来，看看到了哪儿，再想办法骑回家。","steps":["检查刹车和车胎，戴好头盔","带路的人骑前面定方向，大人跟在后面","只走非机动车道，红灯停，过大路口下车推行","20 分钟后停车，找地方买瓶水","回程由带路的人凭记忆走，记不清再看导航"],"need":["2 辆自行车","2 顶头盔"],"hint":"方向全听他的，拐进死胡同也别提醒。你只管一件事：交规和安全，这条没得商量。别在后面喊一路“慢点”。","refs":[{"t":"《道路交通安全法实施条例》第七十二条：骑自行车上路须年满 12 周岁","lv":"官方"}],"art":"bike","tags":["骑车","春","秋"]},{"id":"do-021","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末","出游"],"mins":180,"title":"这座山你当队长","body":"秋天，在北京周边挑一座半天能上下的小山。走哪条路、在哪儿歇、几点开吃，队长说了算。队员只有一个，负责背水。","steps":["今晚一起看地图，队长挑一座入门难度的山","队长列背包清单：水、吃的、外套；再定一个必须往回走的时间","只走有台阶和路标的正规步道","岔路口队长选方向，队员跟着","到折返点拍张照，姿势由队长定"],"need":["水和零食","防滑的鞋"],"hint":"他带错了路，只要还在正规步道上就先跟一段，等他自己发现；要离开步道，或者过了折返时间，直接叫停。别一路问“累不累”。他想叫同学就叫，跟对方家长说一声。","refs":[{"t":"北京日报客户端（2025-05-29）","u":"https://news.bjd.com.cn/2025/05/29/11179764.shtml","lv":"个案"}],"art":"mountain","tags":["徒步","爬山","秋","北京","假期"]},{"id":"do-022","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":90,"title":"冰场上，数数谁摔得多","body":"冬天找一块正规的冰场，两个人都穿上冰鞋。各数各摔了几次，摔得多的人请热饮。扶着栏杆摔的不算，松了手摔的才记数。","steps":["现在就查一块正规冰场（室内的，或公园里售票开放的），不上野冰，定这周哪天去","穿好冰鞋，戴上手套、头盔和护膝护腕（冰场一般能租）","先扶着栏杆走一圈，再试着松手","各数各的摔跤次数，如实上报","下冰后，摔得多的人请热饮"],"need":["手套","厚袜子","头盔和护具（可租）"],"hint":"你多半比他先摔，摔了就笑，别逞强，也别喊“太危险了回去吧”。他滑得比你好，就请他带你一段。","art":"skate","tags":["滑冰","冬","新手"]},{"id":"do-023","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"飞盘 20 次不落地","body":"找块空地对扔飞盘，目标是连续接住 20 次不落地。掉了就从零数起。每接够 5 次，两个人各退一大步。","steps":["找一块周围没人的空地，相隔五六步站好","对扔，接住一次大声数一个数","掉地就归零，重新数","每连续接住 5 次，各退一大步","到 20 次算通关，再试试只用单手接"],"need":["一个飞盘"],"hint":"掉了就一起喊“归零”，别分是谁的责任。他想改规则，比如只准单手接，就按他的来。","art":"tree","tags":["飞盘","春","夏"]},{"id":"do-024","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":40,"title":"谁先放上天，谁起名","body":"春天风大，带一只风筝去空旷的地方。轮流当放线的人，另一个人帮忙举着。从离手算起，谁先让它在天上稳稳待满 1 分钟，谁给它起名字。","steps":["看一眼天气预报：这周哪天下午有风","找一块允许放风筝的空地：没有电线和大树，离马路远","一个人举着风筝迎风站，另一个人拉线后退，喊“放”","栽下来就换人放，另一个人掐表","先稳稳飞满 1 分钟的那位，给风筝起名"],"need":["一只风筝"],"hint":"飞不起来别急着接手，让他多试几次；你试了也飞不起来更好。线缠住了一起解，不怪人。","art":"kite","tags":["风筝","春"]},{"id":"do-025","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":20,"title":"领先的人喊水果","body":"羽毛球打到 11 分。只加一条怪规则：谁领先，谁每次击球前都得喊出一种水果，整场不许重复。喊不出来或者喊重了，这一分归对方。","steps":["找块空地，没有网就在地上放 2 个包当中线","先随便打几拍，活动开肩膀和手腕","从零比零开始，一球一分","领先的人每次击球前喊一种水果，整场不许重复","喊不出、喊重了，这一分归对方；先到 11 分的人赢"],"need":["2 支球拍","几个羽毛球"],"hint":"这条规则会让领先的人手忙脚乱，你不用故意放水。他想把水果换成球星的名字，就换。","art":"sun","tags":["羽毛球"]},{"id":"do-026","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":120,"title":"找一样咱俩都不会的","body":"轮滑、乒乓球、台球、保龄球、滑板……挑一样两个人都没正经玩过的，去体验一次。规矩只有一条：谁也不许假装会。","steps":["各写 3 样“想试但不会”的，同时亮出来","有重合的就定它；没有，就猜拳，赢的人从对方的 3 样里挑","查附近哪里能体验，约好日子","去的那天，护具该戴的戴全，两个人从同一个新手起点开始","回来路上，各说一个对方最好笑的瞬间"],"hint":"你和他在同一条起跑线上，学得比他慢更好。别半路改当他的教练，也别拍他出糗的视频发群里，除非他同意。","refs":[{"t":"Grown and Flown 网站的一篇自述","u":"https://grownandflown.com/mom-found-way-bond-with-teen-son/","lv":"个案"},{"t":"Aron 等（2000），Journal of Personality and Social Psychology","u":"https://pubmed.ncbi.nlm.nih.gov/10707334/","lv":"实证"}],"art":"seedling","tags":["新手","一起学","假期"]},{"id":"do-027","type":"do","sub":"户外","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":20,"title":"下雪了，现在就下楼","body":"北京一年下不了几场雪，下了就别等。穿上外套下楼：堆一个不像雪人的东西，再找棵树当靶子，比谁的雪球扔得准。","steps":["现在就穿外套、戴手套下楼","猜拳赢的人定堆什么：越不像雪人越好","分头滚雪，10 分钟后合体","找一棵树当靶子，每人 10 个雪球比命中","拍一张合影，脸冻红了也拍"],"need":["手套","防滑的鞋"],"hint":"别说“太冷了改天吧”，雪不等人。他朝你扔雪球就扔回去，下手轻点，不砸脸。","art":"snow","tags":["下雪","冬","北京"]},{"id":"do-028","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"纸飞机，比谁飞得远","body":"每人 3 张纸，折法不限，可以现查教程。在走廊里比 3 轮，飞得最远的那架留下，签上名贴到门上。","steps":["每人拿 3 张纸，各折各的，不许看对方","走廊一头摆一只拖鞋，当起飞线","一人一架轮着飞，落点各用一只袜子做记号","3 轮过后，飞得最远的那架获胜","冠军飞机签上名，贴在赢家的房门上"],"need":["几张 A4 纸","一支笔"],"hint":"他折得再怪也别上手帮他改。你那架飞不远就认输，再问问他是怎么折的。","art":"paper-plane","tags":["纸飞机","下雨天"]},{"id":"do-029","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末","出游"],"mins":20,"title":"一副牌，规则你定","body":"拿出一副扑克，交给家里最会玩的那位：接竹竿、争上游，或者和同学玩的那种，玩什么由他定。不会的人现学，输的人洗牌。","steps":["找出一副扑克，定规则的人洗牌","先打一局“教学局”，把规则讲清楚","正式打 3 局，每局输的人洗牌","第 2 局开始前，定规则的人可以临时加一条“家规”","3 局 2 胜，输的人给赢的人倒杯水"],"need":["一副扑克"],"hint":"他讲的规则前后矛盾也先照打，别抬杠。输了就认，别说“我让着你呢”。手机扣在另一个房间。","art":"cards","tags":["扑克","纸牌"]},{"id":"do-030","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"10 秒一步的快棋","body":"家里有什么棋就下什么棋，只加一条规则：每步最多想 10 秒，对手负责大声倒数。超时了，这一步由对手替你走。","steps":["找出棋盘摆好；没有棋，就在纸上画格子下五子棋","说好：每步 10 秒，对手倒数","超时的人，这一步由对手替他走","下完一盘，输的人摆棋","再来一盘，输的人可以改一条规则"],"need":["一副棋，或纸和笔"],"hint":"倒数别故意念快，他想的时候别支招。被他替你走了一步臭棋，笑着认。手边没有棋，「工具箱」里有「五子棋」。","art":"chess","tags":["下棋","象棋","五子棋"]},{"id":"do-031","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":30,"title":"把它修好，或者拆明白","body":"家里总有一样坏了没人管的小东西：不走的闹钟、失灵的遥控器、不亮的手电。今天两个人把它拆开：修得好算赚到，修不好，也看明白了里面长什么样。","steps":["一起在家里转一圈，找一样用干电池的坏东西","先取出电池；插电的、带充电电池的一律不拆","一个人拿螺丝刀，另一个人扶稳、递工具、打手电","拆下来的零件按顺序摆成一排，拍张照","试着装回去：能响能亮算修好，装不回去就留一个零件当纪念"],"need":["小螺丝刀","手电筒"],"hint":"螺丝刀交给他，你当助手。他拧反了方向先别说，让他自己发现。修不好不丢人，别最后自己三两下搞定。","art":"key","tags":["修理","拆东西","动手"]},{"id":"do-032","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":30,"title":"总工与学徒","body":"家里那盒没拼的模型、没装的小书架、没拆封的积木，今天开工。拿图纸的人是总工，另一个人是只会递零件的学徒。","steps":["拆开盒子，零件按形状分堆","总工看图纸下口令，学徒照口令递零件、扶稳","装错了，拆不拆由总工决定","不必一次拼完，拼到总工喊停","没拼完的摆在显眼的地方，下次接着干"],"hint":"你看出哪步装错了，只说一句“总工，要不要对一下图纸？”他说不用就继续。别把活抢过来自己干。","art":"puzzle","tags":["拼装","模型","积木"]},{"id":"do-033","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":20,"title":"给一只旧拖鞋拍广告","body":"在家里找一样最不起眼的旧东西：一只拖鞋、一个掉漆的杯子。给它拍一条 30 秒的“高端产品广告”，文案越夸张越好。","steps":["各自在家里找一样最破的东西，猜拳二选一","一个人当导演：定广告词，定镜头","另一个人当配音和手模，照脚本演","用手机拍，最多拍 3 遍","晚饭时“全球首映”，请妈妈当第一位观众"],"need":["一部手机","一样旧东西"],"hint":"他让你用播音腔念多肉麻的词，你都照念。别嫌幼稚。成片发不发、发给谁，由导演定。","art":"film","tags":["拍视频","搞怪"]},{"id":"do-034","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":10,"title":"我说你画，不许回头","body":"两个人背对背。一个人看着一张图用嘴描述，另一个人照着画，不许问、不许回头。2 分钟后把两张图摆在一起，看差了多远。","steps":["各拿纸笔，背对背坐好","描述的人从书里或相册里挑一张图","只许说形状和位置，不许说“这是什么”","2 分钟到，两张图并排亮出来","换人再来，画得更离谱的那张贴冰箱"],"need":["纸和笔","一张图"],"hint":"你画得越离谱越好，别辩解“是你没说清楚”。轮到你描述时挑张简单的，别成心难他。","art":"pencil","tags":["画画","盲画"]},{"id":"do-035","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":10,"title":"叠杯子，掐表","body":"10 个纸杯，叠成 4、3、2、1 的金字塔，再一把收回成一摞。掐表，看谁快。每比完一轮，输的人可以给赢的人加一条限制。","steps":["找 10 个纸杯或塑料杯，摞成一摞","一个人叠，另一个人用手机秒表计时","叠成 4、3、2、1 的金字塔，再收回一摞，停表","每人 3 次，取最快的一次","输的人给赢的人加一条限制（比如只用一只手），再比"],"need":["10 个纸杯","手机秒表"],"hint":"他给你加的限制再过分也接受。你要是赢了别讲技巧，除非他问。","art":"stopwatch","tags":["叠杯","计时"]},{"id":"do-036","type":"do","sub":"在家","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"家里的技术支持上岗","body":"电视搜不到台、打印机连不上、大人的手机存满了……家里总有一样设备没人搞得定。交给家里最懂的那位，15 分钟收拾一样。怎么弄，技术支持说了算。","steps":["大人说出家里最烦人的一样设备问题","技术支持来查、来设（只动设置，不拆机器），大人坐旁边看","问到“这个要不要关”，大人只回答，不抢着动手","弄好以后教一遍：下次自己怎么弄","技术支持开出诊费：这一单收什么由他定，一瓶饮料起步"],"hint":"这件事得是你真搞不定的，别演。他设的和你的习惯不一样，先用一周再说。诊费照付。之后有人问起，照实说“这是他弄好的”。","refs":[{"t":"UCLA 新闻室 · Fuligni 的综述","u":"https://newsroom.ucla.edu/stories/adolescents-have-a-fundamental-need-to-contribute","lv":"专家意见"}],"art":"bulb","tags":["技术支持","让他教你"]},{"id":"do-037","type":"do","sub":"创作","format":"steps","audience":"all","for":"kid","scenes":["周末","出游"],"mins":20,"title":"3 张特写，认得出算我输","body":"去同一个地方：楼下、球场、菜市场都行。分头走 10 分钟，每人拍 3 张怼近了的特写，越认不出来越好。集合后互相猜，对方猜不出，拍的人得 1 分。","steps":["定好地点和集合时间","分头走，每人只拍 3 张特写，多一张都不行","集合，各举各的手机给对方看，手机不离手","每张可以猜 3 次，猜不出来，拍的人得 1 分","分低的人跟着去看：对方最难猜的那样东西到底在哪儿"],"need":["各自的手机"],"hint":"他拍得再糊再怪也认真猜，别评构图。看照片时别接过他的手机，更别往旁边划。","art":"camera","tags":["拍照","摄影","特写"]},{"id":"do-038","type":"do","sub":"创作","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":30,"title":"剪一条你的十佳球","body":"把手机里拍过的打球视频翻出来，挑出最好的几个球，剪成一条 30 秒的集锦。哪个球压轴、配什么音乐，由打球的人定。","steps":["打球的人自己翻相册，挑出想用的片段","排顺序：哪个开场，哪个压轴","用手机自带的剪辑功能剪，另一个人只在被问到时帮忙","选音乐，起片名","成片先发到家里的群；要不要发给同学，打球的人自己定"],"need":["存着视频的手机"],"hint":"相册由他自己翻，你别凑过去划。选哪个球由他定，剪得粗糙没关系，别上手替他修。发到哪儿他说了算。","refs":[{"t":"澎湃号 · “大虎爸爸”的自述","u":"https://www.thepaper.cn/newsDetail_forward_24562966","lv":"个案"}],"art":"film","tags":["篮球","集锦","剪辑"]},{"id":"do-039","type":"do","sub":"创作","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"录一期 10 分钟的播客","body":"手机打开录音，放在两个人中间。题目由主播定：本周最离谱的 3 件事、谁才是历史最佳、最难吃的菜排行榜。聊满 10 分钟就收工。","steps":["话多的那位当主播，定节目名和这一期的题目","打开手机录音，主播说开场白","主播主讲，另一个人只当捧哏：“然后呢？”“不会吧？”","10 分钟到，主播说结束语","一起听 30 秒回放，留不留由主播定"],"need":["一部手机"],"hint":"他是主播，你是捧哏：多接“然后呢”，少发表高见。别把话题拐到学习上。录音别外传，除非他同意。","art":"chat","tags":["播客","录音"]},{"id":"do-040","type":"do","sub":"创作","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":15,"title":"画一套你的绝杀战术","body":"一张纸画半个球场，5 个圈是进攻，5 个叉是防守。设计一套最后一攻的战术，给它起个代号，再讲给新来的队员听。","steps":["拿纸笔画半场：三分线、罚球线、篮筐","设计的人摆好 5 个圈、5 个叉","画出跑位和传球路线，讲一遍","新队员只问 2 句：“我是哪个圈？我往哪儿跑？”","下次去球场，两个人把这套战术走一遍"],"need":["纸和笔"],"hint":"你是被教的新队员，听不懂就问，别挑战术的毛病。他起的代号再中二，你也照叫。","art":"whistle","tags":["篮球","战术板"]},{"id":"do-041","type":"do","sub":"创作","format":"steps","audience":"all","for":"kid","scenes":["周末"],"mins":5,"title":"标题党大赛","body":"看完一场球，轮流用“震惊体”给它起标题：“震惊！某某全场只干了一件事……”一人一个接着喊，中英混搭也算。谁先接不上，或者先笑场，谁输。","steps":["比赛一结束就开始，猜拳定谁先喊","一人一个轮着来，必须用播音腔","标题得跟这场球沾边，越夸张越好","谁先接不上、先笑场，谁输","输的人把对方最绝的那个标题发到家里的群"],"hint":"你是参赛选手，不是语文老师：不纠正用词，不评好坏。他喊的英文你听不懂就请他翻译，别假装听懂。","art":"abc","tags":["篮球","标题党","英语"]},{"id":"do-042","type":"do","sub":"出游","format":"steps","audience":"all","for":"kid","scenes":["出游","周末"],"mins":240,"title":"开学前最后半天，归你管","body":"开学前最后一个周末，留出半天：去哪儿、怎么去、吃什么，全归策划人定。策划人不能是大人；大人只给一个总预算，花超了，策划人自己想办法砍。","steps":["现在就定日子，大人报出预算总数","策划人查 3 样：去哪儿、怎么去、吃什么，各要花多少","把计划写成 3 行，发给同行的人","当天策划人带路、管时间，其他人跟着","钱有剩，怎么处理由策划人定"],"hint":"计划哪怕是“吃两顿快餐加逛一家店”也照办。别在预算外偷偷加钱，别中途“优化”路线。超支了让他自己砍项目。全程不提“该收心了”。","refs":[{"t":"美国汽车协会（AAA）的出行建议","u":"https://cluballiance.aaa.com/the-extra-mile/advice/travel/how-to-plan-a-family-vacation-with-your-kids","lv":"专家意见"},{"t":"《宁波晚报》报道（人民日报客户端转载）","u":"https://www.peopleapp.com/rmharticle/30051410968","lv":"个案"}],"art":"map","tags":["策划人","预算","他做主","假期","开学"]},{"id":"do-043","type":"do","sub":"出游","format":"steps","audience":"all","for":"kid","scenes":["出游","周末"],"mins":30,"title":"你带路，我殿后","body":"从出门到目的地，导航在带路的人手里：走哪个口、坐哪趟车，都听他的。另一个人跟在后面 3 步远，走错了也跟着错。","steps":["出门前说清目的地，导航交给带路的人","带路的人走前面，跟的人不看自己的手机","换乘、出站口、走哪条街，都由带路的人判断","走错了，跟的人不出声，等带路的人自己发现","到了以后，跟的人请带路的人喝一瓶水"],"hint":"忍住别说“应该走那边”，绕远了就当多走几步。只有涉及安全（闯红灯、走机动车道）才开口。","refs":[{"t":"《宁波晚报》报道（人民日报客户端转载）","u":"https://www.peopleapp.com/rmharticle/30051410968","lv":"个案"}],"art":"compass","tags":["导航","带路"]},{"id":"do-044","type":"do","sub":"出游","format":"steps","audience":"all","for":"kid","scenes":["出游"],"mins":10,"title":"你一项，我一项","body":"出门前，每人只报一样“这趟最想做的事”。报了的一定做到，谁也不许否决别人的。其余的都算赠品，做不成不可惜。","steps":["现在就各写一样这趟最想做的事，同时亮出来","排行程时先放这几样，别的往后排","做别人那一项时全程参与，手机只拍照","轮到自己那一项，别人同样配合","谁的那一项最后没做成，下次出门由他先挑"],"hint":"他选的哪怕是“在酒店打一下午游戏”也算数，别讨价还价。你自己也认真选一项，别说“我都行”。妈妈同去，她也有一项。","refs":[{"t":"Travel Lemming 旅行网站","u":"https://travellemming.com/perspectives/my-kids-help-plan-our-family-trips/","lv":"个案"}],"art":"flag","tags":["旅行","必选项"]},{"id":"do-045","type":"do","sub":"出游","format":"steps","audience":"all","for":"kid","scenes":["出游"],"mins":30,"title":"路上找齐 5 样东西","body":"走路、坐地铁、坐高铁的路上玩。出发前，每人给对方列 5 样“今天路上必须找到的东西”：穿球衣的人、一只柯基、带数字 8 的车牌。谁先找齐谁赢。","steps":["各给对方出 5 样，记在手机备忘录里","互相过目：太离谱的可以驳回一样，重出","路上看到了要指给对方看，才算数；谁在开车谁不参加","到目的地时比谁找到的多","输的人背包"],"hint":"他给你出的题再刁也接着。你开车时别玩这个，专心看路；换成走路、坐地铁的时候再比。","art":"magnifier","tags":["观察","路上"]},{"id":"do-046","type":"do","sub":"出游","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","出游"],"mins":2,"title":"猜猜几点几分到","body":"现在每人报一个到达时间，精确到分钟，不许照抄导航，报完不许改口。到了以后，差得多的人下车拎包。开车的人为了赢改车速，直接判负。","hint":"你开车就只报数，导航该看照看，别为了赢开快车或故意磨蹭。他猜得比你准就认，别说“都怪那个红灯”。","art":"car","tags":["车上","猜时间"]},{"id":"do-047","type":"do","sub":"出游","format":"plain","audience":"all","for":"kid","scenes":["救场","出游","车上"],"mins":5,"title":"最坑的一段，最值的一段","body":"回家路上，每人报两样：今天最坑的一段，和最值的一段。只说一个词也行。别人不许点评，不许反驳。","hint":"你先报，报具体的，比如“你带错路那段最值”。他只蹦一个词也算数，别追问，也别顺势总结今天。","refs":[{"t":"Travel Lemming 旅行网站","u":"https://travellemming.com/perspectives/my-kids-help-plan-our-family-trips/","lv":"个案"}],"art":"chat","tags":["回程","吐槽"]},{"id":"do-048","type":"do","sub":"出游","format":"steps","audience":"all","for":"kid","scenes":["周末","出游"],"mins":90,"title":"地铁盲盒：坐 3 站下车","body":"进地铁站，随便选一条线、一个方向，坐 3 站就下车。出站后有 15 分钟，任务是找到一样值得拍下来的东西，和一样没吃过的零食或小吃。","steps":["现在出门，走到最近的地铁站","猜拳赢的人选线路和方向，数 3 站下车","从哪个口出站也由选线的人定，出站后定 15 分钟的闹钟","各找一样值得拍下来的东西","合买一样没吃过的东西（便利店里的也算），分着吃","回程路上给这一站打分，满分 10 分"],"hint":"下车的地方可能很无聊，那就一起吐槽它，这也算玩到了。别悄悄把目的地换成你想去的地方。","art":"dice","tags":["地铁","盲盒","城市","假期"]},{"id":"do-049","type":"do","sub":"出游","format":"steps","audience":"all","for":"kid","scenes":["周末","出游"],"mins":60,"title":"找一家没去过的小馆子","body":"不去商场，不去吃过的店。在地图上挑一家两个人都没去过的小馆子，谁挑的店谁点菜。踩雷了，算大人的。","steps":["不付钱的那位打开地图，在附近挑一家没去过的","走过去或骑过去，挑店的人带路","菜单交给挑店的人，点什么都行","菜上齐后各评一道“最值”和“最坑”","值得再来，就记进一张“我们的馆子”清单"],"hint":"他点了三个肉菜没有青菜，这一顿就这样。饭桌上不谈学习。踩雷了别说“我就说吧”，说“下次换一家”。","refs":[{"t":"光明网科普 · 王葵（2026-09-11）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"}],"art":"table","tags":["小馆子","他做主"]},{"id":"do-050","type":"do","sub":"出差","format":"steps","audience":"all","for":"kid","scenes":["出差"],"mins":20,"title":"同一场球，各猜 3 样","body":"爸爸出差的那几天，挑一场两个人都能看的比赛。开赛前各自发出 3 个预测：谁赢、赢几分、谁得分最高。发出去就不许改，赛后对答案。","steps":["现在就打开赛程，一起挑一场，说定哪天","开赛前各发 3 个预测，发出去就不许改","各看各的，看全场还是只看集锦都行","赛后对答案：胜负、得分王猜对各 1 分，分差谁更接近谁得 1 分；再各发一句“全场最蠢的一个球”","输的人回家那天兑现一瓶饮料"],"hint":"这串消息里只聊球，别夹一句“作业写完没”。他猜得离谱也别笑，万一中了呢。你只看了集锦就照实说。","art":"scoreboard","tags":["篮球","看球","出差","预测"]},{"id":"do-051","type":"do","sub":"出差","format":"steps","audience":"all","for":"kid","scenes":["出差"],"mins":5,"title":"猜猜这个多少钱","body":"爸爸出差时每天发回一张当天拍的照片：一碗面、一张车票、一样怪东西，让在家的人猜价钱。误差十分之一以内记 1 分，满 3 分，点一样当地的东西带回来。","steps":["现在就说好：出差的人每天晚饭后发一张，不多发","拍当天真买过、或者看得到标价的东西","在家的人报一口价，报了不许改","误差在十分之一以内记 1 分；想反过来考对方，回一张自己拍的","满 3 分，点一样当地的东西让他带回来"],"hint":"每天固定时间发一条就够。他不回别连发、别查岗，更别顺口问作业。他猜得再离谱也别笑，照实揭晓就行。","refs":[{"t":"Penn State Thrive 博客","u":"https://thrive.psu.edu/blog/how-parents-can-keep-in-touch-with-their-children-while-traveling/","lv":"专家意见"},{"t":"《成都商报》报道（澎湃转载）","u":"https://www.thepaper.cn/newsDetail_forward_1978525","lv":"个案"}],"art":"suitcase","tags":["出差","照片","猜价钱"]},{"id":"do-052","type":"do","sub":"出差","format":"steps","audience":"all","for":"kid","scenes":["出差"],"mins":10,"title":"隔空对决，题目你出","body":"爸爸出差的时候，约一个晚上隔空比一场。题目由在家的人出：1 分钟平板支撑、10 个纸团投废纸篓、单脚站谁久都行。两地同时开始，各录一段视频为证。","steps":["现在就约好哪天晚上、几点，在家的人出题","到点两地同时开始，各录各的","互发视频，对一下谁赢了","输的人回家那天认罚：罚什么，赢的人定"],"hint":"题目他出，再刁也接。到点就做，开着会也溜出去 2 分钟；你爽约一次，这个约定就不值钱了。别顺便问作业。","refs":[{"t":"Penn State Thrive 博客","u":"https://thrive.psu.edu/blog/how-parents-can-keep-in-touch-with-their-children-while-traveling/","lv":"专家意见"}],"art":"stopwatch","tags":["出差","约定","对决"]},{"id":"do-053","type":"do","sub":"出差","format":"steps","audience":"all","for":"kid","scenes":["出差"],"mins":10,"title":"给出差的人派个任务","body":"爸爸出差前，在家的人给他派一个必须完成的任务：拍到当地一块球场、学会一句当地话、找到一块最怪的招牌。完不成，回来认罚。","steps":["现在就写下任务，可以附一条“不许做的事”","出差的人到了以后去完成，拍照或录音为证","发回来验收；验收的人说不合格，就重做","回家当天交差：是赏是罚，由派任务的人宣布"],"hint":"任务再无聊也认真完成，真为它专门跑一趟。别用机场买的东西糊弄。他验收说不合格，就重做。","art":"briefcase","tags":["出差","任务"]},{"id":"do-054","type":"do","sub":"约定","format":"steps","audience":"all","for":"kid","scenes":["睡前"],"mins":2,"title":"两短一长，是晚安","body":"定一套只有两个人懂的敲门暗号：两短一长是“晚安”，连敲 3 下是“开饭”。敲完就走，里面回敲一下算“收到”。不回敲，谁也不许推门。","steps":["现在就定暗号：两三种就够，各是什么意思","今晚睡前，先想起来的人去对方门上敲“晚安”","里面的人回敲一下，算“收到”","敲完就走；里面不回敲，谁也不许推门"],"hint":"敲完就走，不进屋巡视，不顺口问作业和手机。里面没回应，就是睡了或者不想被打扰，别再敲。你晚归，就留一张画着暗号的便条。","art":"door","tags":["晚安","睡前","暗号","敲门"]},{"id":"do-055","type":"do","sub":"约定","format":"steps","audience":"all","for":"kid","scenes":["球场","饭桌","周末"],"mins":5,"title":"抓到我看手机，就罚","body":"从今天起，家里多一位“手机监督员”。说好一起做事的时候，哪个大人掏出手机，监督员喊一声“手机！”，那人就得当场放下，外加 5 个俯卧撑。","steps":["现在就任命监督员：家里唯一不是大人的那位","一起定好哪些时候算数：打球、吃饭、说好一起做事的时候","监督员喊“手机”，被抓的人立刻放下，不解释","罚什么由监督员定，5 个俯卧撑起步","监督员本人免罚：这是这份差事唯一的工资"],"hint":"被抓了别辩解“是工作消息”，放下就做俯卧撑。真有必须接的电话，开始前先告诉他几点、几分钟。他自己掏手机，这张卡不管，别反过来抓他。","refs":[{"t":"光明网科普 · 王葵（2026-09-11）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"}],"art":"phone-down","tags":["手机","监督员"]},{"id":"ins-001","type":"insight","sub":"球场","format":"plain","audience":"dad","for":"kid","scenes":["球场"],"mins":1,"title":"耳机不带下楼","body":"说好陪他打球的那半小时，耳机留在家里，手机静音放进球包。真有非接不可的电话，出门前先告诉他几点、几分钟。","more":"一项在科学博物馆做的现场实验，请带孩子的父母一半尽量多用手机，一半尽量少用：少用的一组没那么分心，觉得和孩子的联结更强。少用手机的好处在博物馆里比在日常生活里更大，研究者据此推测，在有意义的共同活动里收起手机更值得。\n\n边界：实验测的是父母自己的感受，不是孩子的结局；也没有任何研究专门测过耳机，“耳机不带”是从手机研究推出来的。好在改起来几乎没有成本。","refs":[{"t":"Kushlev 与 Dunn 2019：博物馆里的手机实验","u":"https://journals.sagepub.com/doi/pdf/10.1177/0265407518769387","lv":"实证"},{"t":"研究者在 SPSP 网站上对这项实验的介绍","u":"https://spsp.org/news-center/character-context-blog/parents-disconnecting-your-phone-can-increase-connection-your","lv":"实证"}],"art":"earbuds-off","tags":["耳机","手机","注意力"]},{"id":"ins-002","type":"insight","sub":"球场","format":"plain","audience":"dad","for":"kid","scenes":["球场"],"mins":1,"title":"请他当你的监督员","body":"下楼前跟他说：“你要是看见我掏手机，直接喊‘爸，手机’。”真被喊了，说一声“我的错”，放回包里，不解释。","more":"请孩子当父母的“监督员”，监督刷手机的时长，是心理咨询师王葵给青春期家庭的建议。属于专家经验，没有对照研究；搬到球场上喊这一句，是引申。\n\n手机在球场上只有一种该出现的用法：他让你拍几个投篮慢放，或者帮他记数。一项在科学博物馆做的实验里，把手机用来帮孩子看展的父母，联结感反而更高（测的是父母自己的感受）。\n\n被喊了不算失败。当场认了放回去，比假装没掏强。","refs":[{"t":"心理咨询师王葵给青春期家庭的建议（光明网）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"},{"t":"研究者在 SPSP 网站上对博物馆手机实验的介绍","u":"https://spsp.org/news-center/character-context-blog/parents-disconnecting-your-phone-can-increase-connection-your","lv":"实证"}],"art":"phone-down","tags":["手机","监督员"]},{"id":"ins-003","type":"insight","sub":"陪伴","format":"plain","audience":"dad","for":"kid","scenes":["球场","周末"],"mins":1,"title":"“陪”和“等”分开说","body":"他和同学打起来了，你想去跑步或回电话，就明说：“接下来你们打，我去跑两圈，11 点回来接你。”别戴着耳机站在场边假装在陪。","more":"他要确认的只有一件事：此刻你的注意力在不在他身上。诚实地“不陪”，比人在场、心不在要好。这一句是推断，不是研究结论。\n\n依据是一项时间日记研究里的区分：一起做同一件事的“投入式时间”，和人在旁边、随叫随到的“可得时间”，是两种东西；在 12–18 岁，父母的投入式时间越多，孩子的越轨行为和行为问题越少。这是相关关系，排除不了反向因果。\n\n说好陪的那一段全程在；说好等的那一段，你爱干什么干什么。","refs":[{"t":"PRB 对 Milkie 等 2015 时间日记研究的介绍","u":"https://www.prb.org/resources/time-with-parents-key-for-adolescents/","lv":"实证"}],"art":"sneaker","tags":["耳机","同学","接送"]},{"id":"ins-004","type":"insight","sub":"球场","format":"plain","audience":"dad","for":"kid","scenes":["球场"],"mins":1,"title":"先当 10 分钟传球手","body":"开场 10 分钟不用会打：他投，你抢篮板，把球传回他手上。不点评动作，不喊“手抬高”。他问你，你再说。","more":"这是球场上流传很广的陪法，没有找到具体出处，更谈不上研究。它管用的道理很朴素：你全程在场上，眼睛跟着球，他每投一次都有人接应。\n\n找得到的几位陪孩子打球的父亲水平都一般，没有一位靠的是球技。其中一位从小对运动没兴趣的爸爸，孩子的训练和比赛每场都到，为了陪儿子，自己从头学运球和投篮（个案）。\n\n10 分钟以后想加码，再换成投篮比赛或一对一。","refs":[{"t":"Clint Edwards：不爱运动的爸爸怎样陪孩子打球（Scary Mommy）","u":"https://www.scarymommy.com/hated-sports-child-started-playing","lv":"个案"}],"art":"ball","tags":["传球","篮板","不会打球"]},{"id":"ins-005","type":"insight","sub":"球场","format":"plain","audience":"dad","for":"kid","scenes":["球场","周末"],"mins":1,"title":"让规则，比分咬住","body":"和他打一对一，给自己加三条限制：不盖帽；单手、把球运高，让他断得着；偶尔“断球失手”，放他上篮。比分咬住，先让他多赢几回。","more":"办法来自美国爸爸 Scott Gibb 的自述，他有一个 13 岁的女儿和一个 6 岁的儿子。照他的打法，30–45 分钟能给孩子几十次上篮机会。一个家庭的经验，不是研究。\n\n他也说了实话：6 岁的那个一输就不玩了。所以先让孩子多赢，等他输得起了、水平上来了，再一点点收回让步。\n\n他推荐打全场，觉得半场别扭；体力跟不上就缩成半场，这是变通，不是他的建议。","refs":[{"t":"Scott Gibb：怎样和孩子打篮球","u":"https://scottgibb.substack.com/p/how-to-play-basketball-with-kids-675","lv":"个案"}],"art":"scoreboard","tags":["一对一","让分"]},{"id":"ins-006","type":"insight","sub":"球场","format":"plain","audience":"dad","for":"kid","scenes":["球场","车上"],"mins":1,"title":"回家路上只说一句","body":"打完球往回走，只说“我喜欢看你打球”。那个该传没传的球，今天不提。他想聊就接着聊，他不吭声，就一起安静走回去。","more":"两位美国教练 Bruce Brown 和 Rob Miller 30 年里做过几百次访谈，对象是大学年龄的运动员：他们最不喜欢的，是比赛后回家路上的那段对话；最让他们舒服的，是父母说这一句。这是教练自己称的“非正式调查”，经专栏作者转述，不是发表的研究。\n\n青少年体育作者 John O'Sullivan 的说法更直接：孩子的运动生涯里，没有比回家路上更不适合教他的时刻；要不要聊，等他自己提。\n\n想多说一句，就说你看见的：“刚才那个左手上篮，我看见了。”","refs":[{"t":"Bruce Brown 与 Rob Miller 的访谈（Daniel Coyle 转述）","u":"https://danielcoyle.com/2013/09/19/best-parenting-tip-ever/","lv":"专家意见"},{"t":"John O'Sullivan：回家路上不是教育的时刻（Soccer America）","u":"https://www.socceramerica.com/the-ride-home-not-a-teachable-moment/","lv":"专家意见"}],"art":"car","tags":["复盘","回家路上"]},{"id":"ins-007","type":"insight","sub":"陪伴","format":"plain","audience":"dad","for":"kid","scenes":["球场","周末"],"mins":1,"title":"去不了，认账并改期","body":"临时去不了，别说“爸爸忙，下次再说”。说：“周三我去不了了，是我的安排出了问题。挪到周四同一时间，行吗？”","more":"前一句把他排在了“忙”的后面；后一句认了是自己的问题，并且当场给出新的时间。这句话是拟写的示范，不是哪位父亲的原话。\n\n背后的做法来自时间管理作者 Laura Vanderkam 的一条规则：给重要的事留一个备用时段，被冲掉就挪过去，不必取消。属于经验之谈，没有研究检验。\n\n所以每周排球场那一格时，顺手把备用日也写进日历。","refs":[{"t":"Laura Vanderkam《Tranquility by Tuesday》书摘","u":"https://lauravanderkam.com/wp-content/uploads/2022/09/TBT-Excerpt.pdf","lv":"专家意见"}],"art":"calendar","tags":["加班","改期","爽约"]},{"id":"ins-008","type":"insight","sub":"陪伴","format":"plain","audience":"dad","for":"kid","scenes":["球场","周末"],"mins":2,"title":"他想和同学打，放手","body":"他说想自己跟同学去，回一句：“去吧。要我送就说，几点接你？”不说“那我不是白来了”。周末那场，欢迎他叫上同学。","more":"一项用呼叫器随机询问学生“此刻在做什么”的追踪研究发现：从五年级到高中毕业，孩子参加家庭活动的时间一路下降，和父母交谈的时间却保持稳定；把他们往外拉的是朋友、打工这些外面的事，家庭冲突不起明显作用，男孩被拉走得比女孩多。研究者给父母的建议是：按孩子的时间表在场。这里读到的是新闻稿。\n\n北京一位三个孩子的父亲和同学家长轮流组织孩子踢球、打篮球，儿子后来愿意主动讲学校的事了（个案）。\n\n要留意的是反过来的情况：一对一也约不成，他也不再主动说任何事。","refs":[{"t":"Larson 等 1996：青少年与家人共处时间的研究（新闻稿）","u":"https://www.eurekalert.org/news-releases/1012938","lv":"实证"},{"t":"北京几位父亲陪孩子运动的做法（北京日报客户端）","u":"https://news.bjd.com.cn/2025/05/29/11179764.shtml","lv":"个案"}],"art":"jersey","tags":["同学","朋友","放手"]},{"id":"ins-009","type":"insight","sub":"陪伴","format":"plain","audience":"dad","for":"kid","scenes":["出差"],"mins":2,"title":"出差每天一条消息","body":"出差那几天，每天差不多同一个时间发一条：一张当地的照片，配一个具体的小问题。不问作业，不查岗。他不回，也不连发。","more":"关于经常出差的父母，没有找到高质量的研究，只有育儿作者和大学推广项目的建议，说法还不完全一致。一位写给出差父亲的作者主张每天在固定时间联系一次，照片和消息作补充，问具体的事，比如“今天最好笑的一件事是啥”；他写的是更小的孩子，换成给 12 岁男孩发消息是改写。宾州州立大学的推广项目则提醒别把时间卡死，每次结束时约好下一次就行。\n\n两边合起来：让他知道每天会有一条，错过了也不算违约。\n\n走之前说清哪天走、哪天回。回来只补上欠的那场球，不开“爸爸对不起你”的长谈。","refs":[{"t":"Art of Manliness：出差的父亲怎样不缺席","u":"https://www.artofmanliness.com/people/fatherhood/how-to-be-a-better-dad-when-you-travel-for-business/","lv":"专家意见"},{"t":"Penn State Thrive：出差时怎样和孩子保持联系","u":"https://thrive.psu.edu/blog/how-parents-can-keep-in-touch-with-their-children-while-traveling/","lv":"专家意见"}],"art":"suitcase","tags":["出差","消息","照片"]},{"id":"ins-010","type":"insight","sub":"陪伴","format":"plain","audience":"dad","for":"kid","scenes":["球场","车上"],"mins":2,"title":"看小信号，别等大变化","body":"头 4 周只留意三个小信号：他主动问“周三还去吗”；进了球回头找你；路上自己说起一件学校的事，哪怕只有一句。","more":"这是按研究推出来的观察清单，不是验证过的指标。依据是 Stattin 与 Kerr 的经典发现：父母对青春期孩子的了解，更多来自孩子主动说，而不是靠盯和查（这里没有读到原文）。\n\n不算信号的两样：考得好不好，和他突然话变多。前者不归这件事管，后者不是目标。\n\n要担心的是另一头：连续几周一对一也约不成，他不再主动说任何事，同时持续低落或易怒、对原来喜欢的事没了兴趣。那时先找学校心理老师，别靠加活动解决。这不替代医生面诊。","refs":[{"t":"《剑桥父母监控与信息管理手册》第二部分（讨论 Stattin 与 Kerr 的研究）","u":"https://www.cambridge.org/core/product/identifier/9781009418652%23bp7/type/book_part","lv":"实证"}],"art":"magnifier","tags":["信号","有没有用"]},{"id":"ins-011","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["睡前","车上"],"mins":1,"title":"先接住，当天不给方案","body":"他说出“我不想当小透明”这类话，当天只回一句：“你愿意跟我说这个，我挺高兴的。”说完就停。不追问，不给办法。","more":"最容易犯的错是马上给方案：“那你上课别讲话。”这等于把他的需要改写成了你的议程。\n\n这一步是按几条证据拟出来的做法，没有对照研究检验过。依据之一是 Yeager 等人的综述：说教式的干预到了青春期常常失效，他们的解释是，这类做法没顾及孩子“想被尊重”的强烈愿望。作者是把它当假说提出来的。\n\n他肯说出口，本身是好消息。想问清他要的是哪一种“被看见”，另找一个肩并肩的时候，只问不评。","refs":[{"t":"Yeager、Dahl 与 Dweck 2018：为什么对青少年的干预常常失效","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758430","lv":"实证"}],"art":"chat","tags":["小透明","存在感","接住"]},{"id":"ins-012","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["车上","饭桌"],"mins":2,"title":"别替他下“自卑”的判断","body":"“你是不是有点自卑”这句话不说。换成一个具体的问题：“你希望同学提起你的时候怎么说？”他怎么答，就按他的答案来。","more":"想被看见，至少有四种读法：这个年龄对地位和尊重本来就敏感；觉得自己在班里可有可无；手里缺一件拿得出手的事；对自己的总体评价确实偏低。前三种不需要“治”，第四种要靠他自己的话来确认。这个分法是综合几项研究的归纳，不是诊断工具。\n\n心理学里，“觉得自己好不好”和“觉得别人在不在乎我”是两回事，后者叫重要感（Flett 等的研究，只核对到摘要）。缺的是后者，却按自卑去夸“你很棒”，药不对症。\n\n“我什么都不行”反复出现，情绪低落超过 2 周，找学校心理老师。这不替代医生面诊。","refs":[{"t":"Flett 等 2022：“重要感”与“无足轻重感”的量表研究","u":"https://journals.sagepub.com/doi/full/10.1177/07342829211050544","lv":"实证"}],"art":"question","tags":["自卑","标签","重要感"]},{"id":"ins-013","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["饭桌","车上"],"mins":1,"title":"逗情境，不逗人","body":"跟他定一条搞怪的规矩，就一句：逗情境，不逗人；也不拿自己最在意的事当梗。笑点放在事情上，谁都不当靶子，包括他自己。","more":"英国 6 所中学 1234 名 11–13 岁学生，从秋季跟到春季：被欺负的孩子，拿自己开涮变多，和大家一起乐的幽默变少；反过来，常拿自己开涮的孩子，被欺负也变多。这是时间上的先后，不能证明谁导致谁，只核对到摘要。这条规矩是据此拟的，没有被检验过。\n\n观察 2 周，留意三件事就够：笑点的靶子是谁；场合对不对；笑声是“跟他一起笑”，还是“笑他”。\n\n玩笑一旦对准某个具体的人，起外号、模仿取笑，就当规矩管，不当幽默看。","refs":[{"t":"Fox、Hunter 与 Jones 2015：幽默风格与被欺负的追踪研究","u":"https://research.gold.ac.uk/id/eprint/16368","lv":"实证"}],"art":"target","tags":["搞怪","玩笑","自嘲"]},{"id":"ins-014","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["车上","饭桌"],"mins":2,"title":"先认他会逗人是本事","body":"谈他上课接话的事，第一句说：“你能让人笑，这是本事。咱们琢磨的是把它用在哪儿。”不说“就知道出风头”“没个正形”。","more":"一项对 672 名瑞士儿童青少年的调查里，“班级开心果”的幽默和领导力得分更高；偏低的是审慎、自我调节和坚持，生活满意度也略低。另一项对 300 名 6–9 年级学生的调查里，这类行为与更多的互选朋友、更高的同伴接纳相关，也与课堂上更多的扰乱行为相关。两项都是问卷调查，只说明相关，只核对到摘要。\n\n所以能逗人笑是社交上的本钱，代价出在课堂上。要处理的是场合：课上用，老师记他一笔；联欢会、主持、解说上用，全班记住他。\n\n规矩照定：老师讲课时不接话，想到的梗记在本子角上，下课再说。","refs":[{"t":"Ruch、Platt 与 Hofmann 2014：“班级小丑”的性格优势","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4179698","lv":"实证"},{"t":"Wagner 2019：班级小丑行为与同伴关系","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6497778","lv":"实证"}],"art":"star","tags":["搞怪","接话","幽默"]},{"id":"ins-015","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["车上","饭桌"],"mins":2,"title":"帮他挣喜欢，不争人气","body":"找个机会把这句话讲给他，只讲一次：“被很多人知道，和被身边人喜欢，是两回事，后一种才长期值钱。”讲完就停，之后只帮他做后一种。","more":"心理学家 Prinstein 总结的追踪研究把“受欢迎”分成两种：被身边人喜欢，和有地位、有人气。前一种与成年后更好的工作关系和健康相关，后一种与日后的攻击、成瘾等问题相关。这来自访谈和科普转述，原始论文没有核对。\n\n另一项研究把 184 名青少年从 13 岁跟到 23 岁：早早靠“装成熟”显得很酷的孩子，短期内在同伴里吃得开，到成年早期，亲密关系、酒精和违法方面的问题更多。样本来自美国的一个社区，方向可以参考，数字不要照搬。\n\n该管的是手段，不是他想被看见这个需要。","refs":[{"t":"APA Monitor 2017：Prinstein 谈两种“受欢迎”","u":"https://www.apa.org/monitor/2017/09/conversation-prinstein","lv":"专家意见"},{"t":"Allen 等 2014：早早“装酷”的孩子后来怎样了","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4165811","lv":"实证"}],"art":"heart","tags":["人气","受欢迎","被喜欢"]},{"id":"ins-016","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["周末","球场"],"mins":2,"title":"每月帮他约一个同学","body":"每月创造一两次“带一个同学一起做事”的机会：周末约一个同学打球、来家里玩、一起看场比赛。你管接送和那顿饭，别的不插手。","more":"一项追踪 169 名青少年 10 年的研究发现：15 岁时亲密友谊的强度，预测 25 岁时自我价值感相对上升、焦虑和抑郁相对下降；而“年级里很多人想跟他玩”，预测的是之后更高的社交焦虑。\n\n这是观察性研究，起点是 15 岁的美国学生，对 12 岁的孩子没有直接证据，只核对到摘要。“友谊是在两三个人一起做事的小场合里长出来的”，则是专家经验。\n\n8 周后可以这样检验：他能不能说出一两个关系好的同学的名字，以及最近一起做过什么。","refs":[{"t":"Narr 等：亲密友谊与同伴人气的 10 年追踪","u":"https://uva.theopenscholar.com/teenresearch/publications/close-friendship-strength-and-broader-peer-group-desirability-differential","lv":"实证"}],"art":"highfive","tags":["朋友","友谊","同学"]},{"id":"ins-017","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["周末","出游"],"mins":2,"title":"家里给他一个真角色","body":"这周交给他一件真归他管的事：一次出门的导航和带路，周末一顿饭吃什么，或者家里设备出问题先找他。他定了，就照办。","more":"判断一个家庭角色是不是真的，只有两条：他不做，这件事就没人做；他定了，家里就真的照办。象征性的家务不算。这两条标准是专家意见。\n\n背后的理论来自 Fuligni：青少年有为别人、为群体做贡献的需要，这一点长期被忽视。这是一篇理论综述，不是对家庭做法的检验。\n\n《宁波晚报》报道过一位妈妈让儿子看导航、带路，自己跟在后面，偶尔故意走错，等他回头来找；另一次是三位家长把行程排满，三个 12 岁的孩子直说没兴趣。都是个案，差别在孩子有没有真实的任务和发言权。","refs":[{"t":"Fuligni 2019：青春期“贡献的需要”","u":"https://adolescence.psych.ucla.edu/wp-content/uploads/sites/354/2025/07/The-Need-to-Contribute-During-Adolescence.pdf","lv":"实证"},{"t":"《宁波晚报》报道的三个家庭（人民日报客户端转载）","u":"https://www.peopleapp.com/rmharticle/30051410968","lv":"个案"}],"art":"key","tags":["责任","导航","做主"]},{"id":"ins-018","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["饭桌"],"mins":2,"title":"身高，家里谁都不评","body":"家里先自查三件事：有没有人拿他的身高开玩笑，哪怕是亲昵的；有没有因为他显小就替他做决定；有没有当着他的面讨论“怎么还不长”。","more":"美国一项对 45 个班、965 名 6–12 年级学生的研究里，学生并不知道研究与身高有关。结果是：身高与朋友多少、同伴接纳、名声都没有关系；矮个学生只是被认为看起来比实际年龄小，这一点到高年级也减弱了。后来有研究转述过一篇综述的结论，方向相同：矮本身并不带来心理社会问题（只核对到转述）。\n\n所以能管的不是他的身高，是大人怎么对待它：不取笑，不因为他显小就把他当小孩。这三条自查是据此拟的，属于专家意见。\n\n局限：样本来自美国，数据已有 20 多年；在篮球分量很重的班级里身高是否更要紧，现有证据回答不了。","refs":[{"t":"Sandberg 等 2004：身高与同伴关系（布法罗大学新闻稿）","u":"https://www.buffalo.edu/news/releases/2004/09/6856.html","lv":"实证"},{"t":"Quitmann 等 2016（PLoS One）：引言转述了一篇关于矮身材的综述","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4838264","lv":"实证"}],"art":"tree","tags":["身高","个子","玩笑"]},{"id":"ins-019","type":"insight","sub":"被看见","format":"plain","audience":"dad","for":"kid","scenes":["饭桌","睡前"],"mins":1,"title":"老师的评语不原样转述","body":"老师反馈之后，回家不说“老师又说你了”。只带回一件他能做的事，或者老师提到的一个好：“老师说你今天举手等了，答得也到位。”","more":"这是按证据拟的家规，“不转述”本身没有被研究检验过。依据是一项对 806 名中美初一学生半年的追踪：定规矩、知道孩子在做什么，预测更好的学业表现；贬低、让他内疚、收回关爱这类“心理控制”，预测孩子情绪变差。一句原样转述的差评，他听到的多半是后一种。\n\n和老师谈的时候，可以请老师说一个他做得不错的时刻，这样你带回家的话是真的。\n\n老师的反馈由父母中的一个人对接，另一个人不重复。","refs":[{"t":"Wang、Pomerantz 与 Chen 2007：父母控制方式的中美追踪","u":"https://pubmed.ncbi.nlm.nih.gov/17883450","lv":"实证"}],"art":"pencil","tags":["老师","评语","转述"]},{"id":"ins-020","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["饭桌","睡前"],"mins":1,"title":"管行为，不贬人","body":"规矩只说行为：“10 点半前上床”“老师讲课时不接话”。不说“你就是懒”“怎么这么不争气”。前一种可以很坚定，后一种一句都嫌多。","more":"最稳的一条证据来自对 806 名中美初一学生半年的追踪：父母的“心理控制”，也就是让孩子内疚、收回关爱、贬低，在两国都预测孩子情绪变差；定规矩、知道孩子在做什么这类行为层面的管教，在两国都预测更好的学业表现。\n\n所以界线不在管不管，在于管的是行为，还是他这个人。作息、手机、作业可以明确而坚定；他的想法、感受和对自己的评价，不当奖惩的工具。\n\n这是追踪研究，说明的是先后和相关，不是实验；这里只核对到摘要。","refs":[{"t":"Wang、Pomerantz 与 Chen 2007：父母控制方式的中美追踪","u":"https://pubmed.ncbi.nlm.nih.gov/17883450","lv":"实证"}],"art":"whistle","tags":["规矩","批评","贬低"]},{"id":"ins-021","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["睡前","饭桌"],"mins":2,"title":"爱和认可不当筹码","body":"找个平常的时候说一次：“不管考得怎么样，我对你这个人的看法不会变。”然后做到：考砸那天，晚饭、晚安、周末的球，一样不少。","more":"“考好了才亲近”这种有条件的认可，与孩子“自我价值跟着表现走”、与抑郁症状都相关，一项汇总 31 个样本的元分析给出的相关系数是 0.29 和 0.22。属小到中等的相关，不是因果。\n\n北京 13 所中学 1419 名初一学生的 3 年追踪还发现一个互相加码的循环：孩子越焦虑，父母的心理控制越多；父母的心理控制，又预测孩子之后更焦虑。能切断它的只有父母这一头。\n\n华盛顿大学给家长的一份讲义说得更直接：一对一的时间不当奖励，也不当惩罚，出了问题的那天更要有。","refs":[{"t":"Haines 与 Schutte：父母有条件认可的元分析","u":"https://rune.une.edu.au/bitstreams/b36b0d24-354b-4ed5-bd3c-61290accb501/download","lv":"实证"},{"t":"孙丽萍等 2018：父母心理控制与初中生焦虑的 3 年追踪","u":"https://devpsy.bnu.edu.cn/CN/Y2018/V34/I6/758","lv":"实证"},{"t":"华盛顿大学给青少年家长的训练讲义","u":"https://depts.washington.edu/hcsats/PDF/TF-%20CBT/pages/8%20Parent%20Management%20Training/How%20to%20get%20your%20teen%20%20to%20want%20to%20be%20good.pdf","lv":"专家意见"}],"art":"lighthouse","tags":["认可","条件","托底"]},{"id":"ins-022","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["饭桌","周末"],"mins":2,"title":"检验的是办法，不是他","body":"一起试一件事之前先讲定：“到时候咱们看哪些办法管用、哪些要换。这是在检验办法，不是检验你。”没成，就说“这个办法不灵，换一个”。","more":"在“勤能补拙”的文化里，“努力了还是不行”比“没努力所以不行”更伤人，所以话要说在前头。这一句是判断，不是研究结论。\n\n做法是只定两三件每周能打勾的事，由他自己定，到期只复盘办法。近处的小目标比远处的大目标更能提升自我效能，这是 Bandura 与 Schunk 经典实验的结论。\n\n“定个期限、到期复盘”作为家庭里的做法，没有直接的实验证据，是从这些研究外推的。","refs":[{"t":"Bandura 与 Schunk 1981：近端目标与自我效能","u":"https://uploads-ssl.webflow.com/59faaf5b01b9500001e95457/5bc552d85141987915dab842_Bandura%20&%20Schunk,%201981.pdf","lv":"实证"}],"art":"flask","tags":["办法","复盘","失败"]},{"id":"ins-023","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["饭桌","球场"],"mins":2,"title":"夸办法，不夸“努力”","body":"把“你很努力”“只要努力就行”换成一句具体的：“这次你先把错题按类型分了，这个办法管用。”说得出他做了什么，才算夸。","more":"到了初高中，空泛地夸“努力”可能适得其反：孩子会琢磨话外音，比如“为什么别人不用这么费劲”。这是一篇综述的结论，这里读到的是教育媒体的报道；报道里研究者给的替代办法，正是具体说出哪个办法起了作用。\n\n另一项汇总 63 项研究的元分析里，成长型思维干预对成绩的平均效应只有约 0.05 个标准差，质量最高的几项研究里接近零。别指望一句“努力就行”能改变什么。\n\n具体的夸法也没有对照研究保证有效，它的好处是真实：你得真看见了，才说得出来。","refs":[{"t":"EdWeek 对 Amemiya 与 Wang 2018 综述的报道","u":"https://www.edweek.org/leadership/teenagers-are-skeptical-of-praise-for-good-effort-study-finds/2018/04","lv":"实证"},{"t":"Macnamara 与 Burgoyne 2023：成长型思维干预的元分析","u":"https://doi.org/10.1037/bul0000352","lv":"实证"}],"art":"bulb","tags":["表扬","努力","夸"]},{"id":"ins-024","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["车上"],"mins":1,"title":"2 次“不知道”，就安静","body":"车上问他一个具体的小问题，比如“午饭时有什么好笑的事”。他连着答 2 次“不知道”，就不再问，让他看窗外，或者让他选歌。","more":"这是四位心理咨询师和治疗师谈“孩子为什么在车里更容易开口”时给的经验：并排坐、不用对视，车程有头有尾，孩子觉得有“出口”；问具体的小事，不把聊天变成采访，不急着替他解决。两个问题都答“不知道”，多半是不想说、需要缓一缓，过后再试。属于专家经验，没有研究检验。\n\n“今天怎么样”这类问法，多半只换来一个“还行”。\n\n沉默不等于失败。他知道这段路不会变成审问，下次才更可能自己开口。","refs":[{"t":"Scary Mommy：为什么青少年在车里更愿意开口","u":"https://www.scarymommy.com/parenting/why-teens-open-up-in-the-car","lv":"专家意见"}],"art":"window","tags":["车上","沉默","不知道"]},{"id":"ins-025","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["车上","饭桌","睡前"],"mins":1,"title":"先听，别急着给建议","body":"他讲了一件学校的事，先只说两句：“再多讲讲。”“谢谢你告诉我。”把“你应该这样”咽回去。他问“你觉得呢”，再给建议。","more":"临床心理学家 Lisa Damour 的经验是：青少年带着烦恼来找父母，要的先是好奇，再是共情，这两样就能走很远；急着动手解决，往往不是他要的。这是临床工作者的意见，不是研究结论。\n\n另一条线索是 Stattin 与 Kerr 的经典发现：父母对青春期孩子的了解，更多来自孩子主动说，而不是靠盯和查（这里没有读到原文）。你每一次先听，都是在给他下一次开口付定金。\n\n反面的个案：一位父亲想引导上初中的儿子，却总变成说教，儿子的评价是“你的话题好无聊”。","refs":[{"t":"Lisa Damour 谈怎样陪青少年过情绪关（NPR）","u":"https://www.npr.org/2023/03/29/1166789948/how-to-show-up-for-teens-when-big-emotions-arise","lv":"专家意见"},{"t":"《剑桥父母监控与信息管理手册》第二部分（讨论 Stattin 与 Kerr 的研究）","u":"https://www.cambridge.org/core/product/identifier/9781009418652%23bp7/type/book_part","lv":"实证"},{"t":"《人民日报海外版》2021-08-26 报道里的一位父亲","u":"http://paper.people.com.cn/rmrbhwb/html/2021-08/26/content_3065177.htm","lv":"个案"}],"art":"cup","tags":["倾听","建议","说教"]},{"id":"ins-026","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["睡前","饭桌"],"mins":1,"title":"说错了，第二天重来","body":"昨晚发了火或说了重话，今天找个平静的时候补一句：“昨天那事我说得不对，重来。”后面不接“但是”，也不问“你原谅我吗”。","more":"临床心理学家 Becky Kennedy 把这叫“修复”，分三步：说出发生了什么，为自己的行为负责，说下次会怎么做。她举过一个反例：先说“要不是你抱怨晚饭，我也不会吼”，再补一句对不起。这不算修复。追问“你原谅我了吧”，则是把自己该做的功课交给了孩子。\n\n这是专家经验，没有对照研究；她的例子里孩子只有六七岁，用在 12 岁的孩子身上是改写。\n\n说完就翻篇，照常吃饭，照常约球。","refs":[{"t":"Becky Kennedy 谈“修复”（NPR）","u":"https://www.npr.org/2023/10/06/1203898492/no-parent-is-perfect-so-try-to-get-good-at-repair","lv":"专家意见"}],"art":"sun","tags":["道歉","发火","重来"]},{"id":"ins-027","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["饭桌","睡前"],"mins":1,"title":"听完评价，隔一天再谈","body":"被老师约谈，或者听完外人对他的一通评价，给自己定一条 24 小时规则：当天不跟他谈这件事，不做任何决定。先和他妈妈对齐，再想对他说什么。","more":"“隔一天”本身没有被研究检验过，它是用来挡住一个有证据的循环：北京 13 所中学 1419 名初一学生的 3 年追踪发现，孩子的焦虑会推高父母的心理控制，父母的心理控制又预测孩子之后更焦虑。你带着火气回家的那个晚上，正是这个循环最容易启动的时候。\n\n隔一天不是瞒着他。外人的评判不转述；老师的话，第二天只带回他能做的那一件事。","refs":[{"t":"孙丽萍等 2018：父母心理控制与初中生焦虑的 3 年追踪","u":"https://devpsy.bnu.edu.cn/CN/Y2018/V34/I6/758","lv":"实证"}],"art":"snow","tags":["老师","评价","冷静"]},{"id":"ins-028","type":"insight","sub":"说话","format":"plain","audience":"dad","for":"kid","scenes":["睡前"],"mins":1,"title":"一句不问作业的晚安","body":"睡前到他房门口，敲门，站着说句晚安就走。不顺口问作业，不看他桌上摊着什么。他已经睡了就留张便条，第二天早饭多坐 10 分钟。","more":"这个小动作没有被单独研究过，是从几条线索推出来的。Ellen Galinsky 对全美 1023 名 8–18 岁孩子的调查发现：孩子评价父母，既看在一起的时间有多少，也看那段时间是匆忙还是从容、父母能不能真的专注在自己身上；说起最好的时光，多半是日常的小片刻。调查是 20 多年前做的，问的是感受，不是因果。\n\n个案里，一位妈妈在儿子 15 岁时固定睡前聊几分钟。\n\n最容易坏在“顺口问一句作业”。一问，晚安就成了查岗。","refs":[{"t":"Ellen Galinsky《Ask the Children》调查（1999）","u":"https://www.familiesandwork.org/wp-content/uploads/2025/07/FindingFromATC.pdf","lv":"实证"},{"t":"《人民日报海外版》2021-08-26 报道里的一位母亲","u":"http://paper.people.com.cn/rmrbhwb/html/2021-08/26/content_3065177.htm","lv":"个案"}],"art":"moon","tags":["晚安","睡前","作业"]},{"id":"ins-029","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["车上","球场","睡前"],"mins":2,"title":"先问一句：2 分钟行吗","body":"身体的事不攒成一次“大谈话”。开口前先问：“跟你说个 2 分钟的事，说完就不说了，行吗？”一次只说一个点，说完真的停。","more":"儿科医生 Cara Natterson 的说法是：这是很多年里的上百次谈话，不是一次；这回没谈成，下次换个方式，从上次停下的地方接着说。属于临床经验，没有对照研究。“先征得同意”是沟通实务里常见的做法，没有找到专门出处。\n\n证据的成色照实说：一项汇总 52 篇文献、2.5 万多名青少年的元分析里，父母与孩子谈性，与孩子日后更安全的行为只有小幅相关，而且在女孩身上、在与母亲的沟通上更明显。不能说成因果。对 12 岁的孩子，目标朴素得多：让他知道这些事在家里可以说。\n\n这不替代医生面诊。","refs":[{"t":"Cara Natterson 访谈：怎样读懂疏远的青春期男孩（Greater Good）","u":"https://greatergood.berkeley.edu/article/item/how_to_decode_your_aloof_teen_boy","lv":"专家意见"},{"t":"Widman 等的元分析（ScienceDaily 介绍）","u":"https://sciencedaily.com/releases/2015/11/151102125735.htm","lv":"实证"}],"art":"stopwatch","tags":["青春期","谈话","两分钟"]},{"id":"ins-030","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["车上","球场","睡前"],"mins":1,"title":"肩并肩说，别对视","body":"难开口的话，挑不用对视的时候说：车上并排坐着，投篮捡球的间隙，晚上道晚安的时候。不把他叫进书房，面对面坐下。","more":"Natterson 给的降低强度的办法就是别面对面：车里并排坐着、散步时、晚上道晚安时。咨询师们对“车里好谈话”的解释是：没有眼神接触，车程有头有尾，孩子觉得有“出口”。写男孩的临床作者 Pollack 也观察到，男孩常常是在做别的事时才谈感受（只核对到摘要）。\n\n如实交代：肩并肩只有医生和作者的经验支持，没有对照研究。值得做，是因为成本几乎为零，而且几位作者给了同样的建议。\n\n车开到家，话也就说完了，这对你和他都是解脱。这不替代医生面诊。","refs":[{"t":"Cara Natterson 访谈：怎样读懂疏远的青春期男孩（Greater Good）","u":"https://greatergood.berkeley.edu/article/item/how_to_decode_your_aloof_teen_boy","lv":"专家意见"},{"t":"Scary Mommy：为什么青少年在车里更愿意开口","u":"https://www.scarymommy.com/parenting/why-teens-open-up-in-the-car","lv":"专家意见"},{"t":"William Pollack 谈男孩怎样表达感受（Oprah.com 摘录）","u":"https://www.oprah.com/relationships/teaching-boys-how-to-cope-with-feelings/3","lv":"专家意见"}],"art":"sofa","tags":["青春期","车上","肩并肩"]},{"id":"ins-031","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["车上","睡前"],"mins":2,"title":"只给信息，不问有没有","body":"谈身体的事只说“这事是这样的”，不问“你有没有”“你是不是”。用正式的名词，语气像说天气。答不上来就说“我查一下再告诉你”。","more":"一问“你有没有”，谈话就从“告诉你一件事”变成了“我在查你”。Yeager 等人的综述认为，青春期的孩子格外在意是否被尊重，说教和盘问正撞在这一点上（作者是把它当假说提出来的）。\n\n睾丸、包皮、遗精、勃起，第一次把正式名词平平常常说出口，等于告诉他这是可以正常说的事。京津冀近 2 万名小学生家长的调查里，能自在地跟孩子谈性的只有四成，用词规范的不到三成，所以你觉得别扭很正常。\n\n这几条做法是按专家经验拟的，没有对照研究。答应去查的，要真的回来告诉他。这不替代医生面诊。","refs":[{"t":"Yeager、Dahl 与 Dweck 2018：为什么对青少年的干预常常失效","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758430","lv":"实证"},{"t":"Zhang 与 Yuan 2023：小学生家长对性教育的认识与做法（PMC9929350）","u":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9929350/","lv":"实证"}],"art":"abc","tags":["青春期","名词","不追问"]},{"id":"ins-032","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["车上","睡前"],"mins":1,"title":"他说别说了，就真的停","body":"他说“别说了，好烦”，你只答一个字：“好。”不追加“我是为你好”，不问“你这什么态度”。过几天换个场景、换个更小的切口再来。","more":"“我都知道了”更准确的翻译是：这个话题让我不自在，请快点结束。背后多半是尴尬、对隐私的需要、怕被追问。这是综合几个来源的推断。\n\n停下来不算失败。Natterson 的看法是，一种方式不行，下次换一种，从上次停下的地方接着来。\n\n只有两条安全规则不能因为一句“别说了”就放弃：睾丸突然剧痛要马上说；被人威胁了先找爸妈。各只需要一句，可以说“行，那我只说一句，说完拉倒”，也可以写在纸条上。这不替代医生面诊。","refs":[{"t":"Cara Natterson 访谈：怎样读懂疏远的青春期男孩（Greater Good）","u":"https://greatergood.berkeley.edu/article/item/how_to_decode_your_aloof_teen_boy","lv":"专家意见"}],"art":"flag","tags":["青春期","防御","别说了"]},{"id":"ins-033","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["睡前"],"mins":1,"title":"先敲门，等他应声","body":"从今天起，进他房间先敲门，他应了再进。只说一句“以后进你屋我们先敲门”，不用开会。他洗澡、换衣服的时候，不推门。","more":"隐私在这个年龄是发育需要，不是“有事瞒着”。联合国教科文组织的《国际性教育技术指导纲要》在 9–12 岁段就写明：青春期里，身体和私人空间的隐私对男孩女孩都变得更重要。\n\n给隐私和定手机规则不矛盾：规则事先讲明、公开执行，不偷看。追踪研究里的经典发现是：父母对孩子的了解，更多来自他主动说，而不是靠盯和查（这里没有读到原文）。\n\n敲门还有一层实际用处：身体的事在家里不会被撞见、被取笑，哪天真有地方疼了，他才肯来找你。这不替代医生面诊。","refs":[{"t":"联合国教科文组织《国际性教育技术指导纲要》（2018 修订版）","u":"https://moldova.unfpa.org/sites/default/files/pub-pdf/itgse.pdf","lv":"官方"},{"t":"《剑桥父母监控与信息管理手册》第二部分（讨论 Stattin 与 Kerr 的研究）","u":"https://www.cambridge.org/core/product/identifier/9781009418652%23bp7/type/book_part","lv":"实证"}],"art":"door","tags":["青春期","隐私","敲门"]},{"id":"ins-034","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["车上","睡前"],"mins":2,"title":"睾丸突然剧痛，马上说","body":"单独、认真地跟他说半分钟：“睾丸，就是蛋蛋，突然疼得厉害，马上告诉我，半夜也叫醒我；在学校就找校医或班主任。疼一阵自己好了也要说。咱们直接去急诊。”","more":"美国儿科学会的说法：睾丸扭转最常见于十几岁的男孩，多在青春期开始后不久；任何时候都可能发生，包括睡着的时候，有时由运动外伤引起。表现是阴囊突然剧痛，通常是一侧，可伴红肿、腹痛、恶心或呕吐。\n\n从开始疼算起，6 小时内得到处理，保住睾丸的机会超过 90%；拖过 24 小时，低于 10%。路上、检查、处理的时间都算在内，所以立刻去急诊，不排普通门诊。疼一阵自己好了也要去，因为它可能再次扭转。\n\n真正的风险是孩子不好意思说，忍到第二天。所以提前讲明：这是安全知识，没什么可难为情的。他不想听，就只说这一句，或者写张纸条。\n\n这不替代医生面诊。","refs":[{"t":"美国儿科学会 HealthyChildren：睾丸扭转","u":"https://www.healthychildren.org/English/health-issues/conditions/genitourinary-tract/Pages/Testicular-Torsion.aspx","lv":"指南"}],"art":"clock","tags":["青春期","急症","睾丸","安全"]},{"id":"ins-035","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["车上"],"mins":2,"title":"遗精：讲流程，不讲原理","body":"赶在第一次之前告诉他三样：是什么（睡着时射精，不是尿床）；怎么办（自己换条内裤，冲一下扔洗衣机，干净的在哪个柜子）；不用报告，没人会问。","more":"事先听过，遇到时是“哦，我爸说过”；没听过，他会自己慌一回，或者去网上找答案。\n\n时间来得及：全国 15011 名男孩的调查里，首次遗精的中位年龄是 14.3 岁，12 岁多数还没发生。美国儿科学会的口径是：梦遗不一定伴随性梦，长大了会停。多久一次算正常，没有机构给过数字；波士顿儿童医院面向男生的网站说，每天、一周几次、偶尔一次、从来没有，都正常。\n\n讲的时候可以加一件你自己当年的真事。只讲属实的，别现编。这不替代医生面诊。","refs":[{"t":"美国儿科学会 HealthyChildren：男孩的身体发育","u":"https://www.healthychildren.org/English/ages-stages/gradeschool/puberty/Pages/Physical-Development-Boys-What-to-Expect.aspx","lv":"指南"},{"t":"波士顿儿童医院 Young Men's Health：关于梦遗","u":"https://youngmenshealthsite.org/?p=99796","lv":"指南"},{"t":"中国城乡男孩青春期发育年龄的全国调查（PubMed 22862548）","u":"https://www.pubmed.gov/22862548/","lv":"实证"}],"art":"bed","tags":["青春期","遗精","流程"]},{"id":"ins-036","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["睡前","周末"],"mins":1,"title":"书放他书架，不用汇报","body":"挑一本讲男孩青春期的书，自己先翻一遍，再放到他书架上，只说一句：“这本写得还行，爱看不看，不用跟我汇报。”之后不问看了没有。","more":"当面说不出口的，可以交给一本书或一张纸条。文字的好处是他可以不回应，但会看。这个做法在给家长的建议里很常见，这里没有找到单独的出处，也没有对照研究；值得做，是因为成本几乎为零。儿科医生 Natterson 的原则是一种方式谈不动就换一种，书是最省事的一种换法。\n\n先自己翻一遍：知道得多了，你的尴尬会少一半，也好决定给哪本、给哪些章节。参考来源里列了两本给男孩的书，一本偏浅，一本谈得更深更直接；书目只核对到图书页面的摘要。\n\n书替不了那两条必须亲口说的安全规则。这不替代医生面诊。","refs":[{"t":"Cara Natterson 访谈：怎样读懂疏远的青春期男孩（Greater Good）","u":"https://greatergood.berkeley.edu/article/item/how_to_decode_your_aloof_teen_boy","lv":"专家意见"},{"t":"偏浅的一本：《给男孩的身体书》（凯莉·邓纳姆著）豆瓣页","u":"https://book.douban.com/subject/35200715/","lv":"专家意见"},{"t":"更深的一本：《男孩的青春期性教育》（方刚主编）豆瓣页","u":"https://book.douban.com/subject/35378066/","lv":"专家意见"}],"art":"book","tags":["青春期","书","纸条"]},{"id":"ins-037","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["饭桌","车上"],"mins":2,"title":"三条网络家规，先讲好","body":"借一条反诈新闻说三条：身体的照片视频不拍不发；陌生人让换平台、下 App、开视频，一律停；出了任何事先找爸妈，保证不骂、不没收。","more":"第三条是父母的承诺，说了就要兑现。他被人威胁“发给你全班同学”的那一刻，能让他开口的只有一样东西：事先听你说过“我只会帮你，不会骂你”。\n\n美国失踪与受虐儿童中心 2025 年收到 5 万多起金钱型性勒索举报，平均每天 137 起；美国联邦调查局称 14–17 岁男孩是最常见的目标之一，作案者常假扮同龄女孩。这是美国的数据。国内警方介绍过手法相同的裸聊敲诈，公开案例多为成年人，专门针对未成年男生的全国性通报没有查到。\n\n真碰上了：不回复、不转账，截图留证据，马上告诉爸妈，父母陪同报警。配合或付钱很少能让勒索停下；错在勒索的人，不在孩子。之后 2 周留意他的情绪。这不替代医生面诊。","refs":[{"t":"美国失踪与受虐儿童中心（NCMEC）：2025 年性勒索数据与建议","u":"https://us.missingkids.org/blog/2026/ncmec-releases-new-sextortion-data-2025","lv":"指南"},{"t":"美国联邦调查局洛杉矶分局的警示","u":"https://www.fbi.gov/contact-us/field-offices/losangeles/news/press-releases/fbi-los-angeles-field-office-warns-of-increase-in-sextortion-schemes-targeting-young-boys","lv":"官方"},{"t":"深圳市公安局：“裸聊”敲诈的常见手法","u":"https://www.sz.gov.cn/hdjl/ywzsk/gaj/xz/content/post_9577429.html","lv":"官方"}],"art":"camera","tags":["青春期","网络安全","勒索","家规"]},{"id":"ins-038","type":"insight","sub":"青春期","format":"plain","audience":"dad","for":"kid","scenes":["球场","车上"],"mins":2,"title":"告诉他：猛长在后头","body":"他提起个子，先接一句“我知道你在意个儿”，再给事实：“男生猛长一般在后头。”不承诺能长多高，也不说“你不矮啊”。","more":"医学手册的说法：男孩的身高突增发生在大约 12–16 岁之间，高峰通常在 13–14 岁。美国儿科学会描述的顺序是先发育、后蹿个，猛长的高峰在发育的后段。同一个班里，有人已经蹿了一头，有人还没动静，两种都正常。\n\n能对他说的可信的话只有这几句：猛长一般在后头；爸妈的身高决定一个大范围；能做的是睡够、吃好、多动；想知道得更准，可以一起去让医生看看生长曲线。多睡、多跳、打篮球能不能把最终身高再推高，没有证据。\n\n综合指南和医生的说法，这几种情况值得去儿童内分泌科评估一次：身高低于同龄男孩第 3 百分位，一年长得明显偏少，14 岁仍没有发育迹象，或他为此很苦恼。不自行买增高产品。这不替代医生面诊。","refs":[{"t":"MSD 诊疗手册：青少年的体格生长与性成熟","u":"https://www.msdmanuals.com/professional/pediatrics/growth-and-development/physical-growth-and-sexual-maturation-of-adolescents","lv":"指南"},{"t":"美国儿科学会 HealthyChildren：男孩的身体发育","u":"https://www.healthychildren.org/English/ages-stages/gradeschool/puberty/Pages/Physical-Development-Boys-What-to-Expect.aspx","lv":"指南"}],"art":"seedling","tags":["青春期","身高","发育","晚长"]},{"id":"ins-039","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"打球会不会耽误学习","body":"怕打球挤掉学习，是很多家长都有的顾虑，有它的道理。查到的证据是两句话：没有发现适度运动会拖累成绩；也不能说打球能提分。","more":"一项汇总 115 项研究的元分析发现，运动参与对学业成绩的平均影响是小幅正向，每周 1 到 2 小时最明显；不过纳入的研究多数质量偏低，作者自己也说还需要高质量的研究。\n\n国内一份用全国追踪数据做的重新分析发现，把学生原有的成绩考虑进去之后，“不运动”和“每天运动 1 小时”之间的差距缩小了约 85%，运动这一项整体上不再显著（预印本）。\n\n所以两头都别押：不用靠停掉打球来保学习，也别拿打球当提分的办法。要不要给打球设边界、设在哪儿，你来定。","refs":[{"t":"运动参与与学业成绩：115 项研究的元分析（PubMed 34559728）","u":"https://www.pubmed.gov/34559728/","lv":"实证"},{"t":"课外运动与学业成绩：全国追踪数据的重新分析（arXiv 预印本）","u":"https://arxiv.org/abs/2312.11484","lv":"实证"}],"art":"atom","tags":["给太太","篮球","学习"]},{"id":"ins-040","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"你不必喜欢篮球","body":"陪他去球场这件事，不必再勉强自己：不用陪打，不用每次到场，也不用学规则。对他要紧的只有一件：说起打球，他从家里感到的是支持，还是压力。","more":"咬着牙去，三个人都不舒服，这一点你最清楚。\n\n一篇汇总 20 项研究的综述提到：中途退出运动的孩子，更常说自己感到的压力更多、支持更少；父母对孩子来说可以是支持，也可以是压力。它没有哪一处要求父母自己喜欢这项运动。“勉强陪着会被孩子读成不认可”则没有直接研究，是推断。\n\n想参与，有几样轻的可以挑，一样不挑也行：他打完球回来问一句“今天痛快吗”；打完球的那顿饭由你定；他有正式比赛时一学期去看一次，往后站，只鼓掌。对打球有担心，私下跟他爸提，两个人商量。","refs":[{"t":"Chu 与 Zhang 2019：教练、同伴与父母在青少年运动中的作用（综述）","u":"https://selfdeterminationtheory.org/wp-content/uploads/2021/01/2019_ChuZhang_IJSSC_The-roles-of-coaches-peers-and-parents-in-athletes-basic-psychological-needs-A-mixed-studies-review.pdf","lv":"实证"}],"art":"hoop","tags":["给太太","篮球","不勉强"]},{"id":"ins-041","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"篮球只守两条线","body":"担心打球挤掉正事，就只盯两条：打球那天作业照常写完；照常时间上床。哪条连续亮红灯，调的是打球的时间和时长，不是取消。","more":"这两条由你来看，到学期末一起回头看守没守住。这是按几个家庭的经验做的设计，没有被验证过，照实说是推断。睡觉那条有官方依据：教育部要求初中生每天睡够 9 小时，一般不晚于 22:00 就寝。\n\n为什么只调不取消：一位家长自述，在孩子 13 岁时把他假期的打球安排全部取消，孩子在房间里又摔又砸，后来改了做法。这是自媒体上的个案，无法核实，只能当一种典型情形来看。差别在规则是事先一起定的，还是事后单方面加的。\n\n这两条夫妻俩先私下谈定，再和他商量。","refs":[{"t":"一位家长取消打球安排之后的自述（澎湃号转载的自媒体文章）","u":"https://m.thepaper.cn/newsDetail_forward_21159833","lv":"个案"},{"t":"新华社：教育部对中小学生睡眠时间的要求","u":"https://www.news.cn/politics/20260321/360bc9a864d14f16896f209895c22d97/c.html","lv":"权威媒体"}],"art":"map","tags":["给太太","篮球","作业","睡眠"]},{"id":"ins-042","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"做法不同，不等于伤孩子","body":"一个严一点、一个松一点，难免担心他钻空子。按现有的研究，做法有些不同本身问题不大，更伤他的是三样：当着他的面吵，互相拆台，让他站队。","more":"一项汇总 59 项研究的元分析把父母的配合分成四个维度：合作、一致、冲突、把孩子拉进分歧，它们与孩子的适应有小而稳定的关联（这里没有读到原文）。另一项汇总 93 项研究的元分析里，父母配合得越好，孩子的情绪和行为问题越少，相关系数约 −0.16 到 −0.17。都是相关，效应不大。\n\n所以用不着两个人变成一个人。研究工作与家庭的 Ellen Galinsky 给夫妻的建议是：各自最看重的几条互相支持，其余的事，说好可以各做各的。\n\n有两句话谁都不说：“都是你爸惯的”，“你妈就是扫兴”。可以共用的一句是：“这事我们俩商量过了。”","refs":[{"t":"Teubert 与 Pinquart 2010：共同养育与儿童适应的元分析","u":"https://www.ivysci.com/en/articles/647083__The_Association_Between_Coparenting_and_Child_Adjustment_A_MetaAnalysis","lv":"实证"},{"t":"共同养育与儿童青少年问题行为：93 项研究的元分析（PMC9407961）","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9407961","lv":"实证"},{"t":"Ellen Galinsky《Ask the Children》：给父母的建议","u":"https://www.familiesandwork.org/wp-content/uploads/2025/07/FindingFromATC.pdf","lv":"专家意见"}],"art":"family","tags":["给太太","分歧","拆台"]},{"id":"ins-043","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"你和他，另起一条线","body":"不必进入他的爱好。挑一件你自己不勉强的事，和他单独做：接送路上聊两句，一起做一道都没做过的菜，或者读一本、看一部他推荐的东西。","more":"标准只有一条：你不勉强。挑哪件、多久一次都由你定，爸爸不插手，也不问“你们聊了什么”。\n\n这几件事来自咨询师的建议：车里并排坐，问一个具体的小问题，他不想说就安静；一起做菜，从查菜谱、买菜到下锅都一起；请他推荐一本书，认真读完，主动跟他聊聊感受。把书换成片子是引申。\n\n一项追踪约 200 个家庭 7 年的研究发现，有旁人在场的亲子时间在青春期一路下降，只有父母和孩子两个人的时间，在青春期早期和中期反而增加。这里读到的是大学的新闻稿。\n\n那件事不必是篮球。","refs":[{"t":"心理咨询师王葵给青春期家庭的建议（光明网）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"},{"t":"Scary Mommy：为什么青少年在车里更愿意开口","u":"https://www.scarymommy.com/parenting/why-teens-open-up-in-the-car","lv":"专家意见"},{"t":"Penn State 对 Lam 等 2012 亲子一对一时间研究的介绍","u":"https://www.psu.edu/news/research/story/time-parents-important-teens-well-being","lv":"实证"}],"art":"pan","tags":["给太太","母子","一对一"]},{"id":"ins-044","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"女生怎么看，听你说","body":"有几件事，他从你这里听到，比从爸爸那里听到更管用：女生的青春期是怎么回事，月经不是笑话，怎么尊重女生。不用专门谈，日常带一句就行。","more":"男孩需要从一位女性那里听到女生怎么看这些事。身体那一头，清洗、遗精、刮胡子，由爸爸来讲。这个分工是按原则拟的建议，不是研究结论；他愿意找谁谈就找谁。\n\n联合国教科文组织的纲要把这一条写进了 12–15 岁的学习目标：因为青春期的变化取笑、羞辱别人是伤人的。可以从身边的事带一句：“你们班女生也在变。月经是怎么回事，你知道吗？”这句是拟写的。\n\n一项元分析里，孩子与母亲谈这些事，和日后更安全的行为之间的关联更明显；不过整体只是小幅相关，在男孩身上比女孩弱。\n\n觉得不自在就先不讲，换成一本书也可以。这不替代医生面诊。","refs":[{"t":"联合国教科文组织《国际性教育技术指导纲要》（2018 修订版）","u":"https://moldova.unfpa.org/sites/default/files/pub-pdf/itgse.pdf","lv":"官方"},{"t":"Widman 等的元分析（ScienceDaily 介绍）","u":"https://sciencedaily.com/releases/2015/11/151102125735.htm","lv":"实证"}],"art":"globe","tags":["给太太","青春期","尊重女生"]},{"id":"ins-045","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"这条急症规则你也要知道","body":"他要是说睾丸（蛋蛋）突然疼得厉害，可能还带着肚子疼、想吐：不等天亮，不排普通门诊，直接去急诊。疼一阵自己好了，也要去。","more":"爸爸会亲口跟他讲这条规则。请你也知道，是因为出事的那天晚上，在家的可能是你。\n\n美国儿科学会的说法：睾丸扭转最常见于十几岁的男孩，睡着时也可能发生。从开始疼算起，6 小时内处理，保住睾丸的机会超过 90%；拖过 24 小时，低于 10%。路上、检查、处理的时间都算在内。\n\n最大的风险是孩子不好意思说，对妈妈可能更难开口。所以他一开口，哪怕说得含糊，比如只说“肚子下面疼得厉害”，先当真，路上再问。\n\n知道流程就行，不必为它提心吊胆。这不替代医生面诊。","refs":[{"t":"美国儿科学会 HealthyChildren：睾丸扭转","u":"https://www.healthychildren.org/English/health-issues/conditions/genitourinary-tract/Pages/Testicular-Torsion.aspx","lv":"指南"}],"art":"clock","tags":["给太太","急症","睾丸","安全"]},{"id":"ins-046","type":"insight","sub":"给太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":2,"title":"他关门，多半不是躲你","body":"他话变少、爱关门、容易烦、睡得晚，当妈妈的心里不好受，很自然。按医生的观察，这多数是这个年龄的发育现象，不是关系破裂。","more":"儿科医生 Cara Natterson 的观察：男孩青春期开始得比父母以为的早，早期的变化又藏得住，父母常常不知道已经开始了。她也承认，“青春期让男孩变沉默”有没有生理基础，目前没有研究；他不说话，不等于不想谈。这是专家经验。晚睡倒有生物学上的解释：青春期生物钟后移是睡眠研究里的通行说法，他确实更晚才困。\n\n能做的很小：进他房间先敲门；想聊，挑车上那样不用对视的时候；他不接话，就先放着。\n\n要认真对待的是另一组信号：持续低落或易怒、对原来喜欢的事没了兴趣、睡眠或食欲明显改变、总说不想上学，几样同时出现并持续 2 周，先找学校心理老师或儿童青少年心理门诊。有自伤痕迹或谈到死，立即就医，或拨打心理援助热线 12356。这不替代医生面诊。","refs":[{"t":"Cara Natterson 访谈：怎样读懂疏远的青春期男孩（Greater Good）","u":"https://greatergood.berkeley.edu/article/item/how_to_decode_your_aloof_teen_boy","lv":"专家意见"},{"t":"Crowley 等 2023：帮晚睡的青少年在上学日多睡的试验（PMC9832518）","u":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9832518","lv":"实证"},{"t":"新华网：全国统一心理援助热线 12356","u":"https://www.news.cn/politics/20250508/b45e439c15bb4732858ad5c7640e9ba9/c.html","lv":"权威媒体"}],"art":"tent","tags":["给太太","关门","话少","青春期"]},{"id":"ins-047","type":"insight","sub":"和太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":1,"title":"每周 10 分钟，对一次日历","body":"周五找 10 分钟，两个人把下一周过一遍：谁哪天出差、加班，谁接送，各自哪天有安排。孩子不在场，只留一部手机看日历。","more":"时间管理作者 Laura Vanderkam 有三条规则可以直接借：周五把下一周排好；给重要的事留一个备用时段；一周做到 3 次就算习惯。经验之谈，不是研究。\n\n这 10 分钟顺带解决另一件事：分歧有了固定的去处。对孩子的做法有不同意见，留到这时候说，不在饭桌上当着他说。元分析里，父母之间的冲突、把孩子拉进分歧，都与孩子的适应问题相关（相关，效应小）。\n\n只排日历，不清算谁做得多、谁做得少。排完各忙各的。","refs":[{"t":"Laura Vanderkam《Tranquility by Tuesday》书摘","u":"https://lauravanderkam.com/wp-content/uploads/2022/09/TBT-Excerpt.pdf","lv":"专家意见"},{"t":"Teubert 与 Pinquart 2010：共同养育与儿童适应的元分析","u":"https://www.ivysci.com/en/articles/647083__The_Association_Between_Coparenting_and_Child_Adjustment_A_MetaAnalysis","lv":"实证"}],"art":"table","tags":["夫妻","日历","分工"]},{"id":"ins-048","type":"insight","sub":"和太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":1,"title":"今天谢她一件具体的小事","body":"今天对她说一句带细节的谢谢。不是“辛苦了”，而是“早上那个电话是你打的，我省了半天心”。说完就完，后面不跟任何要求。","more":"没有研究专门检验过“谢得具体”，这一条是引申。它借的是 Gottman 夫妻研究的思路：他追踪新婚夫妇 6 年，婚姻延续下来的那些，平时更常接住对方递过来的话头。一句带细节的谢谢，是你主动递过去的一个话头。\n\n道理和夸孩子一样：说得出细节，才证明你真的看见了。\n\n两个注意：不当着孩子的面表演；后面不接“不过”。她怎么回都行，不回也行。","refs":[{"t":"Gottman Institute：回应伴侣的“邀请”","u":"https://www.gottman.com/blog/turn-toward-instead-of-away/","lv":"实证"}],"art":"pouch","tags":["夫妻","感谢"]},{"id":"ins-049","type":"insight","sub":"和太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":1,"title":"吃一顿不谈孩子的饭","body":"这个月约她吃顿饭，规矩只有一条：不谈孩子，不谈学校。找一家两个人都没去过的小馆子，聊她最近在看什么、烦什么。","more":"没有研究直接检验过“不谈孩子的饭”，这是推断出来的做法。离它最近的证据是 Aron 等人的实验：夫妻一起做 7 分钟新奇、有点刺激的任务，关系质量的提升比做平淡任务更大。那是实验室里的任务，换成一顿饭是类推；所以挑一家没去过的店，比去老地方多一点用处。\n\n为什么把孩子的话题关在门外：两个人一坐下就对账，谁接送、谁签字、他最近怎么样，这顿饭就成了又一次家庭会议。\n\n谁先提孩子，谁买单。聊不满一顿饭也没关系，安静吃完也算。","refs":[{"t":"Aron 等 2000：夫妻共同参与新奇活动的实验（PubMed 10707334）","u":"https://pubmed.ncbi.nlm.nih.gov/10707334/","lv":"实证"}],"art":"pizza","tags":["夫妻","约会","吃饭"]},{"id":"ins-050","type":"insight","sub":"和太太","format":"plain","audience":"dad","for":"wife","scenes":[],"mins":1,"title":"她随口一句，先抬头","body":"她随口说“你看这个”“今天真累”，那是在递话。放下手机，抬头，应一声，哪怕只是“怎么了”。先别急着出主意。","more":"Gottman 把这种随口一句叫作向对方发出的“邀请”：你可以接，也可以不接。他追踪新婚夫妇 6 年：婚姻延续下来的，接住的比例是 86%；后来离婚的，是 33%。数字来自 Gottman 研究所的介绍文章，原始论文没有核对，只看方向。\n\n接住不需要长谈，抬头、应声、问一句就算。最常见的漏接不是吵架，是眼睛没离开屏幕的那声“嗯”。\n\n同一个动作对孩子也成立，不过那是类推：他一句“爸你看这个球”，也是一次邀请。","refs":[{"t":"Gottman Institute：回应伴侣的“邀请”","u":"https://www.gottman.com/blog/turn-toward-instead-of-away/","lv":"实证"}],"art":"music","tags":["夫妻","回应","手机"]},{"id":"ins-051","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":2,"title":"他盼的是你别那么累","body":"一项调查让孩子许一个关于父母工作的愿望。排第一的不是“多陪我”，是“别那么累、别那么大压力”。今晚推掉一件可去可不去的事，早睡半小时。","more":"这是 Ellen Galinsky 的《Ask the Children》调查，对象是全美 1023 名 8–18 岁的孩子。希望多些时间的，对母亲是 10%，对父亲是 15.5%；希望父母别那么累、别那么大压力的，是 34% 和 27.5%。猜中这个愿望的父母只有 2%。\n\n边界：Galinsky 自己强调，这不等于时间不重要，她的数据里时间多少和在一起时的状态都算数。调查是 20 多年前在美国做的，问的是感受，不是因果。\n\n一个累到只想戴上耳机的爸爸，再多的球场时间也是人在心不在。","refs":[{"t":"Ellen Galinsky《Ask the Children》调查（1999）","u":"https://www.familiesandwork.org/wp-content/uploads/2025/07/FindingFromATC.pdf","lv":"实证"}],"art":"battery","tags":["给自己","累","压力"]},{"id":"ins-052","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"只记两个数","body":"手机备忘录里只记两个数：这周取消了几次约好的事，陪他的时候掏了几次手机。不写反思，不打分，周五看一眼是不是在往下走。","more":"孩子那边的信号都很主观；这两个数是你自己的行为，最客观，也最不会骗人。这是推断出来的建议，不是研究结论。\n\n为什么数掏手机的次数：一项在科学博物馆做的现场实验里，被要求少用手机的父母没那么分心，觉得和孩子的联结更强（测的是父母自己的感受）。\n\n王阳明在《传习录》里说得不客气：“知而不行，只是未知。”知道该放下手机，和这周掏了几次，是两件事。\n\n数字难看也照记。管理者都懂，没有度量就没有改进，只是这回考核的是自己。","refs":[{"t":"研究者在 SPSP 网站上对博物馆手机实验的介绍","u":"https://spsp.org/news-center/character-context-blog/parents-disconnecting-your-phone-can-increase-connection-your","lv":"实证"},{"t":"王阳明《传习录》上卷（徐爱录）","lv":"经典"}],"art":"scoreboard","tags":["给自己","手机","记数"]},{"id":"ins-053","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":2,"title":"20 分钟，但人在","body":"今天只有 20 分钟也去。下楼前把手机留在家里，这 20 分钟只做他想做的那件事：不提要求，不盘问，不批评。到点收工，不算亏欠。","more":"话说在前头：没有任何研究给出陪伴的“最小有效剂量”，也没有实验直接比较过“专注 20 分钟”和“分心 2 小时”。“宁可短，但人要在”是从间接证据推出来的。\n\n间接证据有两条。时间日记研究里，12–18 岁的孩子，父母的投入式时间越多，越轨行为和行为问题越少（相关，不是因果）。华盛顿大学给家长的一份临床讲义，建议每周 3 次、每次 15–20 分钟，做孩子喜欢的事，其间少提问、不指挥、不纠正；它还说，出问题的日子，这段时间更要有。\n\n这不是说时间长短无所谓，只是别因为短就干脆不去。","refs":[{"t":"PRB 对 Milkie 等 2015 时间日记研究的介绍","u":"https://www.prb.org/resources/time-with-parents-key-for-adolescents/","lv":"实证"},{"t":"华盛顿大学给青少年家长的训练讲义","u":"https://depts.washington.edu/hcsats/PDF/TF-%20CBT/pages/8%20Parent%20Management%20Training/How%20to%20get%20your%20teen%20%20to%20want%20to%20be%20good.pdf","lv":"专家意见"}],"art":"hourglass","tags":["给自己","时间","专注"]},{"id":"ins-054","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"错了就修，不求不犯","body":"今天又没忍住、又掏了手机、又放了他鸽子，先别带着一肚子懊恼去找他。对自己认一句“这事是我做错了”，缓过来，再去跟他说那三句：发生了什么，这是我的问题，下次我会怎么做。","more":"临床心理学家 Becky Kennedy 把这叫“修复”：没有不犯错的父母，要练的是事后怎么修。她还说，先跟自己修复，别带着羞愧去找孩子。这是专家经验，她的例子里孩子只有六七岁，用在 12 岁的孩子身上是改写。\n\n《论语·子张》里子贡说，君子的过错像日食月食：“过也，人皆见之；更也，人皆仰之。”错，孩子本来就看得见；他没怎么见过的，是一个成年人怎么认错、怎么改。\n\n你在家里怎么处理自己的错，他多半就学着怎么处理他的。最后这句是推断。","refs":[{"t":"Becky Kennedy 谈“修复”（NPR）","u":"https://www.npr.org/2023/10/06/1203898492/no-parent-is-perfect-so-try-to-get-good-at-repair","lv":"专家意见"},{"t":"《论语·子张》","lv":"经典"}],"art":"puzzle","tags":["给自己","修复","认错"]},{"id":"ins-055","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":2,"title":"不必喜欢他喜欢的","body":"他迷的球星、游戏、梗，你不用假装也喜欢。只做一件事：请他给你讲 5 分钟，你只问不评，不说“这有什么用”。","more":"一篇汇总 20 项研究的综述提到：中途退出运动的孩子，更常说自己感到的压力更多、支持更少。父母要给的是支持，文献里没有哪一条要求父母自己喜欢这件事。\n\n一位从小对运动没兴趣的美国爸爸，孩子的训练和比赛每场都到，说感觉像两个人一起在学。他靠的不是兴趣，是到场（个案）。\n\n也别拿“研究说一起打游戏能增进父子感情”当理由硬凑：常被引用的那项研究有 287 名青少年，只在女孩身上看到了关联，男孩身上没有。他邀你玩一局，接住就好。装懂，12 岁的孩子一眼看得穿；当个不装懂的“老登”，反而体面。","refs":[{"t":"Chu 与 Zhang 2019：教练、同伴与父母在青少年运动中的作用（综述）","u":"https://selfdeterminationtheory.org/wp-content/uploads/2021/01/2019_ChuZhang_IJSSC_The-roles-of-coaches-peers-and-parents-in-athletes-basic-psychological-needs-A-mixed-studies-review.pdf","lv":"实证"},{"t":"Clint Edwards：不爱运动的爸爸怎样陪孩子打球（Scary Mommy）","u":"https://www.scarymommy.com/hated-sports-child-started-playing","lv":"个案"},{"t":"Coyne 等 2011：父母与青少年一起玩电子游戏的研究","u":"https://scholarsarchive.byu.edu/facpub/2379","lv":"实证"}],"art":"gamepad","tags":["给自己","兴趣","游戏"]},{"id":"ins-056","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":2,"title":"先把自己睡够","body":"给他定的睡觉和运动两条，你先照做一周：到点上床，手机不进卧室；每周 3 次出汗的运动。陪他打球可以算数，前提是你真跑起来了。","more":"给孩子定这两条有依据：教育部要求初中生每天睡够 9 小时；一项汇总 13 项随机对照试验、433 名青少年的元分析显示，运动对青少年抑郁有中等幅度的改善。这些证据的对象是青少年，“你也照做”是常识加推断。时间管理作者 Vanderkam 给成年人的第一条规则倒是现成的：给自己定个上床时间。\n\n和你直接有关的是另一项：汇总 16 项观察性研究的元分析发现，父亲抑郁与子女抑郁风险升高相关，比值比约 1.42。这是相关，不是因果；它的意思只是，父亲自己的状态值得当回事。\n\n情绪低落、睡不好、对什么都提不起劲，持续 2 周以上，就去看医生，和你劝他的标准一样。这不替代医生面诊。","refs":[{"t":"JAMA Network Open 2023：父亲抑郁与子女抑郁风险的元分析","u":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10433087/","lv":"实证"},{"t":"运动干预与青少年抑郁：随机对照试验的元分析（PMC9846179）","u":"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9846179/","lv":"实证"},{"t":"新华社：教育部对中小学生睡眠时间的要求","u":"https://www.news.cn/politics/20260321/360bc9a864d14f16896f209895c22d97/c.html","lv":"权威媒体"},{"t":"Laura Vanderkam《Tranquility by Tuesday》书摘","u":"https://lauravanderkam.com/wp-content/uploads/2022/09/TBT-Excerpt.pdf","lv":"专家意见"}],"art":"bike","tags":["给自己","睡眠","运动"]},{"id":"ins-057","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"进门前，停 3 分钟","body":"到家先别上楼。在车里或楼下待 3 分钟：最后一条消息回完，手机调静音，想好进门第一句不是“作业写了吗”。然后再开门。","more":"研究工作与家庭的 Ellen Galinsky 给父母的建议里就有这一条：练几个从工作切换到回家的办法，比如下班前静一静、听听音乐、到家换身衣服，再给孩子一个固定的进门仪式。这是她的经验之谈；“3 分钟”是这里凑的整数，没有研究。\n\n马可·奥勒留在《沉思录》卷四第 3 节写过一段，大意是：人们总想躲到乡间、海边去求清静，其实随时可以退回自己心里待一会儿，再回来面对该面对的事。这是转述，不是原文。\n\n3 分钟里不解决工作，只是把它放下。它明天还在，跑不了。","refs":[{"t":"Ellen Galinsky《Ask the Children》：给父母的建议","u":"https://www.familiesandwork.org/wp-content/uploads/2025/07/FindingFromATC.pdf","lv":"专家意见"},{"t":"马可·奥勒留《沉思录》卷四第 3 节（转述）","lv":"经典"}],"art":"briefcase","tags":["给自己","下班","切换"]},{"id":"ins-058","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"先定今天注意力给谁","body":"早上花 1 分钟定两件事：今天工作上最值得全神贯注的一件，和到家后要完整给出 15 分钟的一个人。其余的，允许自己只用七分力。","more":"日历管的是时间，真正不够用的是注意力：人到了，会开了，饭吃了，心思不在，等于没到。\n\n苏轼在《记承天寺夜游》里写月色和竹柏的影子，结尾一句是：“但少闲人如吾两人者耳。”月亮和竹柏哪天都有，缺的是腾得出心思看一眼的人。他那时被贬在黄州，是个闲人；你不是，所以得预先分配。\n\n孩子这头有一条调查线索：孩子评价父母，除了看时间多少，还看那段时间父母能不能真的专注在自己身上（Galinsky 对全美 1023 名孩子的调查，问的是感受）。“七分力”是经验之谈，没有出处。","refs":[{"t":"苏轼《记承天寺夜游》","lv":"经典"},{"t":"Ellen Galinsky《Ask the Children》调查（1999）","u":"https://www.familiesandwork.org/wp-content/uploads/2025/07/FindingFromATC.pdf","lv":"实证"}],"art":"telescope","tags":["给自己","注意力","工作"]},{"id":"ins-059","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"一次只做一件事","body":"今天挑一个会，全程不看手机、不回消息；再挑一顿饭，同样。就这两处，其余照旧。做完看看耽误了什么，多半什么都没耽误。","more":"塞涅卡在《致鲁基里乌斯书信》第二封里劝朋友读书别东翻西翻，有一句大意是：到处都在的人，其实哪儿也不在。这是转述。他说的是读书，搬到会议室和饭桌上一样成立。\n\n孩子这头有相关的证据：一项汇总 15 篇文献、2.2 万多人的元分析发现，父母低头看手机与青少年抑郁症状的相关约为 0.31；样本几乎都来自中国的中学生，是相关，说明不了因果。\n\n“多任务拖累效率”的说法你大概听过不少，这里不引，手头的材料没有覆盖。只说能验证的：自己试两处，看结果。","refs":[{"t":"塞涅卡《致鲁基里乌斯书信》第二封（转述）","lv":"经典"},{"t":"父母低头看手机与青少年抑郁症状的元分析（2024）","u":"https://ifp.nyu.edu/2024/meta-analyses-systematic-reviews/s40894-024-00244-0/","lv":"实证"}],"art":"chess","tags":["给自己","专注","工作","开会"]},{"id":"ins-060","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"今天只复盘一件事","body":"睡前不过电影，只问自己一句：今天哪件事重来一次，我会换个做法。想清楚换成什么做法就收工，不开自我批斗会。","more":"《论语·学而》里曾子说“吾日三省吾身”，一天反省三件：替人办事尽没尽心，与朋友交往守没守信，学到的东西练了没有。那是圣贤的规格，中年人打个折，一天一件就够。\n\n只挑一件，是因为复盘的用处在于明天能改一个动作，不在于清点今天所有的不是。经典实验发现，近处的小目标比远处的大目标更能提升自我效能；那是在孩子身上做的，用在你身上是类推。\n\n想不出哪件要重来，就算今天过关，睡觉。","refs":[{"t":"《论语·学而》","lv":"经典"},{"t":"Bandura 与 Schunk 1981：近端目标与自我效能","u":"https://uploads-ssl.webflow.com/59faaf5b01b9500001e95457/5bc552d85141987915dab842_Bandura%20&%20Schunk,%201981.pdf","lv":"实证"}],"art":"brain","tags":["给自己","复盘","工作"]},{"id":"ins-061","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"没做到，下周照常","body":"出差、加班把约好的事冲掉了，就认一句“这周没做到”。不补偿，不拿一次大出游赎罪，不写检讨。下周同一时间，照常下楼。","more":"时间管理作者 Laura Vanderkam 有一条规则：一周做到 3 次就算习惯。她的理由是，一件事不必天天做，也能成为你的一部分。标准从来不是一次不落。这是经验之谈。\n\n“出差、加班一断就没了下文”是最常见的失败之一。补救的办法：缩成 15 分钟也算；断了一周不补偿，下周照常。这是综合几位作者经验的建议，不是研究结论。\n\n《道德经》第二十三章说：“飘风不终朝，骤雨不终日。”狂风刮不了一早上，暴雨下不了一整天。糟糕的一周也会过去，用不着拿一场大出游去抵。","refs":[{"t":"Laura Vanderkam《Tranquility by Tuesday》书摘","u":"https://lauravanderkam.com/wp-content/uploads/2022/09/TBT-Excerpt.pdf","lv":"专家意见"},{"t":"《道德经》第二十三章","lv":"经典"}],"art":"kite","tags":["给自己","没做到","坚持"]},{"id":"ins-062","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"给要紧事留个备用档","body":"周五下午排下周时，给最要紧的一两件事各配一个备用时段，像给重要会议多订一间会议室。第一个时段被冲掉，直接挪过去。","more":"这是时间管理作者 Laura Vanderkam 的两条规则：周五把下一周排好；给重要的事留一个备用时段，她的说法是让日程经得起折腾。经验之谈，没有研究检验，成本只是日历上多占一格。\n\n它对付的是管理者最熟悉的那种失败：重要但不紧急的事，总被临时的会冲掉，然后“下次再说”。有了备用档，被冲掉就不等于取消。\n\n不只为了孩子：体检、锻炼、那本一直没读的书，都可以这么排。连备用档也被冲掉的那一周，说明这件事在你心里没排那么靠前，至少先对自己承认。","refs":[{"t":"Laura Vanderkam《Tranquility by Tuesday》书摘","u":"https://lauravanderkam.com/wp-content/uploads/2022/09/TBT-Excerpt.pdf","lv":"专家意见"}],"art":"calendar","tags":["给自己","日程","工作"]},{"id":"ins-063","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":1,"title":"今天砍掉一件事","body":"打开今天的日程，对每一项问一句“这件事非做不可吗”。找出最不必要的那个会、那份汇报或那场饭局，推掉，或者砍一半。","more":"马可·奥勒留在《沉思录》卷四第 24 节引了一位哲人的话，大意是“想要安宁，就少做些事”，然后补了一句：更好的说法是只做必要的事。我们说的话、做的事大半并无必要，去掉它们，人就多些闲暇，少些烦乱；所以每件事都该问一句，这是不是不必要的。以上是转述，不是原文。\n\n他是罗马皇帝，日程不会比你松。\n\n这一条没有实证研究，只有一位 2000 年前的同行的经验。它和陪孩子的关系只是算术：那 40 分钟的球，总得从别处省出来。","refs":[{"t":"马可·奥勒留《沉思录》卷四第 24 节（转述）","lv":"经典"}],"art":"paper-plane","tags":["给自己","日程","工作","取舍"]},{"id":"ins-064","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":2,"title":"把烦心事分成两栏","body":"拿张纸画一条竖线。左边写今天烦的事里你能做点什么的，右边写你做不了主的。左边每条配一个明天的动作；右边看完，把纸翻过去。","more":"这是爱比克泰德《手册》第 1 节的意思：有些事取决于我们，有些不取决于我们。取决于我们的是自己的看法、追求和行动；不取决于我们的是身体、财产、名声、职位。以上是转述，不是原文。\n\n放到眼前：老板怎么想、别人怎么评价你的孩子、他以后长多高，在右栏；你今晚几点下楼、说哪句话、掏不掏手机，在左栏。\n\n这不是研究结论，是一个用了 2000 年的整理办法。分完栏，事情不会变少，只是你不再用左栏的力气去推右栏的墙。","refs":[{"t":"爱比克泰德《手册》第 1 节（转述）","lv":"经典"}],"art":"compass","tags":["给自己","焦虑","工作"]},{"id":"ins-065","type":"insight","sub":"给自己","format":"plain","audience":"dad","for":"self","scenes":[],"mins":2,"title":"火气上来，先问为了谁","body":"听到别人给他下了个不好听的评语，火气上来时先问自己：我是想护着他，还是觉得自己被打了差评。是后一种，今晚先别开口。","more":"觉得被冒犯很正常。一项对 215 对中美母子的研究发现，中国母亲的自我价值更多地系在孩子的表现上，论文的副标题就叫“孩子是我的成绩单”。研究的是母亲，套到父亲身上是推论。\n\n两层火气导向不同的动作：护着他那一层，导向“我去弄清他的真实情况”；被打差评那一层，容易变成给他加压，或者跟对方硬顶，最后都落在他身上。还有一种更隐蔽的：“你得争口气给他们看。”听着像撑腰，其实是把他的价值绑在了能不能翻盘上。\n\n你带团队时说过“对事不对人”。回到家，这句话最难做到。他不是你的绩效。","refs":[{"t":"Ng、Pomerantz 与 Deng 2014：“孩子是我的成绩单”","u":"https://typeset.io/pdf/why-are-chinese-mothers-more-controlling-than-american-1rfcdok6iz.pdf","lv":"实证"}],"art":"trophy","tags":["给自己","愤怒","评价"]},{"id":"play-101","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["车上","饭桌","出差"],"mins":10,"title":"3、3、8、8，能算出 24 吗","body":"4 个数都要用上，加减乘除随便用。这是 24 点里最出名的一道难题，卡上半个小时都算正常。","widget":"make24","params":{"nums":[3,3,8,8],"level":"hard"},"cta":"开算","hint":"别给提示，尤其别说“试试分数”。你也真下场算，算不出来就认：这题我也不会。","more":"13 以内任取 4 张牌，一共有 1820 种组合，其中 1362 种能算出 24。这一题属于最刁钻的那一小撮：凑 3×8、凑 4×6 的老办法全都不灵。\n\n实在卡死了，游戏里的「提示」一次只走一步。够用就停，剩下的自己来。","refs":[{"t":"24 点：经典的扑克牌算术游戏","u":"https://en.wikipedia.org/wiki/24_(puzzle)","lv":"经典"}],"art":"cards","tags":["24点","算术","难题"]},{"id":"play-102","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["车上","饭桌","出差"],"mins":10,"title":"1、5、5、5 凑出 24","body":"三个 5 加一个 1，四张牌都得用上。看着像送分题，其实是 24 点里有名的坑，不少大人都栽在这儿。","widget":"make24","params":{"nums":[1,5,5,5],"level":"hard"},"cta":"试试","hint":"这题你多半也算不出，正好。抓耳挠腮给他看，别装胸有成竹，更别偷偷查答案。","more":"它的门道在于：中间可以先算出一个不是整数的数，最后再把它乘回来。\n\n想到这一步，就只差临门一脚了。","refs":[{"t":"24 点的经典难题","lv":"经典"}],"art":"brain","tags":["24点","算术","难题"]},{"id":"play-103","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["车上","饭桌","周末"],"mins":8,"title":"4、4、10、10，敢不敢","body":"两个 4，两个 10。凑 3×8、凑 4×6 那套老办法在这儿全不灵，得换一条路走。","widget":"make24","params":{"nums":[4,4,10,10],"level":"hard"},"cta":"敢","hint":"他先算出来的话，别接“我也快了”。请他把步骤讲一遍，你只管听，听完说一句“原来这样”。","more":"换的那条路是：先把数乘得很大，再减、再除回来。\n\n24 点里要“先变大再变小”的题不多，这是最有名的一道。","refs":[{"t":"24 点的经典难题","lv":"经典"}],"art":"target","tags":["24点","算术","难题"]},{"id":"play-104","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["车上","饭桌","出差"],"mins":10,"title":"1、3、4、6：一块硬骨头","body":"4 个小数字，看着人畜无害，却是 24 点里公认的硬骨头。提醒一句：除以一个比 1 小的数，结果会变大。","widget":"make24","params":{"nums":[1,3,4,6],"level":"hard"},"cta":"啃一下","hint":"他嫌难想放弃时，别劝“再坚持一下”。说“那先放着，谁先想出来谁发消息”，然后你真去想。","more":"除以二分之一等于乘以 2，除以四分之一等于乘以 4。所以“先凑出一个分数，再拿别的数去除它”，是 24 点里一条很少有人走的路。\n\n这道题和 3、3、8、8 是同一个路数。","refs":[{"t":"24 点的经典难题","lv":"经典"}],"art":"puzzle","tags":["24点","算术","难题"]},{"id":"play-105","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["车上","饭桌","出游"],"mins":5,"title":"4 个数字，几次能猜中","body":"手机藏了 4 个各不相同的数字。每猜一次，它只回一句“几 A 几 B”：A 是数字和位置都对，B 是数字对、位置不对。","widget":"bulls","params":{"mode":"solo"},"cta":"开猜","hint":"两个人合猜，轮流报数。他的推理绕远了也先照他的来，别抢着说“明显是 7”。","more":"有人算过：只要打法得当，不管谜底是什么，7 次以内一定能猜中。\n\n一个好用的开局：先猜 0123，再猜 4567。把两次的 A 和 B 全加起来，用 4 一减，就知道 8 和 9 里藏着几个。","refs":[{"t":"猜数字（Bulls and Cows）","u":"https://en.wikipedia.org/wiki/Bulls_and_Cows","lv":"经典"}],"art":"magnifier","tags":["猜数字","推理","1A2B"]},{"id":"play-106","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","出游"],"mins":8,"title":"我出 4 个数，你来猜","body":"一个人偷偷输入 4 个不重复的数字，另一个人来猜，手机当裁判报“几 A 几 B”。猜中了就交换，比谁用的次数少。","widget":"bulls","params":{"mode":"duo"},"cta":"出题","hint":"让他先出题。你猜的时候把推理说出声，说错了也照说。被他纠正了就认，别嘴硬。","refs":[{"t":"猜数字（Bulls and Cows）","u":"https://en.wikipedia.org/wiki/Bulls_and_Cows","lv":"经典"}],"art":"key","tags":["猜数字","推理","双人"]},{"id":"play-107","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":2,"title":"抢 21：电脑有个秘密","body":"一堆 21 颗石子，你和电脑轮流拿，每次 1 到 3 颗，拿到最后一颗的赢。它赢多输少，因为它知道一个秘密。","widget":"nim","params":{"game":"take21","vs":"ai","last":"win","ease":0.15},"cta":"抢","hint":"每局结束会出现「必胜秘诀」，先别点。你也跟电脑死磕几局，输了就认。谁先看出门道谁讲，多半是他。","more":"线索：每一局都留意一下，你拿完、电脑也拿完之后，还剩多少颗。把这些数排在一起看。\n\n电脑偶尔会走神，抓住那一下。","refs":[{"t":"取子游戏（尼姆游戏的一种）","u":"https://en.wikipedia.org/wiki/Nim","lv":"经典"}],"art":"dice","tags":["取石子","必胜策略","抢21"]},{"id":"play-108","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","出游"],"mins":2,"title":"反着抢：拿最后一颗的输","body":"还是 21 颗，每次拿 1 到 3 颗。但这回谁拿到最后一颗谁输。橙方蓝方，两个人在一部手机上对着干。","widget":"nim","params":{"game":"take21","vs":"duo","last":"lose"},"cta":"对抢","hint":"输了就认，别说“我让着你”。他连赢几把之后问一句：你是不是发现什么了？然后闭嘴听。","more":"规则一反，先走的人就从占便宜变成了吃亏。想知道为什么，打完一局点开「必胜秘诀」。","refs":[{"t":"取子游戏（尼姆游戏的一种）","u":"https://en.wikipedia.org/wiki/Nim","lv":"经典"}],"art":"chess","tags":["取石子","必胜策略","双人"]},{"id":"play-109","type":"play","sub":"数字","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":8,"title":"3 堆石子，电脑凭什么老赢","body":"3 堆石子：3 颗、5 颗、7 颗。轮流从其中一堆里拿，拿几颗都行，拿到最后一颗的赢。电脑心里有本账，你得把这本账算出来。","widget":"nim","params":{"game":"heaps","vs":"ai","last":"win","ease":0.35},"cta":"开拿","hint":"这个比抢 21 难得多，输是常态。输了一起复盘“它刚才为什么那么拿”，别点开秘诀念给他听。","more":"这个游戏叫尼姆（Nim）。100 多年前就有数学家把它彻底算清楚了：任何一个局面，先手是必胜还是必输，都有定论。\n\n秘诀藏在“把每一堆拆成 4、2、1”里，打完一局可以看。","refs":[{"t":"C. L. Bouton (1901), Nim, a game with a complete mathematical theory","lv":"经典"},{"t":"Nim · Wikipedia","u":"https://en.wikipedia.org/wiki/Nim","lv":"经典"}],"art":"brain","tags":["取石子","尼姆","必胜策略"]},{"id":"play-110","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前","出游"],"mins":2,"title":"7 步，把塔搬过去","body":"3 个盘子从小到大叠成一座塔。一次只能搬一个，大的不能压小的。最少 7 步，多一步都算输。","widget":"hanoi","params":{"discs":3},"cta":"搬","hint":"3 层太简单就点「+」加层。他搬的时候别在旁边报步数，那跟站在罚球线旁边喊“别紧张”一样。","refs":[{"t":"Tower of Hanoi · Wikipedia","u":"https://en.wikipedia.org/wiki/Tower_of_Hanoi","lv":"经典"}],"art":"puzzle","tags":["汉诺塔","递归"]},{"id":"play-111","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":6,"title":"64 层的塔要搬多久","body":"传说有座 64 层的金塔，全搬完的那天世界就结束了。先拿 5 层练手：最少 31 步，你用几步？","widget":"hanoi","params":{"discs":5},"cta":"先搬 5 层","hint":"等他搬完再问：那 64 层要多少步？让他先猜一个数，再点「展开」看答案。猜小了一起笑。","more":"每加一层，步数就翻一倍再加 1：3 层 7 步，4 层 15 步，5 层 31 步……n 层最少要 2 的 n 次方减 1 步。\n\n64 层就是 18446744073709551615 步。1 秒搬一步、不吃不睡，大约要搬 5800 亿年，而宇宙到现在才 138 亿岁左右。\n\n这个游戏是法国数学家卢卡斯在 1883 年发明的，那个传说也是跟着它一起流传开的。","refs":[{"t":"Tower of Hanoi · Wikipedia","u":"https://en.wikipedia.org/wiki/Tower_of_Hanoi","lv":"经典"}],"art":"hourglass","tags":["汉诺塔","递归","指数"]},{"id":"play-112","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前","出游"],"mins":2,"title":"2 分钟的小数独","body":"4×4 的迷你数独：每一行、每一列、每个小方块里，1 到 4 各出现一次。填撞车了会变红。","widget":"sudoku","params":{"size":4,"check":true},"cta":"填","hint":"一人填一格，轮着来。轮到他时别伸手指“这儿这儿”，等他自己找。","refs":[{"t":"数独（迷你版）","lv":"经典"}],"art":"pencil","tags":["数独","逻辑"]},{"id":"play-113","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["睡前","周末","出游"],"mins":10,"title":"6×6 数独：不许瞎蒙","body":"升级版：6 行 6 列，每个 2×3 的小宫里 1 到 6 各一次。答案只有一个，得一格一格推出来。","widget":"sudoku","params":{"size":6,"check":true,"level":"normal"},"cta":"开填","hint":"这个得十来分钟，适合睡前安静地并排做。他卡住时问一句“哪一行最挤”，别直接报数字。","more":"入门口诀只有一条：找最挤的地方下手。哪一行、哪一列或者哪个小宫里的空格最少，就先看那里还缺谁。\n\n题目是手机现出的，保证只有一个解。","refs":[{"t":"数独（迷你版）","lv":"经典"}],"art":"calendar","tags":["数独","逻辑"]},{"id":"play-114","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前","出游"],"mins":2,"title":"9 盏灯，全关掉","body":"点一盏灯，它和上下左右的邻居一起变：亮的灭，灭的亮。想办法让 9 盏灯全灭。听着简单，上手就乱。","widget":"lights","params":{"size":3},"cta":"关灯","hint":"他乱按的时候别说“你得有策略”。你也乱按一局，比谁步数少，输了就认。","refs":[{"t":"关灯谜题（经典的翻转类逻辑题）","lv":"经典"}],"art":"bulb","tags":["关灯","逻辑"]},{"id":"play-115","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["睡前","周末","出游"],"mins":8,"title":"25 盏灯的大麻烦","body":"5×5 的关灯：每按一下牵动一片，按下葫芦浮起瓢。上面写着最少要几步，能压到那个数吗？","widget":"lights","params":{"size":5,"level":"normal"},"cta":"试试","hint":"卡住了有「提示」，用不用让他自己定。你别替他点，也别在旁边数他用了几次。","more":"两个小秘密：\n\n- 同一盏灯按两次等于没按，所以每盏灯最多只需要按一次\n- 先按哪盏后按哪盏不影响结果，要紧的只是“按了哪几盏”\n\n所以乱按没有用，得想清楚按哪几盏。","refs":[{"t":"关灯谜题（经典的翻转类逻辑题）","lv":"经典"}],"art":"moon","tags":["关灯","逻辑"]},{"id":"play-116","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前","出游"],"mins":2,"title":"12 张牌，你能记住几张","body":"6 对图案扣在桌上。一次翻 2 张，一样就留下，不一样就扣回去。全翻开用的步数越少越厉害。","widget":"memory","params":{"pairs":6,"players":1},"cta":"翻牌","hint":"两个人合作：一个翻，一个负责记位置，下一局换过来。他记得比你准的时候，直说“这我真不行”。","refs":[{"t":"记忆翻牌（配对游戏）","lv":"经典"}],"art":"cards","tags":["记忆","翻牌"]},{"id":"play-117","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前","出游"],"mins":5,"title":"翻牌对决：谁的脑子好使","body":"20 张牌，两个人轮流翻。翻出一对就归你，还能接着翻；翻错了换人。最后数谁的对子多。","widget":"memory","params":{"pairs":10,"players":2},"cta":"对决","hint":"这个游戏大人未必占便宜。别放水，认真输；输了让他定下一局的规矩。","refs":[{"t":"记忆翻牌（配对游戏）","lv":"经典"}],"art":"trophy","tags":["记忆","翻牌","双人"]},{"id":"play-118","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["饭桌","睡前","周末","出游"],"mins":8,"title":"一笔画完，不许回头","body":"手指从一个点出发，沿着线走，每条线只能走一次，要把整张图走完。前几关送分，后面有一关有诈。","widget":"onestroke","params":{"level":1},"cta":"动笔","hint":"到第 6 关他会卡很久，那是故意的。忍住别说破，等他自己喊出“这根本画不出来”。","refs":[{"t":"一笔画问题","lv":"经典"}],"art":"pencil","tags":["一笔画","图形"]},{"id":"play-119","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":6,"title":"7 座桥，每座只走一次","body":"一座城，一条河，两个岛，7 座桥。能不能散一次步，把 7 座桥各走一遍、每座只走一次？快 300 年前，这是那座城里出了名的难题。","widget":"onestroke","params":{"level":6},"cta":"走走看","hint":"答案是“走不通”，但别说破，也别使眼色。你也认真走几遍，走不通就嚷“再来”。「画不出来？」留给他自己点。","more":"这道题有个大名：哥尼斯堡七桥问题。1736 年，数学家欧拉把陆地看成点、把桥看成线，一下子把它想明白了，还顺手开出了一门新学问：图论。\n\n他到底想明白了什么？先自己走几遍再说。","refs":[{"t":"Seven Bridges of Königsberg · Wikipedia","u":"https://en.wikipedia.org/wiki/Seven_Bridges_of_K%C3%B6nigsberg","lv":"经典"}],"art":"map","tags":["一笔画","七桥问题","欧拉"]},{"id":"play-120","type":"play","sub":"数学魔术","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","周末","出游"],"mins":2,"title":"想一个数，我能读出来","body":"在心里想一个 1 到 63 的数，别说出口。手机给你看 6 张卡片，你只用回答“有”或“没有”，它就知道你想的是几。","widget":"mindread","params":{},"cta":"读心","hint":"先让手机读他的心。他想破解就由他多试几次，「揭秘」留给他自己点。学会了，请他对妈妈表演一遍。","refs":[{"t":"二进制读心卡片（经典数学魔术）","lv":"经典"}],"art":"question","tags":["魔术","二进制","读心术"]},{"id":"play-121","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","周末","出游"],"mins":2,"title":"一条密文，看谁先破","body":"屏幕上是一句加了密的英文：每个字母都往后挪了同样的格数。转动字母盘，转到读得通为止，看谁用的时间短。","widget":"cipher","params":{"mode":"decode"},"cta":"破译","hint":"轮流破，一人一条，各自报用时。他英语比你快就让他快，别找补“我刚才没看清”。","more":"这叫凯撒密码。据古罗马史书记载，凯撒写密信时就这么干：把每个字母换成字母表里往后数的第 3 个。\n\n它一共只有 25 种挪法，一个个试就能破开。小窍门：英文里单独一个字母的词，几乎不是 A 就是 I。","refs":[{"t":"Caesar cipher · Wikipedia","u":"https://en.wikipedia.org/wiki/Caesar_cipher","lv":"经典"}],"art":"key","tags":["密码","英语","凯撒密码"]},{"id":"play-122","type":"play","sub":"闯关","format":"widget","audience":"all","for":"kid","scenes":["出差","周末","饭桌","出游"],"mins":5,"title":"写一句只有我们懂的话","body":"打一句英文或拼音，选好每个字母挪几格，手机把它变成一串乱码。把乱码发给对方，或者直接递手机，看他多久能破开。","widget":"cipher","params":{"mode":"write"},"cta":"写密文","hint":"出差时把密文发给他，挪了几格别说。他回你一条的话，老老实实用「解密文」一格一格试出来。","refs":[{"t":"Caesar cipher · Wikipedia","u":"https://en.wikipedia.org/wiki/Caesar_cipher","lv":"经典"}],"art":"paper-plane","tags":["密码","英语","凯撒密码"]},{"id":"play-201","type":"play","sub":"对决","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","出游"],"mins":2,"title":"我的手速，你确定要比？","body":"手机平放在两人中间，一人守一头。屏幕一变绿就拍，先拍到的赢一轮；没变绿就拍算抢跑，这轮白送。5 局 3 胜。","more":"实验室里，年轻人看到灯亮再按键，平均要 0.2 秒上下。手机屏幕和触摸本身还有延迟，这里测出来会更慢一些——所以只和对面的人比，别和网上的数字比。","widget":"reaction","params":{"players":2,"mode":"simple"},"cta":"开打","hint":"别放水，他多半真比你快。输了就认，然后要求再来一局；你自己抢跑了，先笑的应该是你。","refs":[{"t":"Mental chronometry · Wikipedia","u":"https://en.wikipedia.org/wiki/Mental_chronometry","lv":"常识"}],"art":"stopwatch","tags":["反应","手速","对决"]},{"id":"play-202","type":"play","sub":"对决","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","周末"],"mins":3,"title":"三个人，看谁先上当","body":"屏幕会闪各种图案，只有和“目标”颜色、形状都一样的那个才能拍。手快没用，拍错直接出局。先赢 3 轮的人，今晚遥控器归他。","widget":"reaction","params":{"players":3,"mode":"trick"},"cta":"开打","hint":"这局拼的是忍住不拍，大人一点便宜都不占。被假信号骗了就大方认栽，别说“我是故意的”。","art":"target","tags":["反应","三个人","对决"]},{"id":"play-203","type":"play","sub":"对决","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","出游"],"mins":1,"title":"指尖拔河，手别抖","body":"一人一半屏幕，开始以后就狂点。绳结会被点得快的人拉走，拉过自己面前那条线就赢。一局最多 15 秒，手酸算正常。","widget":"tapwar","params":{"handicap":0},"cta":"开拔","hint":"真点，别让。输了甩甩手说“换只手再来”。他要是用两根手指轮流点，那是他聪明，别喊犯规。","art":"flag","tags":["手速","对决","拔河"]},{"id":"play-204","type":"play","sub":"对决","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","周末"],"mins":2,"title":"让你三成力，照样拉过来","body":"还是指尖拔河，不过坐下方的人要“负重”：每点一下只算七成力气。大人坐下方。开打前拖底下的滑块，负重还能再加。","widget":"tapwar","params":{"handicap":0.3},"cta":"开拔","hint":"先别动滑块。你连赢 2 局，就自己把负重往上加，加到他能赢为止；被他反超了，别急着调回来。","art":"trophy","tags":["手速","对决","拔河","让分"]},{"id":"play-205","type":"play","sub":"对决","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","出游"],"mins":3,"title":"我做难题，照样比你快","body":"两边同时出题，谁先点对谁得 1 分；点错要冻住 1.5 秒。先到 7 分赢。坐下方的人做难题，对面做简单的，难度开局前自己还能改。","widget":"mathduel","params":{"kind":"arith","levels":{"bottom":"hard","top":"easy"}},"cta":"抢答","hint":"你这边有两位数乘两位数，多半要输。输了别说“题不一样”，把两边的难度对调，再来一局。","art":"pencil","tags":["心算","抢答","对决"]},{"id":"play-206","type":"play","sub":"对决","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","出游"],"mins":3,"title":"哪边大？小心有坑","body":"两个数或两个式子摆出来，先点中大的那个得 1 分；一样大就点中间的等号。有些看着差很多，其实一样大。先到 7 分赢。","widget":"mathduel","params":{"kind":"compare","levels":{"bottom":"mid","top":"mid"}},"cta":"抢答","hint":"两边是同一道题，纯拼眼力。掉坑里就笑着认，再问他一句“这俩为啥一样大”，让他讲，你别讲。","art":"magnifier","tags":["心算","比大小","对决"]},{"id":"play-207","type":"play","sub":"下棋","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前","出游"],"mins":8,"title":"五子棋，输的人洗碗","body":"轮流落子，横、竖、斜先连成 5 个的赢。点一下只是预选，再点一下才真的落下，不怕手滑；下错了还能悔棋。","more":"正式比赛里，先走的一方优势太大，所以“连珠”规则专门给先手加了禁手。这里不设禁手，但输的人下一盘先走，算是找补。","widget":"gomoku","params":{},"cta":"落子","hint":"别一上来就把他堵死，等他摆出三连再动手。输了不复盘、不讲棋理，只说两个字：“再来”。","refs":[{"t":"Gomoku · Wikipedia","u":"https://en.wikipedia.org/wiki/Gomoku","lv":"经典"},{"t":"Renju · Wikipedia","u":"https://en.wikipedia.org/wiki/Renju","lv":"常识"}],"art":"chess","tags":["五子棋","棋","对决"]},{"id":"play-208","type":"play","sub":"下棋","format":"widget","audience":"all","for":"kid","scenes":["周末","睡前","出游"],"mins":10,"title":"咱俩联手，把电脑下赢","body":"这回不是对手，是队友。两个人商量着落子，对面是电脑。先打「普通」，赢了再去挑战「高手」；走错了可以悔棋，不丢人。","widget":"gomoku","params":{"ai":true,"level":2},"cta":"开局","hint":"手指交给他，你只出主意，而且每一步最多说一句。他想下的地方就算不对，也照他的下。","art":"gamepad","tags":["五子棋","棋","合作","人机"]},{"id":"play-209","type":"play","sub":"下棋","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前","出游"],"mins":5,"title":"围格子，看谁先沉不住气","body":"轮流在两个点之间画一条边。谁画下第 4 条边、围成一个格子，这格就归谁，而且还得接着画。16 个格子，多的赢。","more":"这个纸笔游戏最早是 19 世纪法国数学家爱德华·卢卡斯写进书里的。他还有一个更出名的发明：汉诺塔。","widget":"dots","params":{"players":2},"cta":"开画","hint":"前半盘谁都不想画“第 3 条边”。这个窍门别说破，等他自己发现，然后被他反过来坑一次。","refs":[{"t":"Dots and boxes · Wikipedia","u":"https://en.wikipedia.org/wiki/Dots_and_boxes","lv":"经典"}],"art":"puzzle","tags":["点格棋","纸笔游戏","对决"]},{"id":"play-210","type":"play","sub":"下棋","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","周末"],"mins":5,"title":"三人圈地，谁也别信谁","body":"三个人轮流画边，围成格子就归自己，还能接着画。两个人可以联手坑第三个，不过格子只算自己的，联盟随时会散。","widget":"dots","params":{"players":3},"cta":"开画","hint":"要结盟就跟他结，别和妈妈一起围他。被他俩联手坑了，哀嚎两声，然后老老实实数格子。","art":"map","tags":["点格棋","三个人","纸笔游戏"]},{"id":"play-211","type":"play","sub":"对决","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前","出游"],"mins":2,"title":"10 秒有多长？你数不准","body":"按下开始，表走 2 秒就藏起来。心里接着数，觉得到 10 秒了就按停。差距精确到 0.01 秒，谁离 10 秒更近谁赢。","widget":"tensec","params":{"target":10,"players":2},"cta":"开数","hint":"他数的时候别出声捣乱，等他按完再笑。你自己差了一大截，就老实报出来，别找理由。","art":"hourglass","tags":["时间","估计","对决"]},{"id":"play-212","type":"play","sub":"对决","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","周末","出游"],"mins":3,"title":"红字写着“蓝”，点哪个？","body":"屏幕上跳出红、蓝、绿、黄几个字，可字的颜色偏偏和意思不一样。别读字，点字的颜色。20 题，看谁的脑子更不容易被带跑。","more":"这叫斯特鲁普效应，1935 年由美国心理学家斯特鲁普发表。认字练得太熟，就成了自动反应：眼睛一扫到字，意思先冒出来，和“看颜色”抢跑，大脑得先把它按住。\n\n「干扰代价」就是打架的题比不打架的题平均慢了多少毫秒。一轮只有 20 题，每次会有几十毫秒的出入，多测几次更准。","widget":"stroop","params":{"players":2},"cta":"开测","hint":"多半是你被带跑得更厉害，认了。他赢了，就请他讲讲为什么字和颜色打架时会慢，你听着就行。","refs":[{"t":"Stroop effect · Wikipedia","u":"https://en.wikipedia.org/wiki/Stroop_effect","lv":"常识"},{"t":"J. R. Stroop (1935), Journal of Experimental Psychology 18(6)","lv":"实证"}],"art":"brain","tags":["斯特鲁普","心理学","反应","颜色"]},{"id":"play-301","type":"play","sub":"篮球","format":"widget","audience":"all","for":"kid","scenes":["球场"],"mins":15,"title":"打到 11 分，输的请水","body":"把手机立在场边当计分板：字够大，+1、+2、+3 随手点，点错了能撤销。先到 11 分的赢，退出再回来比分还在。","widget":"scoreboard","params":{"mode":"score","target":11},"cta":"开始计分","hint":"比分落后别放水，他看得出来。输了就认，水是真的要买；回家路上不复盘这一场。","art":"scoreboard","tags":["篮球","计分","单挑","工具"]},{"id":"play-302","type":"play","sub":"篮球","format":"widget","audience":"all","for":"kid","scenes":["球场","周末"],"mins":15,"title":"投篮接龙，手机帮你记字","body":"一个人选位置和投法，投进了，下一个人必须原样照做。照做的人投丢，就记一个字；先凑满“输了”的人出局。","more":"**怎么玩**\n\n- 猜拳决定谁先出题。\n- 出题的人先说清楚位置和投法（比如“罚球线，单手”），再投。\n- 投进了：下一个人原样照做，没进就记一个字。\n- 出题的人自己没进：不记字，换下一个人出题。\n- 先凑满整个词的人出局，剩到最后的人赢。\n\n词可以换：“输了”2 个字最快，“请喝水”3 个字；英文的 HORSE 5 个字母，是这个游戏在美国球场上的老叫法。","widget":"scoreboard","params":{"mode":"horse","word":"输了","players":2},"cta":"开始记字","hint":"他出的怪招你也得老老实实照做，做不出来就认字。今天你只是对手，不教动作。","refs":[{"t":"传统投篮游戏 H-O-R-S-E","lv":"经典"}],"art":"hoop","tags":["篮球","投篮","HORSE","工具"]},{"id":"play-303","type":"play","sub":"篮球","format":"widget","audience":"all","for":"kid","scenes":["球场"],"mins":10,"title":"罚球 10 投，谁更准","body":"每人 10 个罚球，进一个点一下。命中率、连中了几个、个人最好纪录，手机都记着。下次来，看谁先破纪录。","widget":"scoreboard","params":{"mode":"ft","players":2,"shots":10},"cta":"站上罚球线","hint":"你先投，投丢了自嘲一句。他投的时候你只报数，不纠正手型；破了纪录，击个掌就够。","art":"ball","tags":["篮球","罚球","命中率","工具"]},{"id":"play-304","type":"play","sub":"默契","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前","出游"],"mins":5,"title":"你猜我会选哪个","body":"一个人悄悄选，另一个人猜他选了什么。5 道题：最后一攻自己投还是传？火锅第一筷子夹什么？猜完互换，看谁更懂谁。","widget":"tacit","params":{"pack":"kid","rounds":5},"cta":"开始互猜","hint":"你先当被猜的那个。他猜错了别急着纠正，问一句“你为什么觉得我会选那个”，听他说完。","art":"question","tags":["默契","互猜","两个人"]},{"id":"play-305","type":"play","sub":"默契","format":"widget","audience":"dad","for":"wife","scenes":[],"mins":5,"title":"这么多年了，还猜得中吗","body":"孩子睡了以后，两个人玩 5 题：一个悄悄选，另一个猜。题目只关于你们俩——累了一天最想怎样，难得单独吃饭去哪儿。","widget":"tacit","params":{"pack":"couple","rounds":5},"cta":"两个人玩","hint":"猜错了别辩解，更别说“你怎么会这么想”。记住她选的那个，这周找一天照着做一次。","art":"heart","tags":["默契","夫妻","两个人"]},{"id":"play-306","type":"play","sub":"默契","format":"widget","audience":"all","for":"kid","scenes":["周末","睡前","出游"],"mins":8,"title":"这一局只许喊英文","body":"屏幕给一个英文词，画的人只能画、不能出声，猜的人必须用英文喊出答案。一共 6 个词，看两个人能对上几个。","widget":"sketch","params":{"category":"english","players":2,"seconds":60},"cta":"开始画","hint":"你的英文多半不如他，这正好。猜不出来就让他教你念一遍，然后老老实实跟着读。","art":"abc","tags":["你画我猜","英文","画画"]},{"id":"play-401","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","车上","睡前"],"mins":3,"title":"10 颗球，你押哪个槽","body":"球从钉子阵里乱弹着掉下来。每颗落下之前，先押它会进哪个槽：越难中的槽，分越高。10 颗球，比总分。","more":"每个槽下面的数字，是押中它能得的分。分数按“有多难中”来定：最边上的槽，64 颗球里才进一颗，押中就给 64 分；正中间的槽最容易进，只给 3.2 分。\n\n两个人轮流各玩 10 颗，比总分。\n\n玩完按「撒 300 颗看看」，就知道球到底爱往哪儿去。","widget":"galton","params":{"mode":"bet"},"cta":"押一把","hint":"你俩轮流各玩 10 颗，比总分。他要是全押边上赌大的，别拦，输赢让他自己试出来。你可以故意只押中间。","refs":[{"t":"Galton board · Wikipedia","u":"https://en.wikipedia.org/wiki/Galton_board","lv":"经典"}],"art":"ball","tags":["概率","高尔顿板","下注","对决"]},{"id":"play-402","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","车上","睡前"],"mins":3,"title":"押一把：谁先排完","body":"两支队伍，同一堆乱七八糟的柱子，各用各的办法从矮排到高。只告诉你它们的办法，不告诉你名字。押谁先排完？","more":"每比较一次两根柱子的高矮算一步，步数少的先到。\n\n一共有五种办法轮流上场：挨个比的、每趟挑最矮的、像理扑克牌的、先分两堆的、先分小组再合并的。有的对决差好几倍，有的只差一点点，还有一对永远打平。\n\n每局比完，会公布两支队伍的真名。","widget":"sorting","params":{"mode":"bet","pair":["insertion","merge"]},"cta":"押一把","hint":"每局开跑前各说一句理由再押。他押错了别解释，再来一局。你也押，输了认。五种办法都见过了，再点「为什么」。","refs":[{"t":"Sorting algorithm · Wikipedia","u":"https://en.wikipedia.org/wiki/Sorting_algorithm","lv":"常识"}],"art":"flag","tags":["算法","排序","下注","对决"]},{"id":"play-403","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["饭桌","睡前","周末"],"mins":8,"title":"5 个格子，谁活得最久","body":"只许摆 5 个格子，摆完就不能再碰。规则会让它们自己繁殖、移动、死掉。比一比：谁的图案折腾得最久才消停？","more":"规则只有三条：空格子旁边正好 3 个活的，就出生；活格子旁边有 2 或 3 个活的，就活下去；其余的死掉。\n\n“折腾了几代”从开局算到它不再出新花样为止——全灭、定住不动、或者开始原地重复，都算消停。\n\n绝大多数摆法撑不过 5 代。能撑过 10 代，已经是高手。\n\n试过 3 次以后，会多出一个按钮：「数学家的答案」。先别急着点。","widget":"life","params":{"mode":"five"},"cta":"摆 5 个格子","hint":"轮流摆，各记自己的最好成绩。他连着全灭几次很正常，提醒一句“挨着摆”就够了。「数学家的答案」留到最后一起点。","refs":[{"t":"Conway's Game of Life · Wikipedia","u":"https://en.wikipedia.org/wiki/Conway%27s_Game_of_Life","lv":"经典"}],"art":"puzzle","tags":["生命游戏","挑战","对决","R 五格"]},{"id":"play-404","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","车上","睡前"],"mins":4,"title":"23 个人，会撞生日吗","body":"一个房间里有 23 个人，一年有 365 天。至少两个人同一天生日的可能性，你押百分之几？先押，再揭晓。","more":"这道题叫“生日悖论”：答案并不矛盾，只是和直觉差得太远。\n\n揭晓以后别急着信。一屋一屋地“请人进来”试，或者一口气跑 1000 屋。\n\n再把人数滑到 40（差不多一个班），或者 30（两支篮球队的大名单加起来），看看又是多少。\n\n想在现实里验证：找一份带生日的名单——班级通讯录、球队资料都行——数一数有没有撞的。","widget":"birthday","params":{"n":23},"cta":"押一个数","hint":"各自先押一个数，说出口再揭晓。你猜得离谱更好。揭晓后别讲公式，问他敢不敢拿一份真名单验证。","refs":[{"t":"Birthday problem · Wikipedia","u":"https://en.wikipedia.org/wiki/Birthday_problem","lv":"经典"}],"art":"calendar","tags":["概率","生日悖论","先猜再看"]},{"id":"play-405","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["睡前","周末","出游"],"mins":5,"title":"画个笑脸，看它变成啥","body":"一张空白格子纸。用手指画什么都行：笑脸、名字缩写、一坨不明物体。按下播放，它会自己“活”过来——然后变得面目全非。","more":"这是“生命游戏”的自由模式。画完以后，格子按三条规则自己变：旁边正好 3 个活的就出生，有 2 或 3 个就活着，其余的死掉。\n\n几个玩法：\n\n- 两人各画一个图案，比谁的先死光\n- 画一条长长的横线，看它变成什么\n- 从「图案」里放一把滑翔机枪，再在子弹的路上画点障碍\n\n棋盘上下左右是连着的，飞出去的东西会从另一边回来。","widget":"life","params":{"preset":"empty"},"cta":"开始画","hint":"他画什么都别评价，越离谱越好。你也画一个，比谁的先死光。他问“为什么会动”，再告诉他只有三条规则。","refs":[{"t":"Conway's Game of Life · Wikipedia","u":"https://en.wikipedia.org/wiki/Conway%27s_Game_of_Life","lv":"经典"}],"art":"pencil","tags":["生命游戏","涂鸦","自由玩"]},{"id":"play-501","type":"play","sub":"篮球","format":"widget","audience":"all","for":"kid","scenes":["救场","球场","车上","周末"],"mins":5,"title":"罚球线：进 5 个要几投？","body":"调角度和速度，点出手。小心：你的手会抖一点点，瞄得准不等于投得进。","more":"这里只算重力。罚球线到篮筐中心 4.225 米，篮筐高 3.05 米，出手点默认 2 米高。\n\n挑战里的“手抖”是随机的：每次出手，速度大约差 1%，角度大约差 1°。所以同一个瞄准，有时进，有时不进。\n\n想少投几次，就得找一条“差一点也能进”的弧线。线索在左上角：球眼里的篮筐。","widget":"hoopshot","params":{"mode":"challenge","spot":"ft"},"cta":"上罚球线","hint":"你先投，挑一条很平的弧线，投丢了别找理由。他的成绩比你好就认输，请他讲讲诀窍。","refs":[{"t":"FIBA 篮球规则·器材（篮筐、篮球与球场尺寸）","lv":"官方"},{"t":"Basketball court · Wikipedia","u":"https://en.wikipedia.org/wiki/Basketball_court","lv":"常识"}],"art":"ball","tags":["篮球","罚球","物理","抛物线"]},{"id":"play-502","type":"play","sub":"篮球","format":"widget","audience":"all","for":"kid","scenes":["球场","周末","车上","出游"],"mins":6,"title":"三分线：敢不敢比一局","body":"比罚球远了 2.5 米，能进的那条缝更窄。两个人轮流，各投进 5 个，出手次数少的赢。","more":"三分线离篮筐 6.75 米（国际篮联的标准，NBA 是 7.24 米）。离得越远，同样的手抖，落点偏得越多，所以三分天生比罚球难。\n\n和罚球一样：弧线高一点，球眼里的篮筐就大一点；可是弧线越高，出手越费力。","widget":"hoopshot","params":{"mode":"challenge","spot":"three"},"cta":"开投","hint":"轮流玩，各记各的出手次数。输了就认，别拿“手抖”当借口。他要是赢了，问一句：你是怎么选弧线的？","refs":[{"t":"FIBA 篮球规则·器材（篮筐、篮球与球场尺寸）","lv":"官方"},{"t":"Basketball court · Wikipedia","u":"https://en.wikipedia.org/wiki/Basketball_court","lv":"常识"}],"art":"hoop","tags":["篮球","三分","物理","对决"]},{"id":"play-503","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","车上","睡前"],"mins":4,"title":"猜猜这朵花有几瓣","body":"大圈 96 个齿，小轮 36 个齿，小轮在大圈里滚，笔尖画出一朵花。它有几个花瓣？先猜，再看它画。","more":"小轮每滚过自己的一圈齿，画出一个花瓣。要等大圈和小轮同时回到出发的位置，线才接得上。\n\n所以：**花瓣数 = 大圈齿数 ÷ 两个齿数的最大公因数**。\n\n大圈 96、小轮 36：最大公因数是 12，花瓣 96 ÷ 12 = 8 个，小轮要绕 3 圈。两个齿数互质的时候，花瓣最多。","widget":"curves","params":{"quiz":true},"cta":"猜花瓣","hint":"别讲最大公因数。你也一题一题跟着猜，猜错了就认。猜过几题以后，各说一条自己琢磨的规律，下一题当场验。","refs":[{"t":"Hypotrochoid · Wikipedia","u":"https://en.wikipedia.org/wiki/Hypotrochoid","lv":"常识"},{"t":"Spirograph · Wikipedia","u":"https://en.wikipedia.org/wiki/Spirograph","lv":"常识"}],"art":"pencil","tags":["数学","最大公因数","万花尺","曲线"]},{"id":"play-504","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["救场","睡前","车上","饭桌"],"mins":4,"title":"种一棵只有一条规则的树","body":"每根树枝分两个叉，一直分下去。调角度和比例，看你能种出什么：西兰花？珊瑚？还是一团乱麻？","more":"分形就是：同一条规则，在越来越小的地方一遍遍重复。\n\n树：每根枝分两叉，9 层就有 511 根树枝。折下任何一根，它都和整棵树长得一样。\n\n切到「科赫雪花」：每条边中间鼓出一个小尖角。每加一层，周长变成原来的 4/3，可以一直涨下去；面积却有封顶，永远超不过最初那个三角形的 1.6 倍。","widget":"fractal","params":{"kind":"tree"},"cta":"去种树","hint":"让他调一棵最怪的，你负责起名字。再切到「科赫雪花」一层层往上加，各押一个：面积会不会也跟着一直涨？押错的认输。","refs":[{"t":"Fractal · Wikipedia","u":"https://en.wikipedia.org/wiki/Fractal","lv":"常识"},{"t":"Koch snowflake · Wikipedia","u":"https://en.wikipedia.org/wiki/Koch_snowflake","lv":"常识"}],"art":"tree","tags":["数学","分形","科赫雪花"]},{"id":"play-505","type":"play","sub":"猜猜看","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","车上","睡前"],"mins":4,"title":"5 关：你的眼睛靠得住吗","body":"5 张图，5 个问题，每个都有标准答案。先凭眼睛回答，再当场验证。","more":"这 5 种错觉骗的不是你一个人，是所有人的视觉系统。知道答案以后再看，它们还是老样子。\n\n有的大体弄明白了：同一种灰放在深色旁边显得浅，是因为眼睛只比较“和周围差多少”。有的到现在还没有定论：线头朝外张的线为什么显得长，科学家还在争论。","widget":"illusion","params":{"kind":"tour"},"cta":"闯关","hint":"两个人各答各的，先别商量。被骗了不用解释，这些图连研究它们的人也照样上当。比一比谁被骗得少。","refs":[{"t":"Optical illusion · Wikipedia","u":"https://en.wikipedia.org/wiki/Optical_illusion","lv":"常识"}],"art":"magnifier","tags":["错觉","视觉","大脑"]},{"id":"puz-001","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":8,"title":"只有一个手电筒","body":"天黑，4 个人要过一座窄桥。桥上一次最多走 2 人，过桥的人必须带着那只唯一的手电筒（不能扔，隔着桥也照不到）。4 人单独过桥分别要 1、2、5、10 分钟，两人同行按慢的算。全部过桥，最快要几分钟？","reveal":{"label":"看答案","text":"17 分钟。用过桥时间当名字：①“1”和“2”过去（2 分钟）②“1”回来（1）③“5”和“10”过去（10）④“2”回来（2）⑤“1”和“2”再过去（2）。2+1+10+2+2=17。","explain":"多数人让最快的“1”来回接送，那样要 19 分钟。关键是让最慢的两个人一起走，“5”那一趟就被“10”盖住了；再由提前等在对岸的“2”把手电送回来。"},"hint":"他多半先答 19。别说“错”，只问一句：“最慢的两个人，能不能一起走？”拿四样小东西当人，在桌上摆一摆更清楚。","refs":[{"t":"过桥问题（Bridge and torch problem）· Wikipedia","u":"https://en.wikipedia.org/wiki/Bridge_and_torch_problem","lv":"经典"}],"art":"bulb"},{"id":"puz-002","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","车上"],"mins":6,"title":"7 环金链，最少切几环","body":"一条金链由 7 个环连成一串（两头不相连）。请人干 7 天活，每天收工时结一次账：他手里的金环必须正好等于他干过的天数，不能多给，也不能欠。最少要切开几个环？","reveal":{"label":"看答案","text":"只切 1 个：从一头数的第 3 个环。链子变成 1 环、2 环、4 环三段（切开的那个也算 1 环）。","explain":"关键是可以“找零”。第 1 天给 1 环；第 2 天给 2 环那段，把 1 环换回来；第 3 天再给 1 环；第 4 天给 4 环那段，把 1 环和 2 环都换回来；后 3 天照前 3 天的办法再来一遍。1、2、4 能凑出 1 到 7 的每一个数。"},"hint":"他多半先答 3 或 6（把每个环都拆开）。别说“错”，只问：“每天给出去的，一定得是新的吗？”拿 7 个回形针串起来试最清楚。","refs":[{"t":"经典逻辑题","lv":"经典"}],"art":"pouch"},{"id":"puz-003","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","车上"],"mins":6,"title":"只许称一次","body":"10 盒巧克力，每盒 10 块，每块本该重 10 克。其中有一盒出了错，里面每块都只有 9 克，外表看不出来。给你一台能显示克数的电子秤，秤上的读数从头到尾只许看一次。怎么找出那一盒？","reveal":{"label":"看答案","text":"给盒子编上 1 到 10 号。1 号盒拿 1 块，2 号盒拿 2 块……10 号盒拿 10 块，一共 55 块，一起放上秤。本该是 550 克，少了几克，就是几号盒。","explain":"每块次品只轻 1 克，所以“少了几克”就等于“秤上有几块次品”。而每盒拿出来的块数都不一样，块数就成了那一盒的编号。"},"hint":"这题难。卡住时只提示一句：“每盒拿出来的块数，一定要一样多吗？”你自己没想出来就直说，一起看答案。","refs":[{"t":"经典逻辑题","lv":"经典"}],"art":"flask"},{"id":"puz-004","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["车上","饭桌","睡前"],"mins":6,"title":"一个问题问出路","body":"岔路口有两条路，一条通往球馆，一条是死路。路口站着两个机器人：一个只说真话，一个只说假话，你分不出谁是谁，它俩却互相了解。只许向其中一个问一个问题，怎么问才能走对？","reveal":{"label":"看答案","text":"随便找一个问：“如果我去问另一个机器人‘哪条路通往球馆’，它会指哪条？”然后走另外一条。","explain":"问到说真话的，它会老老实实转述假话机器人的错误答案；问到说假话的，它会把真话机器人的正确答案说反。两种情况指的都是死路，所以反着走一定对。别的问法也有，比如：“如果我问你‘左边这条通往球馆吗’，你会回答‘是’吗？”它说“是”就走左边。"},"hint":"他每想出一个问法，你就分别扮两个机器人各答一遍，让他自己看行不行。扮假话机器人时慢一点：先想真话，再反着说。卡住时提示：“能不能让两个机器人的话叠在一起？”","refs":[{"t":"骑士与无赖（Knights and Knaves）· Wikipedia","u":"https://en.wikipedia.org/wiki/Knights_and_Knaves","lv":"经典"}],"art":"compass"},{"id":"puz-005","type":"puzzle","sub":"逻辑","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"三个人，只有一句真话","body":"体育课后，记分牌被人改成了 99 比 0，是这三个人里的一个干的，而且三人中只有一个说了真话。\n小北：“不是我。”\n小南：“是小北。”\n小东：“不是我。”\n是谁改的？","options":["小北","小南","小东"],"answer":2,"explain":"小北说“不是我”，小南说“是小北”，这两句话正好相反，必定一真一假。唯一的那句真话已经落在他俩中间了，所以小东的“不是我”是假话——就是小东。","hint":"他想一个一个假设也行，别拦着。等他做完，你再说自己的走法：“我是先找哪两句话互相打架。”说完就停。","refs":[{"t":"经典逻辑题","lv":"经典"}],"art":"scoreboard"},{"id":"puz-006","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"three","scenes":["饭桌","周末","睡前"],"mins":8,"title":"看不见自己的帽子","body":"一共 3 顶红帽、2 顶蓝帽，三个聪明人都知道。他们排成一列各戴一顶，只能看见前面人的帽子，剩下 2 顶藏了起来。最后面的说：“我不知道自己的颜色。”中间的也说不知道。最前面的却说：“我知道了。”他戴的是什么颜色？","reveal":{"label":"看答案","text":"红色。","explain":"最后面的人要是看到前面两顶都是蓝的，就知道自己是红的。他说不知道，说明前面两人至少有一顶红。中间的人也想到了这一点：要是看到最前面是蓝的，自己就一定是红的。可他也说不知道，说明最前面那顶不是蓝的。"},"hint":"这题难，给足时间。提示一句就够：“最后面那个人，看到什么才会一定知道？”三个人站成一列真演一遍更好玩。","refs":[{"t":"经典逻辑题","lv":"经典"}],"art":"question"},{"id":"puz-007","type":"puzzle","sub":"逻辑","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":5,"title":"时针分针一天碰面几次","body":"从今天 0 点到明天 0 点，这 24 小时里，钟面上的时针和分针会完全重合多少次？（今天 0 点那次算，明天 0 点那次不算。）","options":["24 次","23 次","22 次","12 次"],"answer":2,"explain":"把它想成操场上跑圈：24 小时里分针跑 24 圈，时针只跑 2 圈。分针每比时针多跑一整圈，就追上它一次，一共多跑 24−2=22 圈，追上 22 次。最后一次追上正好是明天 0 点，不算；今天 0 点出发时的那次重合要算，一减一加，还是 22 次。不信看 11 点到 1 点这两个小时：只在 12 点整重合了一次。","hint":"他多半脱口而出 24。别急着纠正，一起从 12 点往后数：1 点多一次、2 点多一次……数到 11 点，他自己会发现不对劲。","refs":[{"t":"经典趣味数学题","lv":"经典"}],"art":"clock"},{"id":"puz-008","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","出游"],"mins":4,"title":"来回跑的小狗","body":"你和爸爸相距 600 米，面对面同时出发，每人每分钟走 60 米。小狗同时从你脚边出发，每分钟跑 200 米，冲到爸爸那儿就掉头冲向你，这样来回跑，直到你俩碰面。小狗一共跑了多少米？","reveal":{"label":"看答案","text":"1000 米。","explain":"别去算它每一趟跑多远。你俩每分钟一共靠近 120 米，600 米要 5 分钟才碰面。这 5 分钟小狗一步没停，200×5=1000 米。"},"hint":"他要是一趟一趟地算，陪他算第一趟（600÷260，除不尽），再问：“小狗一共跑了多长时间？”你也可以假装硬算，算不下去了再一起换思路。","refs":[{"t":"经典趣味数学题","lv":"经典"}],"art":"sneaker"},{"id":"puz-009","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["救场","球场","车上","饭桌"],"mins":3,"title":"37 支球队要打几场","body":"37 支球队打淘汰赛：输一场就回家，没有平局；队伍凑不成对的时候，多出来的那支轮空，直接进下一轮。一直打到只剩冠军，总共要打多少场比赛？","reveal":{"label":"看答案","text":"36 场。","explain":"不用排赛程。每场比赛正好淘汰 1 支球队，37 支里要剩下 1 个冠军，就得淘汰 36 支，所以是 36 场。换成 64 支就是 63 场，多少支都这么算。"},"hint":"他要是一轮一轮地排（18 场、9 场……），让他排完。然后问：“每打完一场，会少几支队？”看他多久反应过来。","refs":[{"t":"经典趣味数学题","lv":"经典"}],"art":"trophy"},{"id":"puz-010","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["车上","饭桌","睡前"],"mins":5,"title":"标签全贴错了","body":"三个不透明的盒子：一个装 2 个白乒乓球，一个装 2 个黄乒乓球，一个装 1 白 1 黄。盒上的标签“白白”“黄黄”“白黄”全都贴错了。只许从一个盒子里摸出 1 个球来看，怎么判断三个盒子各装什么？","reveal":{"label":"看答案","text":"从贴着“白黄”的盒子里摸一个。摸出白球，这盒就是“白白”，那么贴“黄黄”的盒子装的是“白黄”，贴“白白”的装的是“黄黄”。摸出黄球，就反过来推。","explain":"关键在“全贴错”：贴“白黄”的盒子里，一定是两个同色的球，摸一个就知道是哪种。剩下两个盒子的标签也都是错的，只剩一种排法。"},"hint":"别太早提示。实在卡住就问：“哪个盒子里的两个球，一定是同一种颜色？”他想通了就收，不用再让他讲一遍。","refs":[{"t":"经典逻辑题","lv":"经典"}],"art":"puzzle"},{"id":"puz-011","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末"],"mins":8,"title":"蒙着眼睛分硬币","body":"桌上有 20 枚硬币，其中正好 6 枚正面朝上，其余反面朝上。你蒙着眼，用手也摸不出正反，但可以随意翻动硬币。怎么把它们分成两堆，让两堆里正面朝上的硬币一样多？","reveal":{"label":"看答案","text":"随便数出 6 枚放成一堆，把这 6 枚全部翻个面。剩下的 14 枚是另一堆。","explain":"假设你拿走的 6 枚里有 x 枚正面，那么剩下那堆就有 6−x 枚正面。你这堆是 x 枚正、6−x 枚反，全翻一遍，正好变成 6−x 枚正面，和另一堆一样多。x 是几都成立。"},"hint":"这是最难的几道之一。卡住时提示：“两堆不一定要一样多。”有硬币就真摆出来试；做成了，让他蒙上眼给妈妈表演。","refs":[{"t":"经典逻辑题","lv":"经典"}],"art":"target"},{"id":"puz-012","type":"puzzle","sub":"逻辑","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":4,"title":"前天 12 岁，明年 15 岁","body":"小北说：“前天我还是 12 岁，可明年我就要过 15 岁生日了。”他一个字都没说错。今天是几月几日？他的生日又是哪一天？","reveal":{"label":"看答案","text":"今天是 1 月 1 日，他的生日是 12 月 31 日。","explain":"前天是去年的 12 月 30 日，他还是 12 岁；昨天 12 月 31 日，他满 13 岁；今年年底满 14 岁；明年年底，过 15 岁生日。只有把“前天”和“今天”分在两个年份里，这句话才说得通。"},"hint":"别急着帮他。卡住时只问：“前天和今天，一定在同一年里吗？”你要是比他慢，认了就行。他解出来以后别加题，让他得意一会儿。","refs":[{"t":"经典逻辑题","lv":"经典"}],"art":"calendar"},{"id":"puz-013","type":"puzzle","sub":"逻辑","format":"quiz","audience":"all","for":"three","scenes":["救场","球场","车上","饭桌"],"mins":2,"title":"超过第 2 名，你是第几","body":"100 米决赛，快到终点时，你咬着牙超过了第 2 名，之后名次再没变过。冲线的时候，你是第几名？","options":["第 1 名","第 2 名","第 3 名"],"answer":1,"explain":"你超过的是第 2 名，等于把他的位置占了：你变成第 2，他掉到第 3，第 1 名还在你前面。","hint":"抢答题，读完就让他答。他脱口而出“第 1”也别笑，让他拿去坑妈妈。等他得意了再追问：“超过的要是最后一名呢？”（办不到：跑在最后一名后面的，自己才是最后一名。）","refs":[{"t":"经典趣味谜题","lv":"经典"}],"art":"stopwatch"},{"id":"puz-014","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"three","scenes":["救场","车上","饭桌"],"mins":5,"title":"推车到旅馆就破产","body":"一个人把小车推到一家旅馆门口，立刻知道自己破产了。没有人骗他，也没出任何事故。这是怎么回事？","reveal":{"label":"看答案","text":"他在玩“大富翁”这类棋盘游戏：他的棋子是一辆小车，正好走到别人盖了旅馆的那一格，付不起过路费。","explain":"“把小车推到旅馆门口”让人想到真车、真旅馆。其实那辆车只有指甲盖大，旅馆也是。"},"hint":"你先偷看答案，他只能问“是或不是”，你只答是、不是、没关系，也就是“海龟汤”的玩法。卡住就给一句：“他正和朋友围着一张桌子。”","refs":[{"t":"情境猜谜（Situation puzzle）· Wikipedia","u":"https://en.wikipedia.org/wiki/Situation_puzzle","lv":"经典"}],"art":"dice"},{"id":"puz-015","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"three","scenes":["救场","车上","饭桌"],"mins":5,"title":"只坐到 12 楼","body":"他家住 20 楼。每天出门，他坐电梯直接下到 1 楼；回家时却只坐到 12 楼，再爬 8 层楼梯。可要是电梯里有别人，或者那天下雨，他就一直坐到 20 楼。为什么？","reveal":{"label":"看答案","text":"他是个小学生，个子不够高，最高只够得着 12 楼的按钮。电梯里有别人，可以请人帮忙按；下雨天他带着伞，用伞尖能戳到 20 楼。","explain":"下楼时，1 楼的按钮在最下面，他按得到。线索全在“有别人”和“下雨”里：这两种情况各多出一样东西，一个是帮手，一个是伞。"},"hint":"用“是或不是”来玩：你先偷看答案，他提问，你只答是、不是、没关系。卡住时提醒：“下雨天，他手里多了什么？”","refs":[{"t":"经典情境谜题","lv":"经典"}],"art":"key"},{"id":"puz-016","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"three","scenes":["救场","车上","饭桌"],"mins":5,"title":"要杯水，却被吼了一声","body":"一个人急匆匆走进一家小饭馆，开口就要一杯水。老板看了他一眼，没倒水，反而突然冲他大吼一声。他愣了一下，笑着说“谢谢”，水也不要了，转身就走。为什么？","reveal":{"label":"看答案","text":"他一直在打嗝，想喝口水压一压。老板看出来了，猛地吓他一跳——嗝停了，水自然也不用喝了。","explain":"喝水和吓一跳，都是流传很广的止嗝土办法。管不管用因人而异，不过在这个故事里，它管用了。"},"hint":"用“是或不是”来玩，你先偷看答案。他问不到点子上时提示：“他要水，是因为口渴吗？”","refs":[{"t":"经典情境谜题","lv":"经典"}],"art":"cup"},{"id":"puz-017","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"three","scenes":["救场","睡前","出差","车上"],"mins":5,"title":"半夜打给隔壁的电话","body":"一个出差的人住进一家墙很薄的小旅馆，半夜怎么也睡不着。他拿起电话打给隔壁房间，对方刚“喂”了一声，他一句话没说就挂了，然后很快睡着了。为什么？","reveal":{"label":"看答案","text":"隔壁的呼噜声太响，隔着墙吵得他睡不着。电话把隔壁叫醒，呼噜停了，他赶紧抢在下一轮呼噜开始前睡着。","explain":"他不需要说话，只需要对方醒过来。线索是“一句话没说”：这通电话的目的根本不在通话。"},"hint":"用“是或不是”来玩，你先偷看答案。要是你自己打呼噜，这题讲完他肯定拿你开涮，认了就行。","refs":[{"t":"经典情境谜题","lv":"经典"}],"art":"moon"},{"id":"puz-018","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"three","scenes":["救场","车上","出游"],"mins":3,"title":"草地上的胡萝卜","body":"春天的草地上，躺着一根胡萝卜、两颗黑纽扣和一条旧围巾，三样东西挨得很近。没有人把它们扔在草地上。它们是怎么到这儿来的？","reveal":{"label":"看答案","text":"冬天有人在这儿堆过一个雪人：胡萝卜是鼻子，纽扣是眼睛，围巾围在脖子上。雪化了，它们就落在了草地上。","explain":"三样东西单看都很普通，凑在一起就只剩一个解释。线索是“春天”和“挨得很近”。"},"hint":"这题容易，适合开个头。他答出来后换他出题：让他也编一个“奇怪的现场”，你来问是或不是。","refs":[{"t":"经典情境谜题","lv":"经典"}],"art":"snow"},{"id":"puz-019","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":2,"title":"一身黑的人和没开灯的车","body":"一个人从头到脚穿着黑衣服，站在马路中间。路灯全坏了，天上也没有月亮。一辆没开车灯的汽车开过来，司机却老远就看见了他，稳稳停住。司机是怎么看见的？","reveal":{"label":"看答案","text":"因为是大白天。","explain":"题目里黑衣服、坏路灯、没月亮、没开的车灯，一样接一样，让人自动脑补成了夜里。可从头到尾，没有一个字说过那是晚上。"},"hint":"读题时故意把“黑”“路灯”“月亮”读重一点。他答不出来，就让他把题目再念一遍，找找哪个字说了是晚上。","refs":[{"t":"经典情境谜题","lv":"经典"}],"art":"sun"},{"id":"puz-020","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"该找哪位理发师","body":"小镇上只有两位理发师，全镇人的头发都归他俩剪。第一位自己的头发被剪得乱七八糟，第二位的发型整齐又精神。你路过这里想理个发，该找哪一位？","reveal":{"label":"看答案","text":"找头发乱七八糟的那位。","explain":"理发师没法给自己理发，镇上又只有他们两个，所以他俩的头发是互相剪的。那个漂亮的发型，出自第一位之手；乱七八糟的那个脑袋，才是第二位的作品。"},"hint":"让他先选并说出理由，你别表态。他选了发型整齐的那位，就问：“那他的头发是谁剪的？”他说“自己剪的”，就问后脑勺怎么办。","refs":[{"t":"经典情境谜题","lv":"经典"}],"art":"suitcase"},{"id":"puz-021","type":"puzzle","sub":"脑洞","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","出游"],"mins":2,"title":"涨潮了，梯子淹到第几级","body":"码头边停着一艘船，船舷上挂着绳梯，最下面一级刚好贴着水面，每两级之间相隔 30 厘米。开始涨潮了，水面每小时上升 15 厘米。多久以后，水会淹到从下往上数的第 3 级？","options":["2 小时","4 小时","6 小时","永远淹不到"],"answer":3,"explain":"船是浮在水上的，水涨多高，船和挂在船上的绳梯就跟着升多高，最下面那一级永远刚好贴着水面。照着数字能算出“4 小时”，算得一点没错，只是这道题根本不用算。","hint":"他认真算出“4 小时”时先别笑，问一句：“涨潮的时候，船在干什么？”你也可以先假装跟着他一起算。","refs":[{"t":"经典趣味谜题","lv":"经典"}],"art":"lighthouse"},{"id":"puz-022","type":"puzzle","sub":"脑洞","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"72 岁才过第 18 个生日","body":"一位老爷爷过 72 岁生日这天说：“算上今天，我这辈子才正儿八经过了 18 次生日。”他没记错，也没有哪一年忘了过。怎么回事？","reveal":{"label":"看答案","text":"他出生在 2 月 29 日。这个日子通常 4 年才出现一次，72÷4=18。","explain":"只有闰年才有 2 月 29 日。别的年份，他只能挑 2 月 28 日或 3 月 1 日凑合着过。所以活到 72 岁，日历上真正出现他生日的那一天，只有 18 次。（整百的年份要能被 400 整除才是闰年，2000 年正好是，所以他一次也没少。）"},"hint":"可以用“是或不是”来玩。卡住时提示：“有没有哪个日子，不是每年都有？”答出来后一起算：下一个 2 月 29 日是哪年？（下一个能被 4 整除的年份。）","refs":[{"t":"经典趣味谜题","lv":"经典"}],"art":"family"},{"id":"puz-023","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["救场","球场","车上","饭桌"],"mins":2,"title":"我早就知道你会算出几","body":"心里想一个数，别说出来。把它乘以 2，加上 46，再除以 2，最后减去你一开始想的那个数。算好了吗？点开看看我猜得对不对。","reveal":{"label":"看我猜的","text":"你得到的是 23——乔丹和詹姆斯都穿过的号码。","explain":"设你想的数是 x。乘以 2 再加 46 是 2x+46，除以 2 是 x+23，减去 x，只剩 23。你想的那个数从头到尾都被抵消掉了，想小数、负数也一样。想换个结果？把 46 换成别的数，答案就是它的一半。"},"hint":"让他照着卡片做一遍，你别抢答。他要是追问怎么回事，先别讲，反问一句：想让结果变成你自己的球衣号码，46 该换成几？还想再被猜一次，去「工具箱」找「读心术」。","refs":[{"t":"经典数学魔术","lv":"经典"}],"art":"jersey"},{"id":"puz-024","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":5,"title":"三位数倒过来，我猜得到","body":"拿张纸。写一个三位数，百位和个位至少相差 2（比如 742）。把它倒过来写（247），用大的减小的（得 495）。把得数也倒过来（594），再把这两个数加在一起。先别说结果，点开看我猜的数。","reveal":{"label":"看我猜的","text":"1089。不管你一开始写的是哪个数。","explain":"设原数是 100a+10b+c（a 比 c 大），倒过来是 100c+10b+a。两数相减，10b 抵消，差是 99a−99c=99×(a−c)，也就是 99 的 2 到 9 倍：198、297、396、495、594、693、792、891。这 8 个数都是中间为 9、首尾相加得 9。倒过来再相加：首尾凑出 9 个 100 和 9 个 1，中间两个 9 是 180，合起来 1089。"},"hint":"要纸笔。他中间减错了，结果就不对，先陪他验算。个位是 0 也行，倒过来当作 047。学会后让他把 1089 提前写好，去“预言”妈妈。","refs":[{"t":"1089（数）· Wikipedia","u":"https://en.wikipedia.org/wiki/1089_(number)","lv":"经典"}],"art":"pencil"},{"id":"puz-025","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":4,"title":"月历上框 9 个数","body":"找一页月历。让他在上面任意框出一个 3×3 的方块（9 个格子里都要有日期），只告诉你其中最小的那个数。你立刻报出这 9 个数的总和。","reveal":{"label":"看揭秘","text":"把他说的最小数加 8，再乘以 9。比如最小的是 5：(5+8)×9=117。","explain":"日历上往右一格多 1，往下一格多 7，所以方块正中间的数等于最小数加 8。9 个数以中间为中心两两对称：左上和右下、正上和正下……每一对的平均数都是中间那个数，所以总和就是“中间数×9”。"},"hint":"先自己学会再表演。要一页月历，墙上的、手机里的都行（避开把两天挤在一格的那种）。乘以 9 的口算：先乘 10，再减去它自己。表演两次，让他猜门道；揭秘后换他来。","refs":[{"t":"经典数学魔术","lv":"经典"}],"art":"calendar"},{"id":"puz-026","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","车上"],"mins":5,"title":"我能算出你的生日","body":"让他想一个你不知道的生日（同学的、球星的都行），用计算器照做，每算完一步按一下“=”：月份乘以 5，加 6，得数乘以 4，加 9，得数再乘以 5，最后加上日子。只把最后的结果告诉你。","reveal":{"label":"看揭秘","text":"把他报的数减去 165。得数的后两位是日，前面是月。比如他报 1387：1387−165=1222，就是 12 月 22 日。","explain":"设月份是 m、日子是 d，一步步算下来：5m+6，乘 4 得 20m+24，加 9 得 20m+33，乘 5 得 100m+165，再加上 d。减掉 165 只剩 100m+d：月份被推到了百位以上，日子留在后两位。"},"hint":"先自己学会再表演。计算器用另一部手机，这部留着念步骤。心算减 165：先减 200，再加 35。揭秘后他要是想自己编一套：加 6 换成加 7，最后就减 185。","refs":[{"t":"经典数学魔术","lv":"经典"}],"art":"telescope"},{"id":"puz-027","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":5,"title":"你圈掉的数字我知道","body":"让他拿张纸，别给你看。写一个四位数（四个数字不能全一样），把数字彻底打乱变成另一个数，用大的减小的。在差里圈掉一个不是 0 的数字，把剩下的数字按随便什么顺序念给你听。","reveal":{"label":"看揭秘","text":"把他念的数字加起来，看离下一个 9 的倍数还差几，差的那个数就是他圈掉的。比如他念 3、5、8，和是 16，离 18 差 2，圈掉的就是 2。如果和已经是 9 的倍数，圈掉的是 9。","explain":"一个数除以 9 的余数，等于它各位数字之和除以 9 的余数（因为 10、100、1000 除以 9 都余 1）。打乱顺序不改变数字之和，所以两个数相减，差一定是 9 的倍数，差的各位数字加起来也是 9 的倍数。缺了谁，一补就知道。不许圈 0，是因为圈 0 和圈 9 分不出来。"},"hint":"先自己学会再表演，要纸笔。他减错了你就会猜错，先说好“减完验算一遍”。他要是说圈完没数字可念，或者只剩 0，那就是 9。","refs":[{"t":"弃九法（Casting out nines）· Wikipedia","u":"https://en.wikipedia.org/wiki/Casting_out_nines","lv":"经典"}],"art":"brain"},{"id":"puz-028","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末"],"mins":6,"title":"10 个数，我秒算总和","body":"拿张纸。让他任意写两个数（小一点好算），上下排好；第 3 个数是前两个之和，第 4 个数是第 2、3 个之和……照这样写满 10 个，你在旁边看着。他刚写完，你就报出这 10 个数的总和。","reveal":{"label":"看揭秘","text":"盯住第 7 个数，把它乘以 11，就是总和。比如他写 3 和 5：第 7 个数是 55，总和就是 605。","explain":"设头两个数是 a 和 b，往下依次是 a+b、a+2b、2a+3b、3a+5b、5a+8b（这是第 7 个）、8a+13b、13a+21b、21a+34b。10 个数加起来是 55a+88b，正好是 5a+8b 的 11 倍。"},"hint":"先自己学会再表演，要纸笔。乘以 11 的口算：把这个数错开一位和自己相加（55+550）。他写到第 7 个时你就算好了，等他写完第 10 个，立刻报数。","refs":[{"t":"经典数学魔术","lv":"经典"}],"art":"star"},{"id":"puz-029","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["车上","饭桌","周末"],"mins":3,"title":"两位数乘 11，张口就来","body":"让他随便说一个两位数，你几秒钟之内说出它乘以 11 的结果。比如他说 43，你说 473；他说 78，你说 858。他可以拿计算器验你。","reveal":{"label":"看揭秘","text":"把两个数字拉开，中间塞进它俩的和。43：4 和 3 中间塞 4+3=7，得 473。和超过 9 就向前进一位：78 是 7、15、8，进位后得 858。","explain":"乘以 11 就是“乘以 10，再加上它自己”，比如 430+43。列成竖式看：个位还是原来的个位，最高位还是原来的十位（有进位就加 1），中间那一位正好是两个数字相加。"},"hint":"先自己学会：拿不用进位的数（43、52）热热手，再让他随便出。揭秘后换他当计算器，你来出数。车上玩正好：前面那辆车车牌的末两位就是题。","refs":[{"t":"经典数学魔术","lv":"经典"}],"art":"rocket"},{"id":"puz-030","type":"puzzle","sub":"数学魔术","format":"reveal","audience":"all","for":"kid","scenes":["周末","饭桌","出游"],"mins":6,"title":"21 张牌里找出那一张","body":"拿 21 张扑克牌，牌面朝上，一张一张轮流发成 3 列（每列 7 张）。他在心里认一张，只说它在哪一列。你把这一列夹在另外两列中间，收成一叠。这样一共做 3 遍，然后从上往下数到第 11 张。","reveal":{"label":"看揭秘","text":"第 11 张，就是他认的那张。","explain":"每次把他指的那一列夹在中间，那张牌就被往整叠牌的正中间挤一次。第 1 遍之后，它在第 8–14 张之间。再发开，这 7 张落在各列的第 3–5 张，所以第 2 遍之后它在第 10–12 张之间。这 3 张再发开，正好一列一张，都排在第 4 张；第 3 遍一夹，就是第 11 张。"},"hint":"先自己试两遍再表演。发牌必须一张一张轮流发到三列，收牌时每一列里的顺序别打乱。学会以后，这个魔术归他。","refs":[{"t":"经典数学魔术","lv":"经典"}],"art":"cards"},{"id":"puz-031","type":"puzzle","sub":"估一估","format":"reveal","audience":"all","for":"three","scenes":["救场","球场","车上","出游"],"mins":5,"title":"一辆公交车能装多少篮球","body":"一辆 12 米长的公交车，把座椅全拆掉，车厢里塞满篮球，大概能塞多少个？每人先猜一个数说出口，再一起估。","reveal":{"label":"看答案","text":"大约三四千个，量级是“几千”。","explain":"①车厢里面大约长 11 米、宽 2.3 米、高 2 米，约 50 立方米。②篮球直径约 24.6 厘米，就当每个球占一个边长 25 厘米的方盒子，1 立方米能放 4×4×4=64 个。③50×64=3200 个。球错开放还能多挤进一些，所以 3000 到 4000 都算估得准；不拆座椅的话，要少几百个。"},"hint":"先各猜一个数，说出口就不许改。估的时候让他来定车厢的长宽高，你只负责按计算器。量级猜对就算赢，不比谁更精确。","refs":[{"t":"费米估算（Fermi problem）· Wikipedia","u":"https://en.wikipedia.org/wiki/Fermi_problem","lv":"经典"},{"t":"7 号篮球：周长约 75–78 厘米，直径约 24.6 厘米","lv":"常识"}],"art":"car"},{"id":"puz-032","type":"puzzle","sub":"估一估","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","睡前","球场"],"mins":4,"title":"心脏一年跳多少下","body":"不许查。你的心脏一年大概要跳多少下？先猜个量级：几十万、几百万，还是几千万？然后摸着脉搏数 15 秒，一起算。","reveal":{"label":"看答案","text":"大约 4000 万下，量级是“几千万”。","explain":"按每分钟 75 下算：一小时 4500 下，一天约 10.8 万下，一年 365 天就是约 3900 万下。成年人安静时每分钟 60–100 下都算正常，运动时更快、睡着时更慢，所以 3000 万到 5000 万都是合理的答案。"},"hint":"先猜量级再算。你看表喊“开始”“停”，两人各数自己的脉搏，报出来比一比；他的多半比你快，这很正常，报完数就接着算，别借题发挥。","refs":[{"t":"美国心脏协会：成年人静息心率的正常范围为每分钟 60–100 次","lv":"指南"}],"art":"heart"},{"id":"puz-033","type":"puzzle","sub":"估一估","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","饭桌","睡前"],"mins":3,"title":"10 亿秒是多久","body":"100 万秒大约是 11 天半。那么，10 亿秒大约是多久？","options":["大约 4 个月","大约 3 年","大约 32 年","大约 300 年"],"answer":2,"explain":"一年大约 3150 万秒（60×60×24×365），10 亿除以它，约等于 31.7 年。100 万和 10 亿只差三个零，换成时间，却是一个长假和半辈子的差别。顺便一算：你现在大约活了 4 亿秒。","hint":"先让他猜，你也猜，都说出口再点。然后一起算：他哪天满 10 亿秒？（大约 31 岁零 8 个月。）你自己早就过了。","art":"hourglass"},{"id":"puz-034","type":"puzzle","sub":"估一估","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","出游","饭桌"],"mins":4,"title":"一辈子走的路能绕地球几圈","body":"一个人从学会走路开始，一辈子用两条腿走过的路全接起来，大概能绕地球赤道几圈？","options":["不到 1 圈","3 圈左右","30 圈左右"],"answer":1,"explain":"①一天走 6000 步上下，每步约 0.7 米，一天大约 4 公里。②一年约 1500 公里。③走上 75 年，约 11 万公里。地球赤道一圈约 4 万公里，所以是 3 圈左右。特别爱走路的人能到 5 圈，整天坐着的也有一两圈，量级不变。","hint":"先各选一个再点开。接着打开你手机里的步数记录，把你的数字交给他重算一遍，看你这辈子能绕几圈。","refs":[{"t":"地球赤道周长约 40075 公里","lv":"常识"}],"art":"globe"},{"id":"puz-035","type":"puzzle","sub":"估一估","format":"quiz","audience":"all","for":"three","scenes":["救场","饭桌","车上"],"mins":3,"title":"一辈子喝的水能装满什么","body":"一个人活到 80 岁，这辈子喝下去的水全攒在一起，大概能装满下面哪一个？","options":["一个浴缸","一间卧室","一个 50 米标准泳池","一个小湖"],"answer":1,"explain":"①一天喝水大约 1.5–1.7 升，取 1.7 升。②一年约 600 升，也就是 0.6 立方米。③80 年约 50 立方米。一间 4 米×4 米、高 2.8 米的卧室约 45 立方米，差不多正好。浴缸只有 0.3 立方米左右，半年就喝完了；50 米的标准泳池约 2500 立方米，够 50 个人喝一辈子。","hint":"先各选一个再点开。他要是选了游泳池，别笑，很多人都这么选。再让他估估：到今天为止，他已经喝掉了几浴缸水？（20 个上下。）","refs":[{"t":"《中国居民膳食指南（2022）》：成年人每天饮水 1500–1700 毫升","lv":"指南"}],"art":"cup"},{"id":"puz-036","type":"puzzle","sub":"估一估","format":"reveal","audience":"all","for":"three","scenes":["饭桌","救场"],"mins":4,"title":"一碗饭有多少粒米","body":"一碗盛得满满的白米饭，不许数，凭感觉说：里面大概有多少粒米？几百、几千，还是几万？每人报一个数。","reveal":{"label":"看答案","text":"大约四五千粒，量级是“几千”。","explain":"①一碗饭大约要用 80–100 克生米。②大米 1000 粒重 20 克左右，也就是 1 克大约 50 粒。③所以一碗是 4000–5000 粒。碗大碗小、米粒长短都会让结果变，3000 到 6000 之间都算估对了。"},"hint":"饭桌上玩最好。先各报一个数，说出口不许改。想验证的话，数一勺有多少粒，再数一碗有几勺；让他来数，你只管记数。","refs":[{"t":"大米千粒重因品种而异，量级在 20 克上下","lv":"常识"}],"art":"table"},{"id":"puz-037","type":"puzzle","sub":"估一估","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","球场"],"mins":3,"title":"全校排成一排有多长","body":"假设一所学校有 1200 个学生，全体肩并肩站成一横排。这一排大概有多长？能绕 400 米的操场跑道几圈？","reveal":{"label":"看答案","text":"大约 600 米，能绕操场一圈半。","explain":"肩并肩站着，每个人大约占半米宽（肩宽 40 厘米左右，再留一点缝）。1200×0.5=600 米。站得挤一点是 500 米，松一点是 700 米。你们学校要是也这么排，能绕几圈？"},"hint":"让他伸手比一比“半米”有多宽，再让他估估自己学校有多少人。接着问：要是手拉手排呢？（每人约 1.3 米，将近 4 圈。）","art":"flag"},{"id":"puz-038","type":"puzzle","sub":"找规律","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"三个数列，一个比一个坏","body":"每一行的下一个数是什么？\n① 2，6，12，20，30，?\n② 1，2，6，24，120，?\n③ 31，28，31，30，31，?","reveal":{"label":"看答案","text":"① 42　② 720　③ 30","explain":"①相邻两数的差是 4、6、8、10，下一个差 12；也可以看成 1×2、2×3、3×4……下一个是 6×7。②依次乘以 2、3、4、5，下一个该乘以 6。③不是算出来的：这是平年 1 月到 5 月的天数，6 月有 30 天。"},"hint":"前两个他应该很快。第三个卡住时别提示算法，只说一句：“这串数你每年都见。”他要是被气笑了，就对了。","refs":[{"t":"经典趣味谜题","lv":"经典"}],"art":"puzzle"},{"id":"puz-039","type":"puzzle","sub":"找规律","format":"reveal","audience":"all","for":"kid","scenes":["车上","饭桌","睡前"],"mins":5,"title":"1，11，21，1211，?","body":"找规律，写出下一行：\n1\n11\n21\n1211\n111221\n?","reveal":{"label":"看答案","text":"312211","explain":"每一行都是把上一行“念”出来：1 念作“1 个 1”，写成 11；11 是“2 个 1”，写成 21；21 是“1 个 2、1 个 1”，写成 1211；1211 是“1 个 1、1 个 2、2 个 1”，写成 111221。所以下一行是“3 个 1、2 个 2、1 个 1”：312211。"},"hint":"用算术找不到规律，大人往往比孩子慢。卡住时只说：“别算，大声念出来。”再下一行是 13112221，他想接着写就随他。","refs":[{"t":"外观数列（Look-and-say sequence）· Wikipedia","u":"https://en.wikipedia.org/wiki/Look-and-say_sequence","lv":"经典"}],"art":"chat"},{"id":"puz-040","type":"puzzle","sub":"找规律","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"O，T，T，F，F，S，S，?","body":"下一个字母是什么？\n**O，T，T，F，F，S，S，?**\n提示只有一句：这串东西，你刚学英语时就会背了。","reveal":{"label":"看答案","text":"E。再往后是 N、T。","explain":"One，Two，Three，Four，Five，Six，Seven 的首字母。下一个是 Eight，然后是 Nine、Ten。"},"hint":"他英语好，这题很可能比你快，输了就认。然后让他照这个路子给你出一道，比如星期或者月份的首字母。","refs":[{"t":"经典趣味谜题","lv":"经典"}],"art":"abc"},{"id":"puz-041","type":"puzzle","sub":"找规律","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":5,"title":"移 1 根牙签，让等式成立","body":"用牙签摆出一道罗马数字算式：\n**X + II = X**\n（I 是 1，V 是 5，X 是 10；VI 是 6，IV 是 4。）10+2=10，显然错了。只许移动 1 根牙签，让等式成立。有两种移法，都找出来。","reveal":{"label":"看答案","text":"①从 II 里拿一根，放到第一个 X 的左边：IX + I = X（9+1=10）。②从 II 里拿一根，放到最后那个 X 的右边：X + I = XI（10+1=11）。","explain":"罗马数字里，小的数字写在大的右边是加，写在左边是减。同一根牙签，换个位置，就从“加 1”变成了“减 1”。"},"hint":"没有牙签就用棉签、笔，或者在纸上画。他要是把一根斜搭在等号上变成“≠”，算他机灵，再请他找“=”的两种解。V+V=X 要动两根，不算。","refs":[{"t":"经典火柴棍谜题","lv":"经典"}],"art":"bulb"},{"id":"puz-042","type":"puzzle","sub":"找规律","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末"],"mins":6,"title":"移 3 枚硬币，三角形倒过来","body":"10 枚硬币摆成一个尖朝上的三角形，从上到下每排 1、2、3、4 枚。只许移动 3 枚硬币，让整个三角形变成尖朝下（从上到下每排 4、3、2、1 枚）。","reveal":{"label":"看答案","text":"只动三个角：把最上面那 1 枚移到最下面一排的正下方，当新的尖；把最下面一排两头的 2 枚，分别移到第 2 排（原来只有 2 枚的那排）的左右两边。","explain":"倒过来的三角形和原来的三角形可以重叠 7 枚：第 2 排的 2 枚、第 3 排的 3 枚、第 4 排中间的 2 枚，一枚都不用动。只有三个角需要搬家。"},"hint":"一定要摆实物：硬币、棋子、瓶盖都行。先让他自由试。卡住时提示：“中间哪些硬币，可以一枚都不动？”","refs":[{"t":"经典硬币谜题","lv":"经典"}],"art":"mountain"},{"id":"puz-043","type":"puzzle","sub":"找规律","format":"quiz","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":4,"title":"方格里藏着多少个正方形","body":"一个大正方形被画成 4×4 的方格，像一板 16 格的巧克力。这块方格里一共有多少个正方形？大大小小都算。","options":["16 个","17 个","30 个","64 个"],"answer":2,"explain":"边长 1 格的有 16 个，2 格的有 9 个（横着 3 种放法、竖着 3 种），3 格的有 4 个，4 格的就是最外面那 1 个：16+9+4+1=30。规律是 4×4+3×3+2×2+1×1。照这个规律，8×8 的国际象棋棋盘上一共有 204 个正方形。","hint":"拿纸画一个 4×4 的方格更好数。他先答 16 或 17 都正常，只问一句：“2×2 的算不算？”剩下的让他自己数。","refs":[{"t":"经典趣味数学题","lv":"经典"}],"art":"chess"},{"id":"puz-044","type":"puzzle","sub":"找规律","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","周末"],"mins":5,"title":"4 刀最多切几块","body":"一张圆披萨，每一刀都是一条直线，从边切到边；切的时候披萨不许挪动，也不许叠起来。切 4 刀，最多能切成几块？（不要求每块一样大。）","reveal":{"label":"看答案","text":"11 块。","explain":"找规律：1 刀 2 块，2 刀 4 块，3 刀 7 块，4 刀 11 块，每次多出 2、3、4 块。原因是：新的一刀如果和前面每一刀都相交，又不从旧的交点上过，那么第 n 刀会被截成 n 段，每一段把一块披萨劈成两块，于是多出 n 块。"},"hint":"拿纸画圆来试。他多半先答 8（切成“米”字）。问他：“每一刀都非得过圆心吗？”让他先试出 3 刀切 7 块，再去找 4 刀。","refs":[{"t":"切饼数列（Lazy caterer's sequence）· Wikipedia","u":"https://en.wikipedia.org/wiki/Lazy_caterer%27s_sequence","lv":"经典"}],"art":"pizza"},{"id":"puz-045","type":"puzzle","sub":"破案","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","出差","睡前"],"mins":2,"title":"走错房间的陌生人","body":"旅馆里，一位房客听见敲门声，开门一看，是个陌生人。那人说：“对不起，走错了，我还以为这是我的房间。”说完转身走了。房客关上门，立刻打电话给前台：“请留意一下这个人。”他为什么起了疑心？","reveal":{"label":"看答案","text":"回自己的房间，谁会先敲门？","explain":"真以为那是自己的房间，他会直接掏房卡开门。先敲门，更像是在试探屋里有没有人。当然，他也可能是忘了带卡、屋里有同伴，所以房客没有一口咬定，只是请前台留意。"},"hint":"先别提示，让他把那人说的话再念一遍。他答出来后追问：“那个人敲门，真正想知道的是什么？”他能想到别的解释，也算数。","refs":[{"t":"经典推理小故事","lv":"经典"}],"art":"door"},{"id":"puz-046","type":"puzzle","sub":"破案","format":"quiz","audience":"all","for":"three","scenes":["救场","饭桌","车上"],"mins":2,"title":"停电那晚的蛋糕","body":"昨晚 8 点到 10 点整栋楼停电，冰箱里最后一块蛋糕就在这段时间不见了。哥哥说：“我一直窝在房间，用平板连着家里的 Wi-Fi 看球赛直播。”姐姐说：“我打着手电在找蜡烛。”表弟说：“我 7 点半就睡了。”谁的话有漏洞？","options":["哥哥","姐姐","表弟"],"answer":0,"explain":"平板有电池，停电照样能亮；可家里的路由器要插电，一停电 Wi-Fi 就断了，他不可能“一直”连着看直播。姐姐打手电、表弟早睡，都和停电不矛盾。蛋糕是不是他吃的还不好说，但他得先解释：那两个小时他到底在干什么。","hint":"他要是说“平板有电池，没毛病”，先点头，再问：“那 Wi-Fi 是从哪儿来的？”他要是抬杠“路由器接了充电宝”，就说：那得哥哥自己拿出来。","art":"sofa"},{"id":"puz-047","type":"puzzle","sub":"破案","format":"reveal","audience":"all","for":"kid","scenes":["救场","饭桌","睡前"],"mins":3,"title":"夹在书里的 100 块","body":"表哥嚷嚷：“我明明把一张 100 块夹在那本小说的第 57 页和第 58 页之间，现在没了，肯定被人拿走了！”奶奶翻了翻那本书，笑了：“你再想想，是你记错了。”奶奶为什么这么肯定？","reveal":{"label":"看答案","text":"第 57 页和第 58 页是同一张纸的正反两面，中间夹不了任何东西。","explain":"随手拿一本书看看：单数页码印在一张纸的正面，紧跟着的双数页码印在它的背面。能夹东西的地方，是“58 页和 59 页之间”这样的位置。"},"hint":"先让他空想。卡住了、手边又有书，再让他翻到第 57 页瞧瞧。他要是找到一本页码排法不一样的书，那就算他赢。","refs":[{"t":"经典推理小故事","lv":"经典"}],"art":"book"},{"id":"puz-048","type":"puzzle","sub":"破案","format":"reveal","audience":"all","for":"kid","scenes":["饭桌","睡前","周末"],"mins":4,"title":"照片里的那面钟","body":"有人说下午 3 点整他在家，还拿出朋友给他拍的照片作证：他身后的镜子里映着一面没有数字的挂钟，镜中的指针正好是 3 点整的样子。侦探看了一眼：“这张照片不是 3 点拍的。”那是几点拍的？","reveal":{"label":"看答案","text":"9 点整。","explain":"镜子把左右调了个个儿。镜子里看上去指着右边“3”的时针，实际指着左边的“9”；分针指着正上方，照不照镜子都一样。所以拍照的真正时间是 9 点整（上午还是晚上就看不出来了）。他拿出来的证据，反而拆了自己的台。"},"hint":"卡住时带他去照镜子：让他举起右手，问镜子里的人举的是哪边。家里有带指针的钟或手表，就对着镜子摆一摆。","art":"camera"},{"id":"puz-049","type":"puzzle","sub":"破案","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","出游"],"mins":3,"title":"旧货摊上的“真古董”","body":"旧货摊上，摊主神秘地掏出一枚铜钱：“这可是真古董，你自己看，上面清清楚楚刻着‘公元前 221 年造’。”爸爸还没开口，旁边的孩子就笑了：“假的。”他是怎么看出来的？","reveal":{"label":"看答案","text":"公元前的人，不可能知道自己活在“公元前”。","explain":"“公元”这种纪年法是很多年以后才有的，再往回倒着数，才有了“公元前”。当时的工匠只会用当时的纪年，绝不会刻出一个还不存在的说法。"},"hint":"他要是说“看着太新”“字不对”，都回答：“也可能，但有一个更硬的破绽，就在摊主那句话里。”让他再念一遍。","refs":[{"t":"经典推理小故事","lv":"经典"}],"art":"magnifier"},{"id":"puz-050","type":"puzzle","sub":"破案","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","车上","饭桌"],"mins":3,"title":"那晚狗为什么没叫","body":"球队的吉祥物玩偶昨晚从器材室门口被人抱走了。看门的大黄狗一见生人就狂叫，可那晚谁也没听见狗叫。到过附近的有三个人：新来的保洁员、第一次来送货的司机、每天喂大黄的管理员。谁最可疑？","options":["新来的保洁员","第一次来送货的司机","每天喂大黄的管理员"],"answer":2,"explain":"狗没叫，本身就是线索：来的人它认识。三个人里，只有每天喂它的管理员是熟人。福尔摩斯在《银色马》那个案子里，靠的也是同一个发现：夜里那条狗一声没吭。","hint":"他选完先问理由。要是他觉得管理员最不像，就问：“大黄那晚为什么那么安静？”他要是说“也可能有人拿吃的收买了狗”，也算数。","refs":[{"t":"柯南·道尔《银色马》（福尔摩斯探案）里的推理，改编","u":"https://en.wikipedia.org/wiki/The_Adventure_of_Silver_Blaze","lv":"经典"}],"art":"whistle"},{"id":"show-001","type":"show","sub":"篮球","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","车上"],"mins":2,"title":"24 秒是怎么算出来的？","body":"NBA 一次进攻限时 24 秒。不是 20，不是 30，偏偏是 24。这个数当年是怎么定下来的？","options":["照搬了大学篮球的规定","试过几种时长，挑了最流畅的","48 分钟 ÷ 120 次出手"],"answer":2,"explain":"1954 年，一位球队老板翻了翻他觉得好看的那些比赛：两队各出手 60 次左右，加起来 120 次。一场 48 分钟是 2880 秒，2880÷120=24。在这之前，领先的一方可以一直倒球不投，1950 年甚至打出过 19 比 18 的比分。","more":"这位老板叫丹尼·比亚索内，球队是锡拉丘兹民族队。那场 19 比 18 的比赛，第 4 节两队加起来只得了 4 分。\n\nNBA 从 1954–55 赛季开始用 24 秒。国际篮联 1956 年先用的是 30 秒，到 2000 年才改成 24 秒。","hint":"先用手挡住选项，让他自己编个理由，你也编一个，比谁编得像真的。揭晓后一起按计算器：2880÷120。","refs":[{"t":"Shot clock · Wikipedia","u":"https://en.wikipedia.org/wiki/Shot_clock","lv":"常识"}],"art":"stopwatch","tags":["篮球","NBA","规则"]},{"id":"show-002","type":"show","sub":"篮球","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","车上"],"mins":2,"title":"最早的篮球，接到球能干嘛？","body":"1891 年篮球刚发明时，规则一共只有 13 条。那时候球员接到球以后，可以做什么？","options":["只能站在原地把球传出去","最多拍 3 下球","抱着球最多跑 3 步"],"answer":0,"explain":"最初的规则写得很死：不许带着球跑，必须在接到球的地方把它传出去。运球是后来才有的——1901 年前后才写进规则，而且只许拍一下，拍完还不许投篮。1909 年起，才可以连续运球、运完直接投。","more":"有记录的第一支靠运球打比赛的球队，是 1897 年的耶鲁大学队。\n\n没有运球的篮球更像传球接力：一队 9 个人满场站好，谁拿到球，谁就得定在原地找人。","hint":"他多半不信。问他：一场谁都不许运球的比赛该怎么打？下次去球场，真来 2 分钟“只传不运”，输了你认。","refs":[{"t":"Rules of basketball · Wikipedia","u":"https://en.wikipedia.org/wiki/Rules_of_basketball","lv":"常识"},{"t":"Dribbling · Wikipedia","u":"https://en.wikipedia.org/wiki/Dribbling","lv":"常识"}],"art":"whistle","tags":["篮球","规则","运球"]},{"id":"show-003","type":"show","sub":"篮球","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","饭桌"],"mins":2,"title":"NBA 哪年才有三分球？","body":"NBA 从 1946 年开打。一开始，站多远投进都只算 2 分。三分线是哪一年才画上去的？","options":["1954 年","1967 年","1979 年","1988 年"],"answer":2,"explain":"NBA 的头 33 年没有三分球。1979–80 赛季才画上三分线，而且一开始只说“先试一年”。国际篮联更晚，1984 年才有；奥运会要等到 1988 年。","more":"三分球不是 NBA 的主意。1961 年，一个叫 ABL 的小联盟最先用上；1967 年，NBA 的对手联盟 ABA 也开始用。NBA 是后来才跟进的。\n\n现在 NBA 的三分线离篮筐中心最远 7.24 米，国际篮联的是 6.75 米。","hint":"他要是早就知道，就让他讲给你听，再问一句：没有三分线的年代，射手怎么办？你只听，不评。","refs":[{"t":"Three-point field goal · Wikipedia","u":"https://en.wikipedia.org/wiki/Three-point_field_goal","lv":"常识"}],"art":"target","tags":["篮球","NBA","三分球"]},{"id":"show-004","type":"show","sub":"篮球","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","车上"],"mins":2,"title":"篮筐为什么是 3.05 米？","body":"全世界正规比赛的篮筐都一样高：3.05 米。这个有零有整的数，是怎么来的？","options":["按当时成年人的摸高算出来的","体育馆的看台栏杆正好这么高","试了很多高度，这个命中率最合适"],"answer":1,"explain":"1891 年，发明篮球的奈史密斯把两个桃篮钉在体育馆二层看台的栏杆上。那根栏杆离地正好 10 英尺，换算过来就是 3.05 米。没人专门算过。后来篮子换成了铁圈和网，高度却一直没动。","hint":"揭晓后只问一句：要是当年那根栏杆再矮半米，今天的篮球会变成什么样？然后让他说，别接“所以”。","refs":[{"t":"Springfield College：Where Basketball was Invented","u":"https://springfield.edu/where-basketball-was-invented-the-birthplace-of-basketball","lv":"官方"},{"t":"NBA.com：篮球诞生 125 周年纪念文章","u":"https://www.nba.com/news/celebrating-125th-anniversary-basketball","lv":"官方"}],"art":"hoop","tags":["篮球","篮筐","奈史密斯"]},{"id":"show-005","type":"show","sub":"篮球","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","饭桌"],"mins":2,"title":"篮球最早是什么颜色？","body":"现在的篮球大多是橙色的。可在最初的几十年里，它根本不是这个颜色。","options":["深棕色","白色","黑色"],"answer":0,"explain":"最早打篮球用的其实是足球。后来专门做的篮球是深棕色的，在球馆里不太显眼。1950 年代末，美国一位大学教练托尼·欣克尔想让球员和观众都看得更清楚，才推出了橙色的球，一直用到今天。","hint":"让他先猜。然后问：让你来定，你选什么颜色？他说荧光绿、全黑都行，别评价，顺着聊就好。","refs":[{"t":"Basketball（History 一节）· Wikipedia","u":"https://en.wikipedia.org/wiki/Basketball","lv":"常识"}],"art":"ball","tags":["篮球","器材"]},{"id":"show-006","type":"show","sub":"篮球","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","车上"],"mins":2,"title":"篮板最早是干什么用的？","body":"篮筐后面那块板，一开始是没有的。后来为什么要加上它？","options":["让球打板以后更容易进","挡住看台上伸手的观众","防止球飞出去砸到人"],"answer":1,"explain":"早期的篮筐直接钉在二层看台的栏杆上，楼上的观众一伸手，就能把球拨进去或者挡出来。加一块板把人和筐隔开，这就是篮板。至于打板进球，是装上以后球员才发现的“赠品”。","hint":"他要是选“打板更容易进”，别说“错”：那是篮板现在的本事，只是不是它最初的差事。翻开答案一起看，看完就停。","refs":[{"t":"Basketball（History 一节）· Wikipedia","u":"https://en.wikipedia.org/wiki/Basketball","lv":"常识"},{"t":"NBA.com：篮球诞生 125 周年纪念文章","u":"https://www.nba.com/news/celebrating-125th-anniversary-basketball","lv":"官方"}],"art":"hoop","tags":["篮球","篮板","器材"]},{"id":"show-007","type":"show","sub":"篮球","format":"reveal","audience":"all","for":"kid","scenes":["球场","救场","周末"],"mins":3,"title":"好射手的球为什么倒着转？","body":"仔细看好射手出手：球是向后转着飞出去的，这叫后旋。除了好看，这个旋转到底帮了什么忙？","reveal":{"label":"看答案","text":"后旋让球变“软”：碰到篮筐或篮板以后弹得更慢、离筐更近，更容易掉进去。","explain":"球向后转着碰到筐沿，摩擦力会把它往回拽；碰到篮板，摩擦力会把它往下拽。两种情况都在帮它减速、往筐里送。美国北卡州立大学的两位工程师用电脑模拟了几十万次罚球，结论是每秒转 3 圈左右的后旋最合适。"},"more":"这是电脑模拟出来的结果，用的是男子比赛用球的数据，不是真人实测。换个人、换个球，具体数字会有出入。","hint":"别讲力学。手边有球（没有就用橘子）向后搓着抛一下，让他看清转的方向就够了。剩下的留给球场。","refs":[{"t":"北卡州立大学工程学院：Nothing But Net","u":"https://engr.ncsu.edu/news/2009/11/06/nothing-but-net-the-physics-of-free-throw-shooting/","lv":"实证"},{"t":"Tran & Silverberg (2008)，Journal of Sports Sciences","lv":"实证"}],"art":"ball","tags":["篮球","物理","后旋","投篮"]},{"id":"show-008","type":"show","sub":"篮球","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","车上","饭桌"],"mins":2,"title":"第一场篮球赛，比分多少？","body":"1891 年 12 月，人类历史上第一场篮球赛。两队打完，最后的比分是多少？","options":["0 比 0","12 比 10","21 比 18","1 比 0"],"answer":3,"explain":"全场只进了一个球。那天 18 个学生分成两队，一队 9 个人，用的还是足球，篮筐是钉在栏杆上的桃篮。唯一的进球来自一个叫威廉·蔡斯的学生，出手的地方离筐七八米远——放到今天是个三分球。","more":"那时候的桃篮是有底的。每进一个球，都得有人把球从篮子里取出来——好在那天全场只进了一个。","hint":"你先故意猜个大比分垫底。揭晓后问：九打九、不许运球，换你上场站哪儿？听他排兵布阵。","refs":[{"t":"NBA.com：篮球诞生 125 周年纪念文章","u":"https://www.nba.com/news/celebrating-125th-anniversary-basketball","lv":"官方"},{"t":"History of basketball · Wikipedia","u":"https://en.wikipedia.org/wiki/History_of_basketball","lv":"常识"}],"art":"scoreboard","tags":["篮球","历史","奈史密斯"]},{"id":"show-009","type":"show","sub":"天上地下","format":"quiz","audience":"all","for":"kid","scenes":["救场","睡前","车上"],"mins":2,"title":"哪颗行星一天比一年长？","body":"太阳系里有一颗行星：自己转一圈花的时间，比绕太阳转一圈还要长。是哪一颗？","options":["火星","金星","木星","土星"],"answer":1,"explain":"金星自转一圈要 243 个地球日，绕太阳一圈却只要 225 个地球日。它还是倒着转的：站在金星上，太阳从西边升起、东边落下。","more":"这里说的“一天”是自转一整圈。如果按“这次日出到下次日出”来算，因为金星倒着转，一昼夜大约是 117 个地球日，反而比它的一年短。两种说法都没错，只是量法不同。\n\n水星正好反过来：自转一圈（59 个地球日）比一年（88 个地球日）短，可从日出等到下一次日出要 176 个地球日，等于它的 2 年。\n\n金星还是太阳系最热的行星，表面 460 多摄氏度，比离太阳更近的水星还热：厚厚的大气把热量全捂在了里面。","hint":"他要是脱口而出“金星”，就追问：那金星上太阳从哪边出来？这个他多半不知道——你也是刚知道的，照实说。","refs":[{"t":"NASA Science：Venus Facts","u":"https://science.nasa.gov/venus/venus-facts/","lv":"官方"},{"t":"NASA Science：Mercury Facts","u":"https://science.nasa.gov/mercury/facts/","lv":"官方"}],"art":"planet","tags":["宇宙","行星","金星"]},{"id":"show-010","type":"show","sub":"天上地下","format":"quiz","audience":"all","for":"kid","scenes":["救场","睡前","车上"],"mins":2,"title":"空间站上一天看几次日出？","body":"在地面上，一天只有一次日出。住在空间站里的宇航员，24 小时能看到几次？","options":["还是 1 次","4 次左右","16 次左右","24 次，每小时 1 次"],"answer":2,"explain":"国际空间站大约每 90 分钟绕地球一圈，一天 16 圈，所以 24 小时里要经过 16 次日出和 16 次日落。它每秒飞将近 8 公里——从北京到上海，2 分多钟。","more":"中国空间站也差不多：轨道高度在 400 公里上下，90 分钟左右绕一圈，航天员每天同样要过十几次“早晨”。\n\n所以在空间站里没法看太阳过日子，作息统一按钟表来。","hint":"先用手挡住选项，只说“90 分钟绕地球一圈”，各自心算一天几圈，同时报数。你算错了就认，他算对了别补课。","refs":[{"t":"NASA：Space Station Facts and Figures","u":"https://www.nasa.gov/international-space-station/space-station-facts-and-figures/","lv":"官方"},{"t":"Tiangong space station · Wikipedia","u":"https://en.wikipedia.org/wiki/Tiangong_space_station","lv":"常识"}],"art":"rocket","tags":["宇宙","空间站","宇航员"]},{"id":"show-011","type":"show","sub":"天上地下","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":2,"title":"冬天地球离太阳更远吗？","body":"北半球的冬天这么冷。这个时候的地球，离太阳是更近还是更远？","options":["更远，所以才冷","更近","一年到头一样远"],"answer":1,"explain":"每年 1 月初，地球离太阳最近（约 1.47 亿公里）；7 月初最远（约 1.52 亿公里）。冷热和这点远近关系不大，是因为地球歪着身子转：冬天，北半球这一头正好歪向背着太阳的一边，阳光斜着照，白天又短。这时候南半球正在过夏天。","hint":"你先大大方方选“更远”，答错给他看。等他来纠正你，再问：那这会儿澳大利亚是什么季节？","refs":[{"t":"NASA Space Place：What Causes the Seasons?","u":"https://spaceplace.nasa.gov/seasons/en/","lv":"官方"}],"art":"snow","tags":["地球","四季","太阳"]},{"id":"show-012","type":"show","sub":"天上地下","format":"quiz","audience":"all","for":"kid","scenes":["救场","睡前","车上"],"mins":2,"title":"闪电和太阳表面，谁更热？","body":"一边是天上一闪而过的闪电，一边是烧了几十亿年的太阳表面。哪个温度更高？","options":["太阳表面，高得多","两个差不多","闪电，高好几倍"],"answer":2,"explain":"闪电经过的那一小条空气，瞬间能被加热到两万七八千摄氏度，大约是太阳表面的 5 倍。空气被烫得猛地膨胀开，那一声炸响就是雷。","more":"注意比的是太阳的“表面”（约 5500 摄氏度）。太阳中心有 1000 多万摄氏度，闪电就差远了。\n\n顺便辟个谣：“闪电不会两次打中同一个地方”是假的。又高又尖的东西会被反复击中，纽约的帝国大厦平均每年要挨 20 多下。","hint":"打雷的晚上拿出来最好。各押一个，输的人负责解释雷声是怎么来的——答案卡片上有，一起看。","refs":[{"t":"美国国家气象局：How Hot Is Lightning?","u":"https://www.weather.gov/safety/lightning-temperature","lv":"官方"},{"t":"美国国家气象局：Lightning Myths","u":"https://www.weather.gov/safety/lightning-myths","lv":"官方"}],"art":"sun","tags":["地球","闪电","天气","辟谣"]},{"id":"show-013","type":"show","sub":"天上地下","format":"reveal","audience":"all","for":"kid","scenes":["救场","出游","车上"],"mins":3,"title":"最高的山，有三个答案","body":"先别急着喊珠穆朗玛峰。换一种量法，冠军就换人。另外两种量法、两座山，猜得到吗？","reveal":{"label":"看答案","text":"从海平面量：珠穆朗玛峰，约 8849 米。从海底的山脚量到山顶：夏威夷的冒纳凯阿，约 1 万米，大半截泡在海里。离地心最远：厄瓜多尔的钦博拉索山。","explain":"地球不是正圆的球，赤道那一圈往外鼓。钦博拉索山几乎就在赤道上，海拔只有 6200 多米，山顶却比珠峰顶离地心还远 2000 多米。站在那儿，你就是全地球离地心最远的人。"},"hint":"他喊“珠峰”时别说“错”，说“对了三分之一”。另外两座让他乱猜，猜不到再翻。想查地图，留到最后。","refs":[{"t":"NOAA：What is the highest point on Earth?","u":"https://oceanservice.noaa.gov/facts/highestpoint.html","lv":"官方"}],"art":"mountain","tags":["地球","地理","珠峰"]},{"id":"show-014","type":"show","sub":"天上地下","format":"quiz","audience":"all","for":"kid","scenes":["救场","出游","饭桌"],"mins":2,"title":"太空里看得见长城吗？","body":"“长城是太空中唯一能用肉眼看到的人造建筑。”这句话很多人都听过。是真的吗？","options":["真的，而且是唯一的","半真：要到月球上才看得见","假的，肉眼基本认不出来"],"answer":2,"explain":"长城很长，可是只有几米宽，颜色又和周围的山差不多。2003 年杨利伟从太空回来，说他没有看到长城。NASA 的说法也一样：在几百公里高的轨道上，肉眼一般认不出它；从月球上更是绝对看不到。","more":"用长焦镜头倒是拍得到。华裔宇航员焦立中在国际空间站拍到过一小段长城——他自己当时都不确定拍没拍到，是后来专家在照片上认出来的。\n\n在轨道上，肉眼更容易看到的人类痕迹，是夜里城市的灯光。","hint":"这是张辟谣卡。他要是早知道，就让他讲给你听；你只问：那在太空里到底能看见什么？别补“课本也会错”。","refs":[{"t":"NASA：Great Wall（图片说明）","u":"https://www.nasa.gov/image-article/great-wall","lv":"官方"},{"t":"Great Wall of China（Visibility from space）· Wikipedia","u":"https://en.wikipedia.org/wiki/Great_Wall_of_China","lv":"常识"}],"art":"telescope","tags":["宇宙","长城","辟谣"]},{"id":"show-015","type":"show","sub":"人体","format":"quiz","audience":"all","for":"kid","scenes":["救场","睡前","车上"],"mins":2,"title":"为什么自己挠自己不痒？","body":"别人一挠你就笑得不行，自己挠同一个地方却一点感觉都没有。问题出在哪儿？","options":["大脑提前知道了要碰哪儿","自己下手总是太轻","皮肤认得出自己的手"],"answer":0,"explain":"你的手一动，小脑就已经算好“下一秒哪儿会被碰到”，大脑顺手把这份感觉调小了。没有意外，就不痒。科学家让人操纵机器手来挠自己：只要机器晚零点几秒才动，或者偷偷换个方向，人就又觉得痒了。","hint":"先让他挠挠自己的手心，再把你的手心伸过去让他挠。你躲得越狼狈越好。答案一句话说完，不展开。","refs":[{"t":"Tickling · Wikipedia","u":"https://en.wikipedia.org/wiki/Tickling","lv":"常识"},{"t":"Blakemore, Frith & Wolpert (1999)，J. Cognitive Neuroscience","lv":"实证"}],"art":"brain","tags":["人体","大脑","挠痒"]},{"id":"show-016","type":"show","sub":"人体","format":"plain","audience":"all","for":"kid","scenes":["救场","睡前","饭桌"],"mins":3,"title":"谁先打哈欠谁输","body":"打哈欠会传染：看见别人打、听见声音，甚至只是读到“哈欠”这两个字，都可能跟着来一个。现在面对面，各自假装打几个，看谁先中招。","more":"这叫“传染性哈欠”，实验里反复出现过。为什么会这样，科学家到现在也没有统一的答案：有人认为和体会别人的感受有关，但证据并不一致。\n\n不只是人。黑猩猩之间会互相传染；在一项实验里，29 只狗当中有 21 只，在陌生人冲它打哈欠之后也跟着打了。\n\n“打哈欠是因为缺氧”这个老说法也没站住脚：实验里让人多吸氧气，哈欠并没有变少。","hint":"别解释，先冲他夸张地打一个哈欠。等他中招了，再把卡片亮给他。睡前用最灵，打完正好关灯。","refs":[{"t":"Yawn · Wikipedia","u":"https://en.wikipedia.org/wiki/Yawn","lv":"常识"}],"art":"bed","tags":["人体","哈欠","小游戏"]},{"id":"show-017","type":"show","sub":"人体","format":"quiz","audience":"all","for":"kid","scenes":["球场","救场","车上"],"mins":2,"title":"为什么第二天才开始酸？","body":"打完球当天没事，第二天一起床，腿酸得下不了楼。这份酸痛是哪儿来的？","options":["乳酸堆在肌肉里没散掉","肌肉纤维有了细小的损伤","出汗太多，肌肉缺水"],"answer":1,"explain":"乳酸是被冤枉的：运动完 1 小时左右，它就回到正常水平了。真正的原因是肌肉干了不习惯的活，纤维上出现了极细小的损伤，修补的过程让你觉得酸。这种酸一般在运动后 1 到 3 天最厉害。","more":"它有个正式的名字：延迟性肌肉酸痛。最容易惹上它的，是“一边用力一边被拉长”的动作，比如下山、下楼梯、跳起来落地。\n\n肌肉适应得很快：同样的运动过几天再做一次，就不怎么酸了。","hint":"等他自己喊腿酸的时候再拿出来。你先说“是乳酸吧”，让卡片来纠正你。别顺势提热身和拉伸。","refs":[{"t":"Delayed onset muscle soreness · Wikipedia","u":"https://en.wikipedia.org/wiki/Delayed_onset_muscle_soreness","lv":"常识"}],"art":"sneaker","tags":["人体","运动","肌肉","辟谣"]},{"id":"show-018","type":"show","sub":"人体","format":"quiz","audience":"all","for":"kid","scenes":["救场","球场","车上","饭桌"],"mins":2,"title":"枪响之后起跑，也算抢跑？","body":"百米比赛，发令枪明明已经响了，你才蹬出去——居然还是可能被判抢跑。枪响后多快起动，算“太快”？","options":["0.01 秒以内","0.1 秒以内","0.5 秒以内"],"answer":1,"explain":"大赛的起跑器里装着传感器。规则认定：人从听见枪声到蹬出去，至少要 0.1 秒；比这还快，只能说明你是在猜枪。世界顶尖选手的起跑反应，通常也要 0.1 秒多一点。","more":"这条线划得对不对，一直有人争：有研究认为，极少数顶尖选手也许真能快过 0.1 秒。可规则就是规则，世界大赛上有选手因为 0.099 秒——只快了千分之一秒——被罚下场。\n\n一般年轻人看到信号再按键，大约要 0.2 秒；听到声音会快一点，0.16 秒左右。","hint":"看完别总结。直接去「工具箱」找「反应对决」比一局，看你俩离 0.1 秒差多远。输了就认。","refs":[{"t":"False start · Wikipedia","u":"https://en.wikipedia.org/wiki/False_start","lv":"常识"},{"t":"World Athletics《竞赛与技术规则》起跑部分","lv":"官方"}],"art":"flag","tags":["人体","反应时间","田径"]},{"id":"show-019","type":"show","sub":"人体","format":"plain","audience":"all","for":"kid","scenes":["饭桌","救场"],"mins":2,"title":"“舌头地图”是假的","body":"舌尖尝甜、两边尝酸、舌根尝苦——这张图很多人都见过。其实舌尖、两边、舌根，哪儿都能尝出各种味道。下回吃糖，把它推到舌头侧面试试。","more":"这张图的来历是一连串误会。1901 年，一位德国科学家测出舌头不同部位的敏感程度有一点点差别；1942 年，哈佛的一位心理学家把他的数据重新画成了图；再后来，别人把“略有差别”读成了“各管一种”。\n\n1974 年就有人用实验证实：舌头上有味蕾的地方，酸甜苦咸都尝得出来。\n\n可这张图太好记了，到现在还到处能见到。","hint":"先问他见没见过这张图。然后承认：这个我信了几十年。饭桌上有糖有盐，就让他拿舌头两边当场验一验。","refs":[{"t":"Tongue map · Wikipedia","u":"https://en.wikipedia.org/wiki/Tongue_map","lv":"常识"}],"art":"map","tags":["人体","味觉","辟谣"]},{"id":"show-020","type":"show","sub":"动物","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","出游"],"mins":2,"title":"鲨鱼和树，谁先来到地球？","body":"一个是海里的鲨鱼，一个是陆地上的树。谁在地球上出现得更早？","options":["鲨鱼，早了几千万年","树，早了上亿年","差不多同时"],"answer":0,"explain":"鲨鱼这一家最早的化石（几片鳞）有大约 4.5 亿年了，而已知最早的树大约 3.85 亿年前才出现。鲨鱼比树早了几千万年，比恐龙早了 2 亿多年，还熬过了 5 次生物大灭绝。","hint":"各押一个，你押“树”。输了以后再问：那恐龙和鲨鱼呢？答案就在解释里，让他自己念出来。","refs":[{"t":"英国自然历史博物馆：Shark evolution timeline","u":"https://www.nhm.ac.uk/discover/shark-evolution-a-450-million-year-timeline.html","lv":"官方"},{"t":"Wattieza · Wikipedia","u":"https://en.wikipedia.org/wiki/Wattieza","lv":"常识"}],"art":"tree","tags":["动物","鲨鱼","化石"]},{"id":"show-021","type":"show","sub":"动物","format":"quiz","audience":"all","for":"kid","scenes":["救场","饭桌","出游"],"mins":2,"title":"章鱼为什么不爱游泳？","body":"章鱼会游泳，可大多数时候，它宁愿在海底慢慢爬。为什么？","options":["一游泳，它的主心脏就停工","8 条腕太重，游不快","游起来就看不清东西"],"answer":0,"explain":"章鱼有 3 颗心脏：2 颗专门把血泵过两边的鳃，第 3 颗负责送往全身。偏偏一游起来，管全身的那颗就停工，体力掉得飞快。顺便说，它的血是蓝色的：运氧气用的是含铜的蛋白，不是我们这种含铁的。","hint":"他要是知道“3 颗心脏”，这题就是送他的，让他讲。再追问一句：那它的血是什么颜色？问不倒就服气。","refs":[{"t":"Octopus · Wikipedia","u":"https://en.wikipedia.org/wiki/Octopus","lv":"常识"}],"art":"heart","tags":["动物","章鱼","海洋"]},{"id":"show-022","type":"show","sub":"动物","format":"quiz","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":2,"title":"金鱼的记忆只有 7 秒？","body":"“金鱼只有 7 秒记忆，游一圈就全忘了。”这句话流传很广。是真的吗？","options":["真的，转个身就忘","半真，大概能记 1 分钟","假的，能记好几个月"],"answer":2,"explain":"金鱼能把事情记上好几个月，还分得清不同的形状、颜色和声音。英国普利茅斯大学的人教金鱼推杠杆换吃的，后来把杠杆改成每天只在固定的一个小时里管用——金鱼很快学会了到点才去推。","hint":"各押一个再翻，你押“真的”，押错了就认。养过鱼的话问他一句：一到喂食的点，鱼是不是自己凑过来？","refs":[{"t":"Goldfish · Wikipedia","u":"https://en.wikipedia.org/wiki/Goldfish","lv":"常识"}],"art":"hourglass","tags":["动物","金鱼","记忆","辟谣"]},{"id":"show-023","type":"show","sub":"动物","format":"quiz","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":2,"title":"猫尝不出哪种味道？","body":"酸、甜、苦、咸，有一种味道猫完全尝不出来。是哪一种？","options":["酸","甜","苦","咸"],"answer":1,"explain":"尝出甜味要靠两个基因合作，其中一个在猫身上早就“坏”了，成了不工作的假基因。所以蛋糕再甜，猫也吃不出甜。老虎和猎豹的这个基因同样是坏的。","more":"这是 2005 年发表的一项基因研究。研究者认为，这和猫科动物专门吃肉的习性有关。","hint":"认识的人里有养猫的最好。说完就停，别接“所以不能喂猫吃甜食”。让他拿去考养猫的同学。","refs":[{"t":"Li 等 (2005)，PLoS Genetics：猫的甜味受体基因","u":"https://journals.plos.org/plosgenetics/article?id=10.1371/journal.pgen.0010003","lv":"实证"}],"art":"question","tags":["动物","猫","味觉"]},{"id":"show-024","type":"show","sub":"数学","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"一张纸对折几次能到月球？","body":"一张纸厚约 0.1 毫米。假设它足够大，能一直对折下去：折多少次，厚度就超过地球到月球的距离（约 38 万公里）？","options":["大约 100 万次","大约 1 万次","大约 1000 次","42 次"],"answer":3,"explain":"每折一次，厚度翻一倍。折 10 次约 10 厘米，20 次约 105 米，30 次约 107 公里，42 次约 44 万公里——过月球了。翻倍这件事，前面慢得像没动，后面快得吓人。","more":"照这个算法，折到 103 次，厚度就超过了整个可观测宇宙的直径（约 930 亿光年）。\n\n现实里当然折不了这么多次：纸越折越小、越折越厚。常听人说“一张纸最多对折 8 次”，2002 年，美国高中生布兰妮·加利文用一条约 1200 米长的卫生纸，朝同一个方向折了 12 次，还推出了“多长的纸能折几次”的公式。","hint":"手边有纸就先让他折，折到折不动（一般六七次）。再猜到月球要几次，你报个离谱的大数垫底。","refs":[{"t":"Mathematics of paper folding · Wikipedia","u":"https://en.wikipedia.org/wiki/Mathematics_of_paper_folding","lv":"常识"},{"t":"NASA Science：Moon Facts（地月平均距离）","u":"https://science.nasa.gov/moon/facts/","lv":"官方"}],"art":"moon","tags":["数学","翻倍","指数"]},{"id":"show-025","type":"show","sub":"数学","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","饭桌","出差"],"mins":3,"title":"0.999… 和 1，谁大？","body":"0.999…，小数点后面的 9 无穷无尽，永远写不完。它是比 1 小一点点，还是和 1 一样大？各押一个再翻。","reveal":{"label":"翻答案","text":"一样大。0.999… 就是 1，一丁点儿都不差。","explain":"1/3=0.333…，两边都乘以 3：左边是 1，右边是 0.999…。还不服？两个不相等的数之间，一定还能再塞进一个数。你试试在 0.999… 和 1 中间塞一个——塞不进去。"},"more":"还有一种算法：设 x=0.999…，那么 10x=9.999…。两式相减，9x=9，所以 x=1。\n\n觉得别扭很正常，很多学数学的人第一次见到也不肯信。关键在那个“…”：它不是“很多个 9”，而是“9 永远不停”。只要停下来，哪怕停在第一亿位，它就比 1 小；不停，就等于 1。","hint":"他多半站“小一点点”。你陪他站同一边，一起被答案打脸。他不服气跟你吵，这张卡就成了，别急着赢。","refs":[{"t":"0.999... · Wikipedia","u":"https://en.wikipedia.org/wiki/0.999...","lv":"常识"}],"art":"magnifier","tags":["数学","无穷","小数"]},{"id":"show-026","type":"show","sub":"数学","format":"plain","audience":"all","for":"kid","scenes":["周末","饭桌"],"mins":5,"title":"只有一个面的纸环","body":"裁一条纸带，把一头拧半圈，再把两头粘成环。拿笔沿着中间一直画，别抬笔——你会一口气画遍“里外两面”，回到起点。这个环只有一个面。","more":"它叫莫比乌斯带，1858 年由两位德国数学家各自发现。\n\n再来一个：用剪刀沿着刚才画的那条线，把环从中间剪开。动手之前先猜会变成什么。\n- 多数人猜：两个环\n- 结果：一个 2 倍长的大环，没断开\n\n还没完。再做一个新的，这次贴着离边三分之一的地方一直剪下去，会得到一大一小、套在一起的两个环。","hint":"别先说名字，也别剧透。纸带你来粘，笔交给他画。动剪刀之前两人各押一个结果，你押“两个环”。","refs":[{"t":"Möbius strip · Wikipedia","u":"https://en.wikipedia.org/wiki/M%C3%B6bius_strip","lv":"常识"}],"art":"paper-plane","tags":["数学","莫比乌斯带","动手","纸"]},{"id":"show-027","type":"show","sub":"数学","format":"quiz","audience":"all","for":"kid","scenes":["救场","饭桌","出游"],"mins":3,"title":"一副牌有多少种排法？","body":"一副扑克去掉大小王，52 张。把它们随便排成一摞，一共能有多少种不同的顺序？","options":["大约 1 万种","大约 1 亿种","大约 1 亿亿种","8 后面跟着 67 个 0"],"answer":3,"explain":"第一张有 52 种可能，第二张 51 种……全乘起来，大约是 8 后面 67 个 0。就算全世界 80 亿人从宇宙诞生那天起每秒洗一次牌，到今天也连它的零头都没洗完。所以你认真洗出来的每一副牌，几乎可以肯定是有史以来头一回出现的顺序。","more":"这个数写出来是 52×51×50×…×2×1，数学里记作 52!，念“52 的阶乘”。它比地球上所有原子的个数（大约 1 后面 50 个 0）还多得多。\n\n前提是洗得够乱。数学家算过，像样的交错洗牌大约要洗 7 次，牌才算真正乱了；只洗两三下，离“随机”还差得远。","hint":"手边有牌，就让他洗一把，然后郑重宣布：这个顺序，人类历史上头一回。他问凭什么，再一起看解释。","refs":[{"t":"Shuffling · Wikipedia","u":"https://en.wikipedia.org/wiki/Shuffling","lv":"常识"}],"art":"cards","tags":["数学","扑克","阶乘","概率"]},{"id":"show-028","type":"show","sub":"英语","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","出差"],"mins":2,"title":"这句英语藏着什么秘密？","body":"**The quick brown fox jumps over the lazy dog.**\n试键盘、看字体的时候常能见到这句话。它到底特别在哪儿？","options":["26 个字母全都用上了","正着念倒着念都一样","每个单词的字母数都不同"],"answer":0,"explain":"这种句子叫 pangram（全字母句）。这一句至少从 1885 年就有了，一共 35 个字母，修打字机和电传机的人都拿它来测试每个键是不是好的。还有更短的：Sphinx of black quartz, judge my vow. 只用了 29 个字母。","more":"它最早被印出来的时候，开头是 A 不是 The：A quick brown fox jumps over the lazy dog. 这样只有 33 个字母。\n\n再给一句当靶子：The five boxing wizards jump quickly. 31 个字母。","hint":"让他自己从 a 到 z 核一遍，别帮忙。核完向他下战书：编一句更短的。他编得再怪也算数。","refs":[{"t":"The quick brown fox jumps over the lazy dog · Wikipedia","u":"https://en.wikipedia.org/wiki/The_quick_brown_fox_jumps_over_the_lazy_dog","lv":"常识"}],"art":"abc","tags":["英语","字母","pangram"]},{"id":"show-029","type":"show","sub":"英语","format":"reveal","audience":"all","for":"kid","scenes":["救场","车上","出差"],"mins":3,"title":"把这句英语倒着念","body":"**Was it a car or a cat I saw?**\n别管空格和标点，从最后一个字母开始，一个一个往回拼。拼完告诉我发生了什么。","reveal":{"label":"看答案","text":"倒过来还是同一句。这种正着倒着都一样的词和句子，叫回文（palindrome）。","explain":"单词里也有：level、noon、kayak、racecar。句子还有 Never odd or even 和 Madam, I'm Adam。中文一样能玩：上海自来水来自海上。"},"more":"palindrome 这个词来自希腊语，大意是“又跑回来”。\n\n日期也能回文：2021 年 12 月 2 日写成 20211202。下一个这样的日子是 2030 年 3 月 2 日——20300302。","hint":"让他自己倒着拼，别替他念。拼完接着比中文：从“上海自来水来自海上”开始，一人一句，谁先卡住谁输。","refs":[{"t":"Palindrome · Wikipedia","u":"https://en.wikipedia.org/wiki/Palindrome","lv":"常识"}],"art":"book","tags":["英语","回文","palindrome"]},{"id":"show-030","type":"show","sub":"英语","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","出游","出差"],"mins":3,"title":"英语绕口令：谁先打结","body":"下面 3 句，谁能又快又清楚地连说 5 遍，谁赢：\n**Toy boat**\n**Red lorry, yellow lorry**\n**She sells seashells by the seashore**","more":"3 句都是流传很久的传统绕口令，难法各不相同：\n- Toy boat：说快了会变成 toy boyt\n- Red lorry, yellow lorry：r 和 l 挨得太近，舌头来不及换位置\n- She sells seashells：s 和 sh 轮流上\n\n最后一句至少 1850 年就被印出来，当作练发音的材料。\n\n还想加码：Peter Piper picked a peck of pickled peppers.","hint":"你先来，而且要真的说砸。让他当裁判兼教练。不纠正他的发音，一个音都别纠——这局他是懂行的那个。","refs":[{"t":"Tongue twister · Wikipedia","u":"https://en.wikipedia.org/wiki/Tongue_twister","lv":"常识"}],"art":"chat","tags":["英语","绕口令","小游戏"]},{"id":"show-031","type":"show","sub":"英语","format":"quiz","audience":"all","for":"kid","scenes":["饭桌","救场","车上"],"mins":2,"title":"tea 是哪里的方言？","body":"英语的 tea，听着既不像普通话的 chá，也不像粤语的 cha。它其实是照着中国某个地方的方言念的。是哪儿？","options":["四川话","上海话","福建闽南话"],"answer":2,"explain":"闽南话里“茶”念 tê。17 世纪，荷兰商人从讲闽南话的人那里买茶，把这个读音一起带回了欧洲：英语 tea、法语 thé、德语 Tee 都是它。走陆路传出去的茶，叫法都像 chá：俄语、土耳其语、印地语里都是 chai。","more":"所以全世界对茶的叫法，绝大多数不是像 tea，就是像 cha，源头都是中文。葡萄牙语有点特别：他们是坐船来的，却是在澳门跟讲粤语的人学的，所以叫 chá。\n\n英语借走的中文词还有 kowtow（叩头）、tofu（豆腐，日语先借走，英语再从日语借）、kung fu（功夫）。《牛津英语词典》里现在还查得到 add oil——就是“加油”，标的是香港英语。\n\n反过来，沙发、巧克力、吉他、坦克，都是中文从英语借的。","hint":"家里有人会闽南话或潮汕话，就请他念一声“茶”。然后让他用 tea 和 chai 考你别国怎么说，猜错就认。","refs":[{"t":"Etymology of tea · Wikipedia","u":"https://en.wikipedia.org/wiki/Etymology_of_tea","lv":"常识"},{"t":"Add oil · Wikipedia","u":"https://en.wikipedia.org/wiki/Add_oil","lv":"常识"}],"art":"cup","tags":["英语","外来词","茶"]},{"id":"show-032","type":"show","sub":"发明","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":2,"title":"“蓝牙”这名字哪来的？","body":"耳机、音箱、手柄都靠蓝牙连。可它跟“蓝色”和“牙”到底有什么关系？","options":["1000 年前一位国王的外号","两位发明人的姓：Blue 和 Tooth","最早的芯片是蓝色锯齿形"],"answer":0,"explain":"10 世纪的丹麦国王哈拉尔，外号就叫“蓝牙”——据说他有一颗坏死的牙，颜色发蓝。他把丹麦和挪威统一到了一起。1996 年，几家公司想统一短距离无线的标准，一位工程师就借这个名字当临时代号，结果再也没换掉。","more":"蓝牙的图标也是他：把他名字的两个首字母 H 和 B 写成古代北欧的卢恩字母，再叠到一起，就是耳机盒上那个符号。\n\n本来打算正式发布时改叫 PAN 或 RadioWire。结果 PAN 在网上一搜，重名太多；RadioWire 来不及查完商标——只剩“蓝牙”能用。","hint":"趁他戴着蓝牙耳机时问。让他先猜，再让他把手机上的蓝牙图标找出来，一起看 H 和 B 藏在哪儿。","refs":[{"t":"Bluetooth SIG：Origin of the Bluetooth name","u":"https://www.bluetooth.com/about-us/bluetooth-origin/","lv":"官方"}],"art":"music","tags":["发明","科技","蓝牙","名字"]},{"id":"show-033","type":"show","sub":"发明","format":"quiz","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":2,"title":"橡皮发明前，用什么擦字？","body":"铅笔比橡皮出现得早。在橡皮被发明出来以前，铅笔字写错了，人们拿什么擦？","options":["一小块湿布","一块软木塞","去了皮的软面包"],"answer":2,"explain":"把软面包捏成小团，就是当年的“橡皮”。1770 年，英国人爱德华·奈恩说，他本想伸手拿面包屑，却错抓了一小块橡胶，一擦，比面包好用多了。橡皮就是这么来的。","more":"英语里橡胶叫 rubber，本意就是“用来擦（rub）的东西”。这种材料是先当上了橡皮，才得了这个名字。\n\n把橡皮装到铅笔屁股上，要等到 1858 年。","hint":"手边有软面包和铅笔时最好：先别说话，捏一小团在铅笔印上擦擦看，再问他猜到了什么。擦不干净也照实说。","refs":[{"t":"Eraser · Wikipedia","u":"https://en.wikipedia.org/wiki/Eraser","lv":"常识"}],"art":"pencil","tags":["发明","橡皮","文具"]},{"id":"show-034","type":"show","sub":"发明","format":"quiz","audience":"all","for":"kid","scenes":["救场","车上","周末"],"mins":2,"title":"泡泡纸本来想做成什么？","body":"就是那种一捏就“啪”一声、让人停不下来的泡泡纸。它被发明出来的时候，原本是想拿来干什么的？","options":["贴在墙上的立体墙纸","浴室里的防滑垫","救生衣的夹层"],"answer":0,"explain":"1957 年，两位发明家想做一种带立体花纹的塑料墙纸，结果根本卖不出去。后来他们发现，这东西拿来包东西特别好；1960 年前后，它被用来包装一款新出厂的计算机，从此改了行。","hint":"手边有泡泡纸最好：一人半张，边捏边猜。他猜什么都先说“有可能”，最后再翻答案。","refs":[{"t":"Bubble wrap · Wikipedia","u":"https://en.wikipedia.org/wiki/Bubble_wrap","lv":"常识"}],"art":"bulb","tags":["发明","泡泡纸","意外"]},{"id":"show-035","type":"show","sub":"发明","format":"quiz","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":2,"title":"没有开罐器，怎么开罐头？","body":"罐头发明以后的头 40 多年里，世界上还没有开罐器。那时候的人是怎么把它打开的？","options":["找块大石头把它砸开","用凿子和锤子凿开","拧开顶上的小盖子"],"answer":1,"explain":"铁皮罐头 1810 年就拿到了专利，专门的开罐器却要到 1855 年才出现。这 40 多年里，罐头上的说明是：用凿子和锤子，沿着顶上的边凿一圈。那时候的罐头皮厚得很，有的比里面装的东西还重。","more":"最早的开罐器差不多就是一把改了形状的刀。带轮子、能沿着罐边转一圈的那种，1870 年才出现；现在常见的双轮款，是 1925 年的事。","hint":"先用手挡住选项，让他自己想招。“用牙咬”“往地上摔”都记一分，再看选项。揭晓后说完就停。","refs":[{"t":"Can opener · Wikipedia","u":"https://en.wikipedia.org/wiki/Can_opener","lv":"常识"}],"art":"pan","tags":["发明","罐头","厨房"]},{"id":"show-101","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","车上","睡前"],"mins":5,"title":"换，还是不换？","body":"3 扇门，一扇后面藏着篮球。你选了一扇，主持人打开另一扇——空的。现在给你一次机会改主意：换不换？","more":"这道题叫“三门问题”。1990 年美国一份杂志的专栏登了它，大约 1 万名读者写信来，绝大多数说专栏的答案错了，其中将近 1000 人是博士。\n\n想不通的时候，把 3 扇门换成 100 扇：你随手指一扇，主持人把剩下 99 扇里的 98 扇空门全打开，只留一扇。还觉得“换不换都一样”吗？\n\n关键只有一个：主持人**知道**球在哪，而且绝不会把球开出来。\n\n不服气就让它自动玩 1000 次，看两根柱子各自停在哪儿。","widget":"monty","params":{"doors":3},"cta":"选一扇门","hint":"先让他选，你别出声。他说“一半一半”也别纠正，让他连玩 10 局自己数。你也押一个，押错了就认。","refs":[{"t":"Monty Hall problem · Wikipedia","u":"https://en.wikipedia.org/wiki/Monty_Hall_problem","lv":"经典"}],"art":"door","tags":["概率","三门问题","蒙提霍尔","篮球"]},{"id":"show-102","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前"],"mins":3,"title":"100 扇门，你换吗？","body":"100 扇门，只有一扇后面有篮球。你随手指了一扇，主持人把另外 98 扇空门全打开，只留下一扇没开。换不换？","more":"这是“三门问题”的放大版。门只有 3 扇的时候，很多人觉得换不换都是一半一半；门变成 100 扇，感觉就不一样了。\n\n你随手一指，指中的机会是 1%。剩下那 99% 去哪儿了？主持人知道球在哪，他小心地绕开了一扇门——\n\n玩几局，再回头想想 3 扇门的时候，是不是同一回事。","widget":"monty","params":{"doors":100},"cta":"指一扇门","hint":"他玩过 3 扇门还不服气，就递这张。别讲解，只问一句：“主持人为什么偏偏留那一扇？”","refs":[{"t":"Monty Hall problem · Wikipedia","u":"https://en.wikipedia.org/wiki/Monty_Hall_problem","lv":"经典"}],"art":"key","tags":["概率","三门问题","一百扇门"]},{"id":"show-103","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":5,"title":"随机乱点，能点出一幅画","body":"3 个顶点，一个点。每次随机挑一个顶点，朝它跳一半，在落脚的地方点个点。这样乱跳几千次，纸上会是什么？先猜。","more":"这个玩法叫“混沌游戏”。骰子完全公平，每一步都是瞎蒙，可点出来的图案每次都一样。\n\n随机的只是先后顺序；“每次跳一半”这条规则，决定了哪些地方永远跳不到。\n\n玩完三角形，底下还能换成方形、五边形、六边形——规则只改一点点，画出来的完全是另一幅。\n\n想用纸笔验证：画 3 个点，掷骰子（1、2 去 A，3、4 去 B，5、6 去 C），拿尺子量一半。点上一两百个，就能看出眉目。","widget":"chaosgame","params":{"variant":"tri"},"cta":"开始乱点","hint":"让他先猜会画出什么，你也猜一个。前几步用「一步」慢慢点，别急着按「自动」。等他问为什么，再点「为什么」。","refs":[{"t":"Chaos game · Wikipedia","u":"https://en.wikipedia.org/wiki/Chaos_game","lv":"经典"}],"art":"dice","tags":["分形","谢尔宾斯基三角形","随机","混沌"]},{"id":"show-104","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":5,"title":"跳到 0.618，会怎样","body":"5 个顶点，一个乱跳的点。这回不跳一半，每次跳到 0.618 的位置——就是传说中的黄金分割。几千步之后，纸上会长出什么？","more":"还是“混沌游戏”：随机挑一个顶点，朝它跳过去一截，点个点。只改了两处——顶点变成 5 个，每次跳到全程的 0.618。\n\n0.618 不是随便挑的。跳得近一点，图案会糊成一团；跳得远一点，会碎成互不相连的几撮；正好这个数，5 个小图案肩并肩挨着。\n\n黄金分割本来就住在五边形里：正五边形的对角线除以边长，就是 1.618……，而 1 除以它，又回到 0.618……","widget":"chaosgame","params":{"variant":"penta"},"cta":"开始乱点","hint":"先玩过三角形那张再来这张更好。让他猜“这回还会不会有图案”，然后把手机交给他按。","refs":[{"t":"Chaos game · Wikipedia","u":"https://en.wikipedia.org/wiki/Chaos_game","lv":"经典"},{"t":"Golden ratio · Wikipedia","u":"https://en.wikipedia.org/wiki/Golden_ratio","lv":"常识"}],"art":"star","tags":["分形","黄金分割","五边形","混沌"]},{"id":"show-105","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["饭桌","睡前","周末"],"mins":4,"title":"乱弹的球，为什么堆成山","body":"小球从顶上掉下来，每碰一颗钉子，就随机向左或向右。几百颗球之后，底下的槽里会堆出什么形状？","more":"这块板叫高尔顿板，是 100 多年前英国科学家高尔顿做出来的。\n\n每颗球走哪条路全凭运气，可球多了以后，堆出来的形状几乎每次都一样。\n\n原因在“路的条数”：想落到最边上，得每一次都拐向同一边，只有一条路；想落到正中间，左左右右怎么排都行，有 200 多条路。\n\n把「向右的概率」调到 0.7 试试——先猜山会怎么变。","widget":"galton","params":{"rows":10},"cta":"放球","hint":"别解释，先问：“你猜哪个槽最满？”等球堆起来，再让他把概率滑到 0.7，滑之前先猜山往哪边跑。","refs":[{"t":"Galton board · Wikipedia","u":"https://en.wikipedia.org/wiki/Galton_board","lv":"经典"}],"art":"mountain","tags":["概率","二项分布","钟形曲线","高尔顿板"]},{"id":"show-106","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":5,"title":"扔飞镖，能算出圆周率？","body":"一个方框，里面套一个圆。闭着眼往里扔飞镖，只数两个数：圆里几个，一共几个。不用尺子，不用公式，就能把 π 逼出来。","more":"把方框的边长当成 2，圆的半径就是 1：方框面积是 4，圆的面积是 π。\n\n乱扔的飞镖落在哪儿都一样可能，所以落在圆里的比例大约是 π÷4。把这个比例乘以 4，就是 π。\n\n这招叫“蒙特卡洛方法”，名字来自一座以赌场出名的小城——因为它靠的就是大量的随机。科学家用它来算那些列不出公式的东西。\n\n缺点是慢：想多准一位小数，得多扔 100 倍的飞镖。","widget":"montepi","params":{},"cta":"扔飞镖","hint":"先让他手动扔二三十个，自己按计算器算一遍“圆里÷全部×4”，再开「自动」。看数字在 3.1 附近晃，别急着报答案。","refs":[{"t":"Monte Carlo method · Wikipedia","u":"https://en.wikipedia.org/wiki/Monte_Carlo_method","lv":"经典"}],"art":"target","tags":["圆周率","随机","蒙特卡洛","面积"]},{"id":"show-107","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["睡前","周末","饭桌"],"mins":5,"title":"三条规则，一个会动的世界","body":"每个格子只看身边 8 个邻居：正好 3 个活的就出生，有 2 或 3 个就活着，否则死掉。就这么点规矩——看它造出了什么。","more":"这叫“生命游戏”，数学家康威 1970 年想出来的。没有玩家，也没有输赢，摆好开局就只能看。\n\n你现在看到的是一把“滑翔机枪”：每隔 30 代，它就吐出一架会自己往前爬的小飞机。没人设计过“飞”这个动作，它是从那三条规则里自己冒出来的。\n\n点「图案」换别的：会呼吸的脉冲星、横着飞的飞船，还有只用 5 个格子、在大棋盘上能折腾 1000 多代的“R 五格”。也可以直接用手指画。","widget":"life","params":{"preset":"gun"},"cta":"看它开火","hint":"不用先讲规则，让他看枪“开火”。他要是问“这谁设计的”，就说“没人，规则自己长出来的”，然后把手机给他画。","refs":[{"t":"Conway's Game of Life · Wikipedia","u":"https://en.wikipedia.org/wiki/Conway%27s_Game_of_Life","lv":"经典"}],"art":"seedling","tags":["生命游戏","康威","滑翔机","元胞自动机"]},{"id":"show-108","type":"show","sub":"数学","format":"widget","audience":"all","for":"kid","scenes":["饭桌","周末","睡前"],"mins":3,"title":"同一堆柱子，谁先排完","body":"40 根高矮不一的柱子，两种排队的办法同时开工：一个老老实实挨个比，一个每次先分成两堆。差距会有多大？","more":"两边干的是同一件事：把柱子从矮到高排好。每比较一次两根柱子算一步。\n\n上面那种叫冒泡排序：相邻两根比一比，高的往后挪，一趟一趟来。下面那种叫快速排序：挑一根当“裁判”，比它矮的站左边、高的站右边，然后两边各自再来一遍。\n\n柱子越多，差得越离谱。手机里的通讯录、游戏里的排行榜，背后都在排序——用的当然不是慢的那种。\n\n点算法的名字，可以换别的办法再比。","widget":"sorting","params":{"pair":["bubble","quick"],"n":40},"cta":"开跑","hint":"开跑前让他先押谁赢、差几倍。看完别总结，问他：“一副打乱的扑克牌，你平时怎么理？”","refs":[{"t":"Sorting algorithm · Wikipedia","u":"https://en.wikipedia.org/wiki/Sorting_algorithm","lv":"常识"}],"art":"stopwatch","tags":["算法","排序","冒泡排序","快速排序"]},{"id":"show-201","type":"show","sub":"物理","format":"widget","audience":"all","for":"kid","scenes":["救场","睡前","车上"],"mins":3,"title":"这只摆不按套路出牌","body":"两根杆连在一起，松手。盯着那条线看：它会不会重复自己？","more":"只有一根杆的摆，来回的路线每次都一样。接上第二根，两根杆互相拉扯，甩起来就看着毫无规律，几乎不会走回同一条路线。\n\n奇怪的是，这里没有任何随机：每一步都严格照着同一条物理规则走。规则完全确定，结果却没法长期预测，这种现象叫**混沌**。\n\n拖动小球可以换个起点。起点低，它摆得规规矩矩；抬得越高，越没有规律。","widget":"pendulum","params":{},"cta":"甩一下","hint":"先别解释“混沌”。让他摆一个最刁钻的姿势，你们赌它 10 秒后甩在左边还是右边。","refs":[{"t":"Double pendulum · Wikipedia","u":"https://en.wikipedia.org/wiki/Double_pendulum","lv":"常识"}],"art":"atom","tags":["物理","混沌","双摆"]},{"id":"show-202","type":"show","sub":"物理","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前"],"mins":3,"title":"只差 0.057°，能同步几秒？","body":"两只一模一样的双摆，同时松手，起点只差 0.057°，肉眼看不出来。先猜：它们能一起走多久？","more":"两只摆的规则完全相同，松手时上面那根杆只差 0.001 弧度，也就是 0.057°。\n\n这点差别不会老实待着，它每过一小会儿就翻一倍。下面的曲线画的是两只摆的角度差，纵轴每一格是 10 倍：先是一条往上爬的斜线，爬到头，两只摆就各走各的了。\n\n气象学家洛伦茨在算天气时撞见过同样的事，“蝴蝶效应”说的就是它。天气预报只能准几天，主要就是因为这个：一开始总有一点量不准。","widget":"pendulum","params":{"twins":true},"cta":"同时松手","hint":"先各报一个秒数，谁离得近谁赢。然后让他拖个新起点再来一次：每次分开的时间都不一样。","refs":[{"t":"Butterfly effect · Wikipedia","u":"https://en.wikipedia.org/wiki/Butterfly_effect","lv":"常识"},{"t":"Double pendulum · Wikipedia","u":"https://en.wikipedia.org/wiki/Double_pendulum","lv":"常识"}],"art":"magnet","tags":["物理","混沌","蝴蝶效应"]},{"id":"show-203","type":"show","sub":"物理","format":"widget","audience":"all","for":"kid","scenes":["救场","睡前","饭桌"],"mins":2,"title":"15 只摆，自己会排队","body":"一起松手，它们先扭成一条蛇，再散开、分队。等满 60 秒，看会发生什么。","more":"一只摆来回一次要多久，只看绳子多长，跟球多重没关系。\n\n这 15 只摆的绳长是算好的：60 秒里，最长的那只正好摆 51 次，旁边的 52 次，一只比一只多一次，最短的 65 次。\n\n一起松手后，快的一点点领先，队伍就拉成一条蛇。30 秒时，摆了双数次的回到原位，单数次的正好在对面，于是分成两队。60 秒时每只都摆了整数次，同时回到起点。","widget":"wavependulum","params":{},"cta":"松手","hint":"别剧透 60 秒时会怎样。到 55 秒一起倒数。看完各猜一个：再多等 1 分钟，会怎样？","refs":[{"t":"Pendulum wave · Wikipedia","u":"https://en.wikipedia.org/wiki/Pendulum_wave","lv":"常识"},{"t":"哈佛大学自然科学演示实验：Pendulum Waves","lv":"经典"}],"art":"hourglass","tags":["物理","单摆","周期"]},{"id":"show-204","type":"show","sub":"篮球","format":"widget","audience":"all","for":"kid","scenes":["球场","周末","饭桌"],"mins":5,"title":"平着投，还是高高地抛？","body":"同一个罚球，换个出手角度，“力气大一点小一点都能进”的余地能差好几倍。拖一拖，找出最稳的角度。","more":"球是斜着飞向篮筐的，所以篮圈在它“眼里”是一个被压扁的椭圆：\n\n**看起来的宽度 = 篮圈直径 × sin(入筐角)**\n\n篮圈内径 45 厘米，球直径约 24.6 厘米。垂直掉下去，篮筐有 45 厘米宽；入筐角 45° 时只剩 31.8 厘米；小于 33° 时这条缝比球还窄，不蹭筐不可能进。\n\n弧线高一点，缝就宽一点，可是也更费力。这个模型只算重力，没有空气阻力和旋转，它给的“最稳角度”只是模型里的答案。","widget":"hoopshot","params":{"mode":"explore","spot":"ft"},"cta":"找角度","hint":"先让他站起来比划自己平时的出手角度，再让他拖滑块。结论由他讲给你听，你只负责“哦——”。","refs":[{"t":"FIBA 篮球规则·器材（篮筐、篮球与球场尺寸）","lv":"官方"},{"t":"Basketball court · Wikipedia","u":"https://en.wikipedia.org/wiki/Basketball_court","lv":"常识"}],"art":"hoop","tags":["篮球","物理","抛物线","入筐角"]},{"id":"show-205","type":"show","sub":"人体","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","睡前"],"mins":2,"title":"盯住这个蓝球 20 秒","body":"眼睛别动，盯住球心的小黑点。倒计时结束的那一下，看看白底上多了什么。","more":"眼睛里有 3 种管颜色的感光细胞。盯着蓝色看久了，对蓝色起反应的那些细胞“累了”，反应变弱。\n\n这时再看白色（白光里各种颜色都有），蓝色的信号偏弱，剩下的颜色占了上风，你看到的就是它的补色。过几秒细胞缓过来，残像就散了。","widget":"illusion","params":{"kind":"afterimage"},"cta":"开始盯","hint":"你也一起盯，结束时各自说看到了什么颜色，别抢答。他说没看到，就让他别眨眼再来一次。","refs":[{"t":"Afterimage · Wikipedia","u":"https://en.wikipedia.org/wiki/Afterimage","lv":"常识"}],"art":"camera","tags":["错觉","视觉","补色","残像"]},{"id":"show-206","type":"show","sub":"人体","format":"widget","audience":"all","for":"kid","scenes":["救场","饭桌","周末"],"mins":3,"title":"你的眼睛里有个洞","body":"闭上一只眼，盯住十字，把手机慢慢拉近。旁边那个圆点会在某个距离突然不见。","more":"眼球后面有一小块地方，是视神经穿出去的出口，那里没有感光细胞。圆点的像正好落在那儿时，你就看不见它。\n\n平时没感觉，是因为两只眼睛的盲点不在同一个位置，互相补上了。只用一只眼时，大脑会用周围的颜色和图案把这个洞“补”上，所以你看到的不是黑洞，而是一片连续的背景。","widget":"illusion","params":{"kind":"blindspot"},"cta":"找盲点","hint":"你先来，找到了别说距离，把手机递给他自己找。再点「换成一条线」，看大脑怎么把缺口补上。","refs":[{"t":"Blind spot (vision) · Wikipedia","u":"https://en.wikipedia.org/wiki/Blind_spot_(vision)","lv":"常识"}],"art":"magnifier","tags":["错觉","视觉","盲点"]},{"id":"show-207","type":"show","sub":"天上地下","format":"widget","audience":"all","for":"kid","scenes":["球场","周末","出游","车上"],"mins":5,"title":"地球缩成篮球，月亮在哪？","body":"先猜：月亮有多大，离这个篮球几米？太阳呢？猜完再一站一站走过去。","more":"所有数字都用同一个比例：真实尺寸除以 5185 万。\n\n- 月球：一个网球那么大，离篮球 7.4 米\n- 太阳：直径 27 米，差不多一个篮球场那么长，在 2.9 千米外\n- 离太阳最近的恒星比邻星：在 77.5 万千米外，比真的月亮还远一倍\n\n按这个比例，光每秒只走 5.8 米，和骑自行车差不多。它从太阳“骑”到地球要 8 分 19 秒。\n\n课本上的太阳系图把距离缩得比大小狠得多，不然一页纸画不下。","widget":"scale","params":{"ball":"basketball"},"cta":"出发","hint":"在球场边最好：先各猜一个，用步子把月亮“放”到自己猜的地方，再点开看谁近。太阳那一站的答案让他念。","refs":[{"t":"NASA Planetary Fact Sheet","u":"https://nssdc.gsfc.nasa.gov/planetary/factsheet/","lv":"官方"},{"t":"Proxima Centauri · Wikipedia","u":"https://en.wikipedia.org/wiki/Proxima_Centauri","lv":"常识"}],"art":"planet","tags":["天文","太阳系","比例","篮球"]},{"id":"talk-001","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"隐身还是会飞？都带坑","body":"只能挑一个，副作用甩不掉。","either":{"a":"隐身，但得憋着气才管用","b":"会飞，但只有走路那么快","ask":"拿到手第一件事干什么？最想躲开谁？"},"hint":"你先选，说一件你想拿它干的没出息的事，比如从一个无聊的会上隐身溜走。他说要去捣蛋，笑就行，别纠正。","art":"star","tags":["超能力"]},{"id":"talk-002","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":3,"title":"一个月只吃一种颜色","body":"接下来 30 天，进嘴的东西只能是一个颜色。调料不算。","either":{"a":"只吃白色的","b":"只吃黄色的","ask":"各报 5 样能吃的，谁先卡壳谁输。炸鸡算黄的吗？"},"hint":"别提营养。跟他较真“冰淇淋算不算白的”“可乐算什么色”，吵得越细越好。谁的菜单更惨，谁认输。","art":"pizza","tags":["吃"]},{"id":"talk-003","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"队友选哪一拨","body":"接下来一个月打游戏，只能跟这一拨人组队。","either":{"a":"全是大神，但全程没人说话","b":"全是菜鸟，但笑到肚子疼","ask":"你遇到过最神和最坑的队友，各讲一个。"},"hint":"他讲坑队友的时候只管笑。别接“所以少玩点”，这句一出口这张卡就废了。你也讲一个工作里的坑队友，别点名。","art":"highfive","tags":["游戏"]},{"id":"talk-004","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌","出游"],"mins":3,"title":"跑遍世界，还是住下来","body":"都免费，都不用上班上学。只能二选一。","either":{"a":"环游世界，每个地方只待一天","b":"只去一个地方，住满一整年","ask":"只去一个地方的话是哪儿？到了第一顿吃什么？"},"hint":"别顺势科普地理，也别当场许愿“放假就带你去”，除非你真打算兑现。你也选一个，说一个你一直想去还没去成的地方。","art":"globe","tags":["旅行"]},{"id":"talk-005","type":"talk","sub":"篮球","format":"either","audience":"all","for":"kid","scenes":["救场","球场","车上"],"mins":3,"title":"两样神技，都带坑","body":"只能挑一个，一辈子换不了。","either":{"a":"离筐一步以内，百发百中","b":"中场出手，10 个进 3 个","ask":"带着它你打什么位置？对手会怎么防你？"},"hint":"他选哪个你就选另一个，当场吵谁更值，别拿命中率算账压他。场上有球就各投 5 个中场，看离“10 进 3”差多远。你多半一个不进，认了。","art":"hoop","tags":["篮球","超能力"]},{"id":"talk-006","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":3,"title":"宠物突然开口说话","body":"明早起床，家里多了一只会说人话的。只能留一只。","either":{"a":"一只话多、还爱告状的狗","b":"一只啥都懂、但瞧不起你的猫","ask":"给它起个名。留下的那只睡谁屋、归谁管？"},"hint":"他学猫狗的口气损你，多半带点真心话，笑着收下，别解释。你也学一句，损的是你自己。","art":"chat","tags":["动物"]},{"id":"talk-007","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"恭喜，你中奖了","body":"奖品只能挑一样，不能折现，不能转卖。","either":{"a":"任选一场比赛，坐第一排，就一次","b":"楼下小卖部，终身免费","ask":"选比赛：看哪场、带谁？选小卖部：第一天先拿啥？"},"hint":"他选小卖部也别说“没追求”，认真帮他算一年能吃回多少。你选哪个照实说；选了比赛，就说想带他去看哪一场。","art":"dice","tags":["中奖"]},{"id":"talk-008","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"外星飞船停在楼下","body":"它们很客气，就问你一句：走不走？","either":{"a":"跟它们走，10 年后送你回来","b":"不走，但以后说了没人信","ask":"走的话带哪 3 样？留下的话怎么让人信你？"},"hint":"他说走，别问“那爸妈怎么办”，帮他挑那 3 样行李。你也照实选；选留下，就说说打算怎么跟人吹这件事。","art":"rocket","tags":["外星人"]},{"id":"talk-009","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上"],"mins":3,"title":"哪个更想钻地缝","body":"两件事必须摊上一件，周围全是人。","either":{"a":"放了一个巨响的屁","b":"热情回了个招呼，人家喊的是你身后的人","ask":"接下来 3 秒你怎么救场？当场演一下。"},"hint":"你先演，演得越用力越好。这类事你肯定真干过，把真事讲出来。他演的时候只管笑，不打分。","art":"door","tags":["尴尬"]},{"id":"talk-010","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"出门自带特效一年","body":"甩不掉，关不了，所有人都看得见、听得到。","either":{"a":"走到哪都响着你的出场音乐","b":"说的每句话都在头顶飘字幕","ask":"你的出场音乐是哪首？顺便给我也挑一首。"},"hint":"他给你挑的出场音乐再损也收下，当场哼两句。别问他为什么喜欢那首，记下歌名，下次车上放。","art":"music","tags":["音乐"]},{"id":"talk-011","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","睡前"],"mins":3,"title":"送你一间秘密基地","body":"水电网都通，位置二选一，选了不能搬。","either":{"a":"30 米高的大树顶上","b":"海底，四面都是玻璃","ask":"半夜窗外会看到什么？第一个请谁来做客？"},"hint":"别操心安全（“掉下来怎么办”）。问他屋里先放哪 3 样东西。你也选一间，说说你想在里面干什么，哪怕是睡一整天。","art":"tree","tags":["秘密基地"]},{"id":"talk-012","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"你打得过哪一边","body":"躲不掉，必须挑一边当对手。","either":{"a":"100 匹鸭子那么大的马","b":"一只马那么大的鸭子","ask":"你的战术是什么？可以从家里带一样东西当装备。"},"hint":"当成战术会议来开：地形、装备、先对付哪只。他的方案有漏洞，就让对面“反击”一下，别拿大人的常识扫兴。","art":"target","tags":["动物"]},{"id":"talk-013","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"地堡里住一年","body":"外面暂时出不去（放心，一年后啥事没有）。两间地堡挑一间。","either":{"a":"好吃的管够，但没有任何娱乐","b":"游戏电影管够，但只有压缩饼干","ask":"第 100 天你在干嘛？最先想念的是什么？"},"hint":"别借机感慨“看来游戏也会腻”。就聊地堡：带谁进去、床位怎么分。你选哪间照实说，选吃的就认。","art":"battery","tags":["世界末日"]},{"id":"talk-014","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"接下来 3 分钟这么说话","body":"选一种，立刻生效。谁先忘了规矩，谁输。","either":{"a":"每句话都得唱出来","b":"每句话结尾加一声“喵”","ask":"现在开始计时。输的学一段对方指定的动物叫。"},"hint":"你得真唱、真喵，有外人在场也照做。你先破功最好，认罚要认得痛快。","art":"stopwatch","tags":["小游戏"]},{"id":"talk-015","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":3,"title":"家里来了个机器人","body":"它只会一样本事，一辈子升不了级。","either":{"a":"做饭天下第一","b":"陪你玩什么都刚好比你强一点","ask":"给它起个名字。它上岗第一天会闯什么祸？"},"hint":"你多半想选做饭的那个，照实选，让他笑你。别把话拐到“那你多帮家里干点活”。","art":"brain","tags":["机器人"]},{"id":"talk-016","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","饭桌","周末"],"mins":4,"title":"哪个你能拿世界冠军","body":"两个奇怪的世界大赛，你觉得自己哪个更有戏？","either":{"a":"憋笑大赛：先笑的人输","b":"发呆大赛：先动的人输","ask":"口说无凭，现在比一局。我先出招。"},"hint":"比憋笑时你来出丑：鬼脸、怪声、学你老板讲话。输给他，再要求来一局。3 局就收，别玩到他烦。","art":"trophy","tags":["小游戏"]},{"id":"talk-017","type":"talk","sub":"二选一","format":"either","audience":"all","for":"kid","scenes":["救场","车上","睡前"],"mins":3,"title":"搬去另一个世界","body":"一去 10 年。两个世界选一个。","either":{"a":"有魔法，但没有任何电器","b":"有飞船和机器人，但没有魔法","ask":"你在那边靠什么本事吃饭？我能干点啥？"},"hint":"他在那边给你安排的工作再惨（扫飞船、喂龙）也接着。别问“那边要不要上学”。","art":"planet","tags":["魔法","科幻"]},{"id":"talk-018","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"给全世界发 7 个字","body":"所有人的手机同时亮起来，屏幕上是你写的话。只有 7 个字，只能发一次。你发什么？","more":"还想接着玩：\n- 换成只能发一个表情呢？\n- 这 7 个字只发给一个人，发给谁？\n- 100 年后的人收到，会不会看不懂？","hint":"你先掰着手指凑一句，凑不齐更好。他要是发了句搞怪的，那就是最佳答案，别问“就这？”，也别把你那句讲成人生感悟。","art":"paper-plane"},{"id":"talk-019","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"比比谁的超能力更废","body":"比如：能让任何一只袜子瞬间找到另一只。一人说一个，废得越具体越好。","more":"卡壳的时候借一个：\n- 能让泡面永远刚好 3 分钟熟\n- 能一眼看出西瓜里有几颗籽\n- 打喷嚏的时候不闭眼\n- 能跟任何一扇自动门心灵感应","hint":"你的要够废、够具体，比如“能精确知道电梯还有几秒到”。请他当裁判打分，他判你输就认。","art":"bulb","tags":["超能力"]},{"id":"talk-020","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","睡前"],"mins":4,"title":"全世界只有你醒着","body":"从早 8 点到晚 8 点，别人全睡着了，叫不醒，也不会有事。所有东西照常能用。这一天你怎么过？","hint":"先问“第一站去哪儿”，别问“会不会害怕”。你的答案越没出息越好：把明天的会全取消，去空荡荡的商场把所有的床躺一遍。","art":"moon"},{"id":"talk-021","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","周末"],"mins":4,"title":"明天这个家你说了算","body":"整整一天，我和你妈都得听你的。你上任后的前 3 条规定是什么？","hint":"再离谱也先记下来，不讨价还价。里面要是有一条其实办得到（晚饭他点菜、你洗碗），这周就真照办一次。","art":"calendar"},{"id":"talk-022","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":4,"title":"动物也能报名奥运会","body":"每个项目只收一种动物：百米、跳高、举重、游泳、篮球。你各派谁上？谁来当裁判？","hint":"别掏手机查谁跑得最快，争起来才好玩。他懂得比你多，就让他讲。篮球那一项派谁，他说了算。","art":"flag","tags":["动物"]},{"id":"talk-023","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":3,"title":"由你发明一个新节日","body":"全国放假一天。叫什么名字？这天必须干什么，绝对不许干什么？","hint":"你先说你的，比如“不回消息节”。他发明的要是在家就能过，挑个周末真过一次，规矩按他的来，一条不改。","art":"kite"},{"id":"talk-024","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":3,"title":"家里哪样东西最想骂人","body":"今晚 12 点，家里的东西都能开口说一句话。谁的怨气最大？它骂谁，骂什么？","hint":"先替你的手机骂你自己一句。轮到他的书包、球鞋开口时，听着笑就行，别顺着那句话说他。","art":"sofa"},{"id":"talk-025","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":4,"title":"把你做成游戏角色","body":"一个主动技能，一个被动技能，一个致命弱点。先设计你自己，再顺手把我的也设计了。","hint":"他给你设计的技能多半是在损你，照单全收，再追问一句“冷却时间多久”。别拿他“弱点”那一栏做文章。","art":"gamepad","tags":["游戏"]},{"id":"talk-026","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","车上","出游"],"mins":3,"title":"未来博物馆里的咱家","body":"很多年以后，展柜里摆着咱家现在的一样东西。是哪样？旁边的说明牌上会怎么写？","hint":"你先来一个：“21 世纪中年男性保温杯，出土时内有枸杞。”他挑你的哪样东西来损，都算好答案。","art":"telescope"},{"id":"talk-027","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","球场"],"mins":3,"title":"重力减半一天","body":"明天一整天，地球上所有东西都只有一半重，你也是。这一天你打算怎么用？","hint":"他多半要去扣篮。别提身高，只问“第一个扣哪种”。然后说你的：终于能做一个像样的引体向上了。","art":"atom"},{"id":"talk-028","type":"talk","sub":"如果","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"暂停键只能按 3 次","body":"按一下，全世界定住 10 秒，只有你能动。一辈子就 3 次。你留给什么时候？","hint":"你先交代一次：开会被点名、答不上来的那 10 秒。他说要用在比赛上、恶作剧上都行，别评价“浪费”。","art":"clock"},{"id":"talk-029","type":"talk","sub":"你教我","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"最近那个梗啥意思","body":"挑一个你们常说、我肯定听不懂的词。讲给我听，再告诉我：什么场合用了会很尴尬。","hint":"真没懂就说没懂，请他再讲一遍。学会了也别当着他同学的面用，除非他批准。不说“你们现在的小孩”。","art":"question","tags":["梗"]},{"id":"talk-030","type":"talk","sub":"你教我","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","周末"],"mins":4,"title":"3 句话讲明白你那个游戏","body":"就当我是刚下载的新手：这游戏在干什么，怎么算赢，高手和菜鸟差在哪儿。","hint":"别问一天玩多久、花没花钱。听完问一句内行话，比如“那你一般玩哪个角色？”他要掏手机演示，就跟着打一局，死得难看也行。","art":"gamepad","tags":["游戏"]},{"id":"talk-031","type":"talk","sub":"你教我","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","球场"],"mins":3,"title":"给我安利一个球星","body":"挑一个你觉得我该多看看的球员。给你 1 分钟：他最厉害的是哪一招，哪场比赛值得找来看？","hint":"别拿你那个年代的球星来比。听完这周真去找一段他的集锦，看完告诉他你看见了哪一招。","art":"star","tags":["篮球","球星"]},{"id":"talk-032","type":"talk","sub":"你教我","format":"plain","audience":"all","for":"kid","scenes":["车上","出游","周末"],"mins":5,"title":"这一路你来当 DJ","body":"放一首你最近循环的。放之前先说一句：这首歌该在什么时候听。我听完整首，不快进。","hint":"听完只说你听到了什么（“这段鼓挺带劲”），不说“这唱的啥”。然后轮你放一首你 13 岁时循环的，让他随便吐槽。","art":"music","tags":["音乐"]},{"id":"talk-033","type":"talk","sub":"你教我","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"教我一句课本没有的英语","body":"游戏里、解说嘴里、视频里学来的都行。告诉我什么时候用，再听我造个句，造错了你来改。","hint":"你来当那个造错句的学生，发音烂是加分项。别问他从哪儿学的、看了多久，也别说“这个考试不考吧”。","art":"abc","tags":["英语"]},{"id":"talk-034","type":"talk","sub":"你教我","format":"plain","audience":"all","for":"kid","scenes":["救场","周末"],"mins":4,"title":"我的手机哪儿最土","body":"手机给你 2 分钟，翻我的表情和常用语。鉴定一下：哪个表情在你们眼里是阴阳怪气，哪句话一看就是中年人？再给我换 3 个能用的。","hint":"真把手机递过去（先想好哪些聊天能给他看）。他说哪个土就是土，别辩解。他给换的表情，当天就在家里的群里用一次。","art":"magnifier","tags":["手机","表情"]},{"id":"talk-035","type":"talk","sub":"你教我","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":3,"title":"教我把这个笑话讲好笑","body":"我讲一个我觉得巨好笑的，你打分。然后告诉我哪儿讲砸了，你来示范一遍。","hint":"挑一个你真心觉得好笑的冷笑话，讲砸了最好。他示范的时候认真笑，别补一句“上课可别这样”。","art":"chat","tags":["笑话"]},{"id":"talk-036","type":"talk","sub":"老爸自曝","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":4,"title":"我 13 岁最丢人的一次","body":"点到这张，我就得交代：我像你这么大的时候，当着好多人的面出过的最大的一次糗。讲到最丢人的那一秒我会停住，你来猜后来怎么着。","more":"这类事一般藏在这些地方：\n- 叫错了人，还叫得特别大声\n- 裤子在最不该裂的时候裂了\n- 上台忘词，站了整整 10 秒\n- 以为没人，唱得很投入，一回头全是人\n\n听的人可以点播：“再讲一个比这更丢人的。”","hint":"讲真事，别挑那种其实在夸自己的。结尾不加“后来我明白了”。他不接自己的糗事也没关系，他笑了这张就算成。","art":"seedling","tags":["糗事"]},{"id":"talk-037","type":"talk","sub":"老爸自曝","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":3,"title":"我今天搞砸了一件事","body":"今天上班我干了件蠢事，发错群、叫错名字、讲了半天没开麦这一类的。我照实讲，你来出主意：换成你，接下来怎么圆？","hint":"要当天的、小的、真的。他出的主意再馊也回一句“这招我明天试试”，第二天告诉他结果。别顺口反问“你今天呢”。","art":"briefcase","tags":["糗事"]},{"id":"talk-038","type":"talk","sub":"老爸自曝","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","球场"],"mins":4,"title":"我也被喜欢的东西揍过","body":"我小时候迷过一样东西（一项运动、一种棋、一个游戏），自以为挺行，直到被一个人打得找不着北。我讲怎么输的，你来判：我当年到底菜在哪儿。","hint":"讲你怎么输的，输得越惨越好，别讲成逆袭。他判你哪儿菜都认，不辩解。不问他输给过谁，更不落到“贵在坚持”。","art":"chess"},{"id":"talk-039","type":"talk","sub":"老爸自曝","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":4,"title":"我小时候闯的最大的祸","body":"这事我爸妈当年都不知道全貌。我从头交代，你当法官：这要搁现在，该怎么罚我？","hint":"别讲成“你可别学”。他要是顺嘴说出自己闯过的小祸，今天听了就过去，不追究，不然以后就没下文了。","art":"flask"},{"id":"talk-040","type":"talk","sub":"老爸自曝","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","睡前"],"mins":3,"title":"我到现在还怕一样东西","body":"说出来别笑：我到现在还怕一样东西，打针、蟑螂、过山车、给陌生人打电话这一类的。我讲上回碰上它有多狼狈，你来评：哪种怕最没道理？","hint":"说一个真的、现在还怕的。他要是说了自己怕什么，回一句“这个我也是”就够，别安慰，别讲勇敢。","art":"lighthouse"},{"id":"talk-041","type":"talk","sub":"老爸自曝","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌"],"mins":3,"title":"我第一次自己花的大钱","body":"我攒了好久才买的第一样大件，结局挺惨：一周就坏了，或者被我妈没收了，就这一类。我讲完，换你报：你买过最值的和最亏的，各是什么？","hint":"他说的“最值”要是你当初反对买的，认个错：“那回是我看走眼了。”别转到“花钱要有计划”。","art":"pouch"},{"id":"talk-042","type":"talk","sub":"老爸自曝","format":"plain","audience":"all","for":"kid","scenes":["救场","饭桌","车上"],"mins":4,"title":"我当年觉得最酷的东西","body":"我那会儿觉得最酷的东西（一个发型、一双鞋、一句口头禅），现在看照片想把自己藏起来。你们现在什么最酷？20 年后哪样会变土？","hint":"有老照片就翻出来给他笑。他说的“酷”你听不懂就问，别评价“这有什么好看的”。请他预言：你现在哪样东西已经土了。","art":"camera"},{"id":"talk-043","type":"talk","sub":"篮球","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","饭桌","球场"],"mins":5,"title":"选秀开始，状元签归你","body":"历史上所有球星都在池子里，全是巅峰状态。你先挑，我第二个，轮流挑满 5 个人。最后比比谁的队赢。","more":"还想再来一轮：\n- 只能选现役的\n- 只能选后卫\n- 只能选你在直播或现场亲眼看过的\n- 每队必须有一个“为了好玩才选”的人","hint":"别用数据压他，他说谁强就按他的理由来。你选的人被他笑“过气”就对了。谁的队赢让他判，判你输就认。","art":"jersey","tags":["篮球","球星"]},{"id":"talk-044","type":"talk","sub":"篮球","format":"either","audience":"all","for":"kid","scenes":["救场","车上","球场"],"mins":3,"title":"手感和实力，你信哪个","body":"你是主教练。最后一攻，暂停时只能指定一个人出手。","either":{"a":"队里最准的，可他今天一直没进","b":"平时一般的，可他今天怎么投怎么有","ask":"要是没进，赛后记者追着问，你怎么答？"},"hint":"这题教练们自己也吵不完，没有标准答案。他选哪个都顺着问下去，别总结成“要相信队友”。你也选，选完跟他对着吵。","art":"hoop","tags":["篮球","关键球"]},{"id":"talk-045","type":"talk","sub":"篮球","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","球场","饭桌"],"mins":3,"title":"给篮球加一条新规则","body":"联盟请你当一天总裁，只能改一条。四分线？每队一次“复活”机会？进球必须庆祝？你加哪条？","more":"卡壳的时候借一条：\n- 每节可以喊一次“这球不算”\n- 吉祥物可以上场打 1 分钟\n- 教练必须亲自罚一个球\n- 垫底的球队下赛季可以多上一个人","hint":"他加的规则越离谱越好，接着问“那谁最占便宜”。下次去球场，就按他的新规则打一局。","art":"whistle","tags":["篮球"]},{"id":"talk-046","type":"talk","sub":"篮球","format":"plain","audience":"all","for":"kid","scenes":["救场","球场","周末"],"mins":2,"title":"请开始你的解说","body":"接下来 30 秒，你是现场解说，我干什么你解说什么：系鞋带、喝水、投丢一个球。中文英文随你，越夸张越好。","hint":"你负责演那个笨手笨脚的球员，动作放慢，给他留词儿。他损你，你就配合着演。别说“小点声”。","art":"scoreboard","tags":["篮球","解说"]},{"id":"talk-047","type":"talk","sub":"篮球","format":"plain","audience":"all","for":"kid","scenes":["救场","车上","球场"],"mins":3,"title":"球星让你一个条件","body":"跟你最喜欢的球星单挑，先到 5 分赢。他得答应你一个条件：蒙眼、只用左手、穿拖鞋……你提哪个才有戏？","hint":"别说“让什么你也赢不了”。陪他认真算：蒙眼加拖鞋够不够？然后轮到你俩：下次父子单挑，谁让谁、让什么，他定。","art":"sneaker","tags":["篮球","单挑"]},{"id":"talk-048","type":"talk","sub":"篮球","format":"plain","audience":"all","for":"kid","scenes":["救场","球场","车上","饭桌"],"mins":4,"title":"送你一支球队当老板","body":"队名、主场城市、球衣颜色、吉祥物、进场音乐，全由你定。我能在队里混个什么差事？","hint":"他安排你擦地板还是卖爆米花，都接。追问吉祥物长什么样、怎么出场。别问“主场为什么不选咱们这儿”。","art":"trophy","tags":["篮球"]},{"id":"talk-049","type":"talk","sub":"篮球","format":"plain","audience":"all","for":"kid","scenes":["球场","周末"],"mins":5,"title":"教练，我该练点啥","body":"你当我的教练。看我投几个球，只许提一条建议，再布置一个下次见面要检查的动作。","hint":"照他说的练，下次真让他检查。他说得不客气也别回嘴，更别反过来也给他提一条。","art":"ball","tags":["篮球"]},{"id":"talk-050","type":"talk","sub":"饭桌","format":"plain","audience":"all","for":"three","scenes":["饭桌","救场"],"mins":4,"title":"投票删掉一种菜","body":"全家 3 票，得票最多的那种菜从此在世界上消失。每人先提名，再拉票。香菜、胡萝卜、芹菜，谁最危险？","hint":"这是他合法吐槽饭菜的机会，别接“挑食不好”。你也提名一个你真不爱吃的，请妈妈替它辩护。","art":"pan","tags":["吃"]},{"id":"talk-051","type":"talk","sub":"饭桌","format":"plain","audience":"all","for":"three","scenes":["饭桌","救场","出游"],"mins":5,"title":"咱家拍成电影叫什么","body":"喜剧、灾难片还是纪录片？三个人各由谁来演？每人先给自己挑演员，再给另外两个人挑。最后定片名。","hint":"他给你挑的演员再离谱也认，别争“我哪有那么老”。片名他说了算。","art":"film","tags":["电影"]},{"id":"talk-052","type":"talk","sub":"饭桌","format":"plain","audience":"all","for":"three","scenes":["饭桌","救场"],"mins":5,"title":"今晚只许爆大人的料","body":"每人讲一件另一个大人干过的糗事：妈妈讲爸爸的，爸爸讲妈妈的，你两个都能讲。被爆的人不许辩解，只能补细节。","hint":"规则护着他：今晚谁也不许讲他的糗事，别破例。你被爆得越惨越好，带头笑。妈妈不乐意被讲，就只爆你一个。","art":"family","tags":["糗事"]},{"id":"talk-053","type":"talk","sub":"饭桌","format":"plain","audience":"all","for":"three","scenes":["饭桌","救场","出游"],"mins":5,"title":"最想再吃一遍的那顿饭","body":"不看价钱，只看记性：哪一顿、在哪儿、跟谁、吃的什么。三个人各说一顿，看有没有撞上同一顿的。","hint":"他说的要是路边摊或者一碗泡面，那就是答案，别补“那个不健康”。真撞上同一顿，找个周末再去吃一次。","art":"table","tags":["吃"]},{"id":"talk-054","type":"talk","sub":"饭桌","format":"plain","audience":"all","for":"three","scenes":["饭桌"],"mins":5,"title":"期末颁奖礼：奖越怪越好","body":"学期最后那几天找一顿饭，三个人互相颁奖。奖项现编，越怪越好：“年度最离谱借口奖”“最佳起床气奖”。每人给另外两人各颁一个，再给自己颁一个。得奖的人发表 10 秒感言。","more":"卡壳的时候借一个：\n- 最长洗澡时间奖\n- 年度“马上就来”奖\n- 最佳冷笑话奖\n- 找东西找得最久奖\n- 最快干饭奖\n\n年底、放长假之前，也能再办一届。","hint":"给他的奖要好笑、他自己也认，别夹带“进步奖”“最该早睡奖”这种话里有话的，更不碰分数。你领到的奖再损也上台致辞。妈妈的奖别拿家务开涮。","art":"trophy","tags":["期末","颁奖","假期"]},{"id":"talk-055","type":"talk","sub":"饭桌","format":"plain","audience":"all","for":"three","scenes":["饭桌","救场","出游"],"mins":3,"title":"定一个咱家的暗号","body":"一个词或者一个手势，只有咱仨懂。意思由你定：“快来救我”“这人话真多”“我想回家了”。今晚就试用。","hint":"意思让他定，哪怕是“我爸又开始了”。定了就真认：他在外面打出暗号，你照办，当场不问为什么。","art":"key","tags":["暗号"]},{"id":"talk-056","type":"talk","sub":"饭桌","format":"plain","audience":"all","for":"three","scenes":["饭桌","救场"],"mins":4,"title":"家庭群该改名了","body":"每人提一个新群名。要求：外人看了一头雾水，咱仨一看就笑。投票，不能投自己。赢的那个，吃完饭就改上。","hint":"他提的赢了就真改，至少挂一周。你提的那个要够土，给他垫底。别否决，除非真的不能让长辈看见。","art":"heart","tags":["家庭群"]},{"id":"talk-057","type":"talk","sub":"路上","format":"plain","audience":"all","for":"kid","scenes":["车上","救场","出游"],"mins":3,"title":"给路人配一句心里话","body":"等红灯的时候挑一个路人，或者旁边车里的人，替他配一句此刻的内心独白。一人配一个，看谁配得更像。","hint":"往处境上配（“完了，煎饼忘加蛋了”），不拿人的长相开涮。他要是往那边去，你换个路人接着配就行，不用讲道理。","art":"window","tags":["配音"]},{"id":"talk-058","type":"talk","sub":"路上","format":"plain","audience":"all","for":"kid","scenes":["车上","救场","出游"],"mins":3,"title":"导航换成你的声音","body":"你来配 3 句：前方右转、您已超速、您已偏离路线。用你觉得最欠揍的语气。配完，接下来 3 个路口归你播报（路还是按真的走）。","hint":"他播报得再欠揍也别嫌吵，笑着回一句“收到”。你也配一句，学你自己平时催他出门的语气，让他评像不像。","art":"compass","tags":["配音"]},{"id":"talk-059","type":"talk","sub":"路上","format":"plain","audience":"all","for":"kid","scenes":["车上","救场","饭桌"],"mins":3,"title":"今天听到最离谱的一句话","body":"不用是大事。今天听到的最好笑、最离谱或者最莫名其妙的一句话是什么？谁说的都行。我先来。","hint":"你先说一句你今天听到的（会上、电梯里）。他说“不知道”就过；连着 2 次“不知道”，就放歌，不再问。","art":"car"},{"id":"talk-060","type":"talk","sub":"路上","format":"plain","audience":"all","for":"kid","scenes":["车上","救场","出游"],"mins":3,"title":"一直往前开会到哪儿","body":"现在不拐弯、不回家，沿着这条路一直开，油管够。你想开到哪儿停？下车第一件事干什么？","hint":"别说“明天还得上学”。你也认真答一个。哪天真有半天空，就照他说的方向开一段，开到哪儿算哪儿。","art":"map"},{"id":"talk-061","type":"talk","sub":"路上","format":"plain","audience":"all","for":"kid","scenes":["车上","球场"],"mins":3,"title":"今天哪个球值得回放","body":"要是刚才那场有录像，你最想再看一遍哪个球？用慢动作讲给我听。","hint":"只问这一个。他讲，你听，最后说一句“我喜欢看你打球”就收。不提那个没传的球，不讲动作要领。","art":"ball","tags":["篮球"]},{"id":"talk-062","type":"talk","sub":"睡前","format":"plain","audience":"all","for":"kid","scenes":["睡前","救场"],"mins":1,"title":"今天是哪个表情","body":"不用解释，做出来或者说出来都行。我先来。","hint":"他比完，你点个头：“收到，晚安。”不问“怎么了”。想知道原因，等他哪天自己说。","art":"moon"},{"id":"talk-063","type":"talk","sub":"睡前","format":"plain","audience":"all","for":"kid","scenes":["睡前","救场"],"mins":2,"title":"明天有啥值得起床的","body":"一件小事就行：一顿早饭、一节体育课、一集更新。说不出来的话，我替你编一个。","hint":"你先说你的，哪怕是“明天食堂有红烧肉”。他说“没有”，就真给他编一个离谱的，然后关灯走人。","art":"sun"},{"id":"talk-064","type":"talk","sub":"睡前","format":"plain","audience":"all","for":"kid","scenes":["睡前","救场"],"mins":2,"title":"用打游戏的话说晚安","body":"比如“下线了”“存个档”“明天上号”。你来一句，我回一句，谁先词穷谁关灯。","hint":"你接不上最好：“呃……那就，关机？”让他赢，说完晚安就带上门，不追加一句“早点睡”。","art":"bed","tags":["游戏"]},{"id":"talk-065","type":"talk","sub":"睡前","format":"plain","audience":"all","for":"kid","scenes":["睡前","救场"],"mins":3,"title":"睡前一问，问啥都行","body":"你可以问我一个问题，什么都行，我照实答。答完就睡，我不反问。","hint":"真的照实答，真的不反问。他问工资、问你小时候挨没挨过打，能答就答；不能答就说“这个等你 16 岁”。他不问，就说晚安。","art":"question"},{"id":"talk-066","type":"talk","sub":"出差","format":"plain","audience":"dad","for":"kid","scenes":["出差","救场"],"mins":2,"title":"3 次机会，猜我在哪儿","body":"拍一张不露地标的照片（一碗面、一块路牌、酒店窗外），发过去：“3 次机会，猜我在哪儿。猜中了，回去给你带一样当地的怪东西。”","more":"换着发：\n- 一张今天拍的怪照片：“给它起个名，起得好我拿它当一天头像。”\n- 酒店里一样看不懂用途的东西：“你猜这是干嘛的？”\n- 当地的一块招牌：“这个字你认识吗？我不认识。”","hint":"发完就放下手机。他隔半天才回、只回一个字，都算接上了。不追一句“怎么不回”，更不顺手问作业。","art":"suitcase","tags":["消息","照片"]},{"id":"talk-067","type":"talk","sub":"出差","format":"plain","audience":"dad","for":"kid","scenes":["出差","救场"],"mins":2,"title":"这个我敢不敢吃","body":"拍一样你没吃过的当地东西，发过去：“这个我敢不敢吃？你说吃我就吃，吃完给你发我的表情。”","hint":"他说吃就真吃，把表情拍给他，难吃最好。全程不带“你吃了吗、写完了吗”这类话。","art":"cup","tags":["消息","吃"]},{"id":"talk-068","type":"talk","sub":"出差","format":"plain","audience":"dad","for":"kid","scenes":["出差","救场"],"mins":2,"title":"今天的数字是 7","body":"只发一个数：“今天的数字是 7。猜它数的是什么，3 次机会。”谜底挑没出息的：今天开了几个会，吃了几个包子，被人叫错几回名字。晚上揭晓。","more":"换着出：\n- 一个钟点：“14:37，猜我那会儿在干嘛。”\n- 一段路：“今天走了 9 公里，猜为什么。”\n- 他反过来给你出一个数，你也只有 3 次机会","hint":"谜底要真的、糗一点的，别挑“签了 3 个大单”。他乱猜就对了，最离谱的那个回一句“差一点”。发完放下手机，他不回不追，更不顺口问作业。","art":"question","tags":["消息","猜数"]},{"id":"talk-069","type":"talk","sub":"出差","format":"plain","audience":"dad","for":"kid","scenes":["出差","救场"],"mins":2,"title":"30 秒语音：今天的怪事","body":"每天同一个钟点，发一段不超过 30 秒的语音：“今天我碰上一件怪事：……你那边今天最好笑的一件事是啥？”","hint":"两篇写给出差父母的文章的经验（不是研究）：固定比发得多要紧。他不回，不连发，第二天同一时间照常来一条。在家的那位递一句“你爸发语音了”就够，不代问学习。","refs":[{"t":"Penn State Thrive：出差时怎样和孩子保持联系","u":"https://thrive.psu.edu/blog/how-parents-can-keep-in-touch-with-their-children-while-traveling/","lv":"专家意见"},{"t":"Art of Manliness：常出差的爸爸怎么做","u":"https://www.artofmanliness.com/people/fatherhood/how-to-be-a-better-dad-when-you-travel-for-business/","lv":"专家意见"}],"art":"clock","tags":["消息","语音"]},{"id":"talk-070","type":"talk","sub":"出差","format":"plain","audience":"dad","for":"kid","scenes":["出差"],"mins":2,"title":"回去头一个小时归你","body":"回程前一天发过去：“我周四到家。回去以后我的头一个空闲小时归你安排：打球、吃什么、看什么，你定，发我就行。”","hint":"他定什么就是什么，哪怕是“各玩各的”。回去只补这一小时，不开“爸爸对不起你”的长谈，也不靠一堆礼物补偿。","art":"door","tags":["消息"]},{"id":"trio-001","type":"trio","sub":"不用道具","format":"steps","audience":"all","for":"three","scenes":["饭桌","周末"],"mins":8,"title":"吹牛还是真本事","body":"每人说 3 件“我能做到”的事（比如单脚站满 1 分钟、用英文从 20 倒着数），2 件是真的，1 件是吹的。另外两人指出哪件是吹牛，被指的那件必须当场证明。","steps":["每人想 1 分钟：3 件当场能验证的事，2 件真的、1 件吹的","年纪最小的先说，说的时候保持扑克脸","另外两人商量，一起指出哪件是吹的","被指的那件当场演示：做到了说的人得 1 分，做不到猜的人各得 1 分","一圈下来，分最高的人今天免洗碗"],"hint":"你吹的那件要像真的，真的那 2 件要像吹的。妈妈演示时别起哄拆台。他没做到别笑，下一个就轮到你。","refs":[{"t":"传统聚会游戏“两真一假”的变体","lv":"经典"}],"art":"question","tags":["游戏","两真一假","饭桌"]},{"id":"trio-002","type":"trio","sub":"不用道具","format":"steps","audience":"all","for":"three","scenes":["救场","车上","饭桌"],"mins":5,"title":"二十个问题","body":"一个人在心里想一样东西：一个人、一种吃的、一个地方都行。另外两人轮流提问，只能得到“是”或“不是”。20 问之内猜中，算猜的人赢。","steps":["猜拳赢的人先想，想好了说“开始”","另外两人轮流问，每问一句掰一根手指","只能问用“是”或“不是”回答的问题","20 问之内猜中，猜的两人赢；否则出题的人赢","谁猜中，谁出下一题；没人猜中，出题的人再出一题"],"hint":"他想的东西你没听过（某个游戏角色、某个球员），就老实认输，再请他讲讲。别问“是不是跟学习有关”。","refs":[{"t":"传统猜谜游戏“二十个问题”","lv":"经典"}],"art":"brain","tags":["游戏","车上"]},{"id":"trio-003","type":"trio","sub":"不用道具","format":"steps","audience":"all","for":"three","scenes":["救场","饭桌","车上"],"mins":5,"title":"幸好，不幸的是","body":"三个人合编一个故事，每人一次只说一句。规则：一句必须用“不幸的是”开头，下一句必须用“幸好”开头，轮着来，越编越歪。","steps":["年纪最小的说第一句：主角是谁，在哪儿","下一个人用“不幸的是……”接","再下一个人用“幸好……”接","转满 3 圈，轮到谁谁给故事收尾","三个人一起给这个故事起片名"],"hint":"别把故事往“有意义”的方向带，越离谱越好。他把你编成故事里的倒霉蛋，你就顺着演。想换个编法，「工具箱」里有「故事骰子」。","refs":[{"t":"传统故事接龙游戏","lv":"经典"}],"art":"book","tags":["游戏","故事接龙"]},{"id":"trio-004","type":"trio","sub":"不用道具","format":"steps","audience":"all","for":"three","scenes":["饭桌","车上"],"mins":10,"title":"不许说那个字","body":"一个人心里选一个词，用嘴描述给另外两人猜，但不能说出这个词里的任何一个字，也不许比划。谁先猜中，谁和出题人各得 1 分。","steps":["出题人想一个词：一样东西、一个人、一部片子","开始描述，不许说出词里的任何一个字","另外两人抢答：先猜中的人和出题人各得 1 分","说漏了嘴，这题作废，出题人倒扣 1 分","每人出 3 题，分最低的收拾桌子"],"hint":"他出的词可能是你不懂的梗，猜不中就问那是什么，别说“这谁猜得到”。妈妈猜中了，别说是你让的。","art":"chat","tags":["游戏","我说你猜"]},{"id":"trio-005","type":"trio","sub":"不用道具","format":"steps","audience":"all","for":"three","scenes":["饭桌"],"mins":10,"title":"10 分钟，只许说一个字","body":"接下来 10 分钟，三个人每次开口只能说一个字。“吃”“好”“盐”“嗯”都行，“不要”就算犯规。可以用手指，可以用表情。","steps":["定一个 10 分钟的闹钟，手机扣在桌上","每次开口只说一个字，其余靠手势和表情","谁一口气说了 2 个字，另外两人一起指他","犯规一次记一笔","闹钟响，犯规最多的人收碗"],"hint":"你多半是犯规最多的那个，认罚。别趁这 10 分钟用单字问他正事。","art":"hourglass","tags":["游戏","饭桌"]},{"id":"trio-006","type":"trio","sub":"不用道具","format":"steps","audience":"all","for":"three","scenes":["救场","饭桌","车上"],"mins":5,"title":"逢七拍手","body":"三个人轮流报数，从 1 开始。遇到带 7 的数和 7 的倍数不许出声，只能拍一下手。谁说漏了嘴或者拍错了，记一笔，从头再来。","steps":["猜拳输的人从“1”开始，三个人轮流报数","7、14、17、21……只拍手不出声；开车的人不拍手，改喊“过”","出错的人记一笔，由他重新从“1”开始","越数越快才好玩","谁先记满 3 笔，谁去倒垃圾"],"hint":"故意数快一点才好玩。你出错了别找理由。数到 50 还没人错，就改成“逢三拍手”。","refs":[{"t":"传统报数游戏“逢七过”","lv":"经典"}],"art":"highfive","tags":["游戏","报数"]},{"id":"trio-007","type":"trio","sub":"固定节目","format":"steps","audience":"all","for":"three","scenes":["周末","饭桌"],"mins":90,"title":"周五主理人，每周换届","body":"周五晚上，从晚饭到 9 点归三个人。做主的人每周轮换：吃什么、饭后看什么片或者玩什么，全由这一位说了算，另外两人不许否决。9 点散场，各回各屋。","steps":["今天就抽签，定出第一任“周五主理人”","周五白天，主理人在群里宣布节目和晚饭：点外卖、下馆子，还是自己下厨","吃饭时 3 部手机放到玄关","饭后的片子或游戏照主理人定的来","在日历上写下：下周轮到谁"],"hint":"他选的片子你不爱看也陪着看完，别中途刷手机，更别否决。轮到妈妈做主，你和他同样配合。9 点准时散场，别拖堂。第一任抽不出来，用「转盘」那张。","refs":[{"t":"Houston Family Magazine · Kathryn Streeter","u":"https://houstonfamilymagazine.com/family-life/how-our-friday-night-pizza-night-helps-us-connect-with-our-growing-kids","lv":"个案"},{"t":"Austin Kleon 的博客（2026-01-06）","u":"https://austinkleon.com/2026/01/06/lessons-learned-from-movie-night/","lv":"个案"}],"art":"sofa","tags":["周五","电影","轮流做主"]},{"id":"trio-008","type":"trio","sub":"固定节目","format":"steps","audience":"all","for":"three","scenes":["周末","出游"],"mins":180,"title":"4 个周末，一人领半天","body":"一个月 4 个周末：三个人各认领一个周末的半天来做主，第 4 个周末留空，谁也不安排。做主的人定去哪儿、干什么，另外两人这半天全程加入，不看手机。","steps":["拿出日历，三个人各认领一个周末的半天","一起定一个花费上限，人人适用","做主的人提前 2 天宣布计划","当天另外两人全程参与，手机只拍照","第 4 个周末留空：各玩各的"],"hint":"轮到他做主，哪怕是“你们陪我在家打一下午游戏”也照办。轮到你做主，别排成“有教育意义”的行程。","refs":[{"t":"伊利诺伊大学推广部博客","u":"https://extension.illinois.edu/blogs/family-files/2026-05-26-be-intentional-family","lv":"专家意见"}],"art":"calendar","tags":["周末","轮流做主","假期"]},{"id":"trio-009","type":"trio","sub":"固定节目","format":"steps","audience":"all","for":"three","scenes":["周末"],"mins":10,"title":"三个人的点子罐","body":"每人写 3 张纸条，每张一件“想拉上另外两人干的事”，折好扔进罐子。哪个周末没安排就抽一张：抽到谁写的，谁当这半天的头儿，另外两人不许讨价还价。","steps":["找一个空罐子或空盒子，裁 9 张纸条","每人写 3 张，背面签名，不许偷看别人的","写半天之内能做完的事，离谱一点也行","没安排的周末抽一张：抽到谁写的，谁当这半天的头儿","做完的那张写上日期，贴到冰箱上留念"],"need":["一个空罐子","纸条和笔"],"hint":"他写“吃三顿烧烤”，抽到了就去吃，别偷偷换掉。你写的 3 张里别夹带“参观完写观后感”这种。","refs":[{"t":"加拿大地方报纸 Western Wheel 的一篇家长专栏（原网页现已打不开）","lv":"个案"},{"t":"Harvard Health 的家庭资料","u":"https://www.health.harvard.edu/mindscape/for-parents-and-caregivers/building-a-strong-family-system/building-positive-family-routines","lv":"专家意见"}],"art":"pouch","tags":["点子罐","抽签"]},{"id":"trio-010","type":"trio","sub":"固定节目","format":"steps","audience":"all","for":"three","scenes":["周末","饭桌"],"mins":10,"title":"周日 10 分钟，抢下周档期","body":"周日晚上，三个人抢下周的档期：谁哪天不在家、哪天打球、周五谁做主。先报先占，写上日历就不许反悔。最不爱开会的那位掐表，10 分钟一到，喊“收工”。","steps":["掐表的人定 10 分钟倒计时，桌上只留一部手机看日历","每人报下周的 2 个档期，先报先占","打球的时间和一个备用日写进日历，写上了大人不许放鸽子","两个档期撞车，猜拳解决；还不服，留到下周日再战","倒计时一响就收工，没排完的不补"],"hint":"这不是成绩总结会，分数和排名一个字都不提。你先报自己哪天不在家。写进日历的球约，你就别放鸽子。","refs":[{"t":"Bruce Feiler 的个人通讯","u":"https://brucefeiler.substack.com/p/three-questions-to-ask-your-children-21-09-17","lv":"个案"},{"t":"澎湃号 · “我爱小黑鱼”","u":"https://www.thepaper.cn/newsDetail_forward_13509413","lv":"个案"},{"t":"北京号（北京日报客户端）的一份官方材料","u":"https://peking.bjd.com.cn/content/s67d7e082e4b08edd28f6584d.html","lv":"官方"}],"art":"clock","tags":["周日","日历","档期"]},{"id":"trio-011","type":"trio","sub":"固定节目","format":"steps","audience":"all","for":"three","scenes":["周末"],"mins":10,"title":"每人教一招没用的绝活","body":"每人教一招“没什么用但有点帅”的：指尖转球、转笔、打响指、弹舌、一句绕口令都算。限时 3 分钟，另外两人当场学，学得最慢的那位单独再表演一遍。","steps":["每人现在就报出自己要教的那一招，越没用越好","抽签定顺序，每人 3 分钟，手机倒计时","当学生的两个人必须真的上手","时间到，教的人指认：谁学得最慢，谁单独再来一遍","三招学完，三个人连起来表演一轮"],"hint":"他教的时候你就是学生，学不会就多试几次。妈妈教的时候同样认真。你学得最慢就老实单独表演，别找理由。","refs":[{"t":"AZ Big Media 的一篇汇总","u":"https://azbigmedia.com/lifestyle/14-ways-to-get-teenagers-excited-to-participate-in-summer-family-activities/","lv":"个案"}],"art":"bulb","tags":["每人教一样","绝活"]},{"id":"trio-012","type":"trio","sub":"动手","format":"steps","audience":"all","for":"three","scenes":["周末"],"mins":50,"title":"一顿饭，抽签分 3 份","body":"一顿饭拆成 3 份：主食、菜、饮品加摆桌。抽签决定谁管哪样，各干各的，40 分钟后同时上桌。","steps":["写 3 张签：主食、菜、饮品加摆桌，抽","各用 5 分钟想好做什么，食材从冰箱里先到先得","做什么、怎么做，抽到的人说了算；动刀、开火那几下由大人代劳，照指挥办","40 分钟后同时上桌，各自报菜名","三个人同时伸手指：指向今天最好吃的那一样，不许指自己"],"hint":"他抽到要开火的那份，你只当他的手：切多大、炒多久听他的，别替他调味。妈妈做的那份别当成理所当然，好吃就指她的。","refs":[{"t":"光明网科普 · 王葵（2026-09-11）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"}],"art":"pan","tags":["做饭","分工"]},{"id":"trio-013","type":"trio","sub":"动手","format":"steps","audience":"all","for":"three","scenes":["周末","出游"],"mins":30,"title":"一人一个颜色","body":"出门走一圈。猜拳赢的人给另外两人指定颜色，越难找越好。一路上只拍自己那种颜色的东西，谁先拍满 5 样谁喊停，拍得最少的人负责把照片拼成一张图。","steps":["猜拳，赢的人给另外两人指定颜色，自己最后挑","定路线：绕小区一圈，或者去趟公园","各拍各的颜色，同一样东西不能拍两次；先拍满 5 样的人喊停","回家把照片发到家里的群","拍得最少的人负责拼图，赢家的颜色放正中间"],"need":["各自的手机"],"hint":"谁拍得慢就等谁，别催“差不多得了”。他给你指定了最难找的颜色，认了。拼出来再丑，也拿它当一周的群头像。","art":"camera","tags":["拍照","散步"]},{"id":"trio-014","type":"trio","sub":"动手","format":"steps","audience":"all","for":"three","scenes":["周末"],"mins":30,"title":"斗地主，输了贴纸条","body":"三个人正好凑一桌。每打完一局，输的一方脸上贴纸条，贴哪儿由赢家定。5 局之后，纸条最多的人顶着它们去倒垃圾。","steps":["找一副扑克和一沓便利贴","有人不会，先明牌打一局“教学局”","每局结束贴纸条：地主输了挨 2 张，农民输了各挨 1 张，贴哪儿赢家定","贴上了不许自己撕","5 局后数纸条，最多的人顶着去倒垃圾"],"need":["一副扑克","一沓便利贴"],"hint":"他往你脑门正中贴，你就顶着。正常打，不用让牌，他看得出来；也别在牌桌上讲“牌要这么记”。只贴纸条，不赌钱。","refs":[{"t":"光明网科普 · 王葵（2026-09-11）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"}],"art":"cards","tags":["斗地主","扑克"]},{"id":"trio-015","type":"trio","sub":"动手","format":"steps","audience":"all","for":"three","scenes":["周末"],"mins":120,"title":"捏个杯子，看谁的漏水","body":"找一家能体验的陶艺店，三个人都是新手，各捏一个杯子。不用互相帮忙，也不用一直说话。烧好取回来倒水验货：谁的漏了、谁的最歪，谁请客。","steps":["现在就查附近能体验一次的陶艺店，约个周末","三个人都上手，谁也不许只当观众","各捏各的，不许替别人修","捏完在杯底刻上名字和日期","取回来当场倒水验货，漏的、最歪的请客；再抽签，每人用别人捏的那个"],"hint":"三个人都得动手，你别躲去拍照，也别劝妈妈“你在旁边看就行”。他捏歪了别上手扶正，歪的才认得出是谁的。","refs":[{"t":"光明网科普 · 王葵（2026-09-11）","u":"https://kepu.gmw.cn/2026-09/11/content_38996770.htm","lv":"专家意见"},{"t":"Aron 等（2000），Journal of Personality and Social Psychology","u":"https://pubmed.ncbi.nlm.nih.gov/10707334/","lv":"实证"}],"art":"cup","tags":["陶艺","新手"]},{"id":"trio-100","type":"trio","sub":"抽签","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","周末","出游"],"mins":1,"title":"点兵点将：谁先来","body":"谁先出题、谁先投、谁去开门拿外卖。每人按住一根手指，2 秒后见分晓。","widget":"picker","params":{"title":"谁先来？","names":["爸爸","妈妈","孩子"]},"hint":"抽到你就认，别耍赖，也别喊“再来一次”。要定“今晚谁说了算”，换「转盘」那张。"},{"id":"trio-101","type":"trio","sub":"一部手机","format":"widget","audience":"all","for":"three","scenes":["周末","饭桌","出游"],"mins":10,"title":"灵魂画手请就位","body":"按住偷看一个词，60 秒内画出来，另外两个人抢着猜。猜对了，画的和猜的各得 1 分。画得越离谱，笑得越大声。","widget":"sketch","params":{"category":"mix","players":3,"seconds":60},"cta":"开始画","hint":"你画得烂是加分项，大方亮出来让他们笑。他画的时候只管猜，不评价画得像不像。","art":"pencil","tags":["你画我猜","画画","三个人"]},{"id":"trio-102","type":"trio","sub":"抽签","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","周末","出游"],"mins":1,"title":"今晚谁说了算","body":"选电影、定晚饭、谁洗碗、谁坐副驾——吵不出结果的事，交给转盘。指针停在谁那儿，就是谁。","widget":"wheel","params":{"preset":"who","title":"今晚谁说了算？"},"cta":"转一下","hint":"转之前三个人先说好：转到谁就是谁。转到你也认；转到他，就真的让他做一回主。","art":"target","tags":["转盘","抽签","谁来","三个人"]},{"id":"trio-103","type":"trio","sub":"抽签","format":"widget","audience":"all","for":"three","scenes":["救场","车上","周末"],"mins":2,"title":"“随便”不是一道菜","body":"先一起把今晚吃不了的删掉，把想吃的加进去，然后转。转到什么吃什么——转到「爸爸下厨」也得认。","widget":"wheel","params":{"preset":"dinner"},"cta":"转一下","hint":"转出来的就照做，别临时改口说“太油了”。实在做不到的那几项，转之前就删掉。","art":"pizza","tags":["转盘","吃什么","晚饭","三个人"]},{"id":"trio-104","type":"trio","sub":"抽签","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","周末","出游"],"mins":2,"title":"输的人，过来转一下","body":"刚才那局谁输了？来领一个小惩罚：用播音腔读说明书、慢动作表演绝杀、太空步滑过客厅……运气好能转到免罚金牌。","widget":"wheel","params":{"preset":"forfeit"},"cta":"领惩罚","hint":"你输了就认认真真演，越投入越好笑。他实在不想做的那一项别硬逼，让他再转一次。","art":"whistle","tags":["转盘","惩罚","搞怪","三个人"]},{"id":"trio-105","type":"trio","sub":"一部手机","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","车上","出游"],"mins":5,"title":"谁最可能把遥控器放进冰箱","body":"屏幕出一句「谁最可能……」，三个人轮流悄悄投票，可以投自己。全部投完一起揭晓，看谁众望所归。","widget":"whois","params":{"players":3,"pack":"daily"},"cta":"开始投票","hint":"被投成“最可能”的那位，认了，再讲一个真事。票投到你头上时别解释，先笑。","art":"family","tags":["投票","糗事","三个人"]},{"id":"trio-106","type":"trio","sub":"一部手机","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","睡前","出游"],"mins":5,"title":"外星人会选谁当地球代表","body":"脑洞版「谁最可能」：谁能在荒岛上活到最后？谁当了特工第一天就说漏嘴？悄悄投票，一起揭晓。","widget":"whois","params":{"players":3,"pack":"wild"},"cta":"开始投票","hint":"别总让着他，也别总投他。当选的人可以用一句话为自己辩护；你当选了，就带头辩。","art":"planet","tags":["投票","脑洞","假如","三个人"]},{"id":"trio-107","type":"trio","sub":"一部手机","format":"widget","audience":"all","for":"three","scenes":["救场","车上","饭桌","睡前","出游"],"mins":5,"title":"这 6 样东西，编得圆吗","body":"掷出 6 颗骰子：有人、有地方、有几样东西，还有一个意外。每人说一句，全都得编进同一个故事里，谁也不许跳过。","widget":"storydice","params":{"theme":"any","count":6},"cta":"掷骰子","hint":"故事跑偏、越编越离谱，都别往回拉。你那一句尽量短，把最好玩的转折留给他。","art":"dice","tags":["故事","接龙","骰子","三个人"]},{"id":"trio-108","type":"trio","sub":"一部手机","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","车上","出游"],"mins":3,"title":"给你们 2 分钟","body":"随机抽一条 2 分钟挑战：说出 15 种球类运动、从 A 到 Z 接英文单词、三个人合作数到 30……这条不想做，就换一条。","widget":"timer","params":{"seconds":120},"cta":"抽一条","hint":"你和他们一起做，别当裁判。做不到的那条认输就行，不找理由；时间到就收，不加时。","art":"stopwatch","tags":["计时","挑战","倒计时","三个人"]},{"id":"trio-109","type":"trio","sub":"一部手机","format":"widget","audience":"all","for":"three","scenes":["救场","饭桌","睡前","周末"],"mins":3,"title":"1 分钟，谁都不许笑","body":"一个人板着脸坐好，另外两个人想尽办法逗：鬼脸、冷笑话、怪声音都行，就是不许碰到他。撑满 1 分钟算赢，然后换人。","widget":"timer","params":{"seconds":60,"challenge":"1 分钟不许笑：一个人憋住，另外两个人负责逗，不许碰到他"},"cta":"开始憋","hint":"你先当那个不许笑的，输得越快越好。轮到你逗他时，拿自己的糗事开刀，别拿他的。","art":"hourglass","tags":["计时","挑战","不许笑","三个人"]}];
